(1503,2683,'assertion','from playwright.sync_api import Page, expect

def test_new_length_validation(page: Page):

    # locate row 1 and row 2 Length cells
    row1_length_locator = page.locator(\'[data-rowindex="0"] [data-field="productLength"]\')
    row2_length_locator = page.locator(\'[data-rowindex="1"] [data-field="productLength"]\')

    # extract values and convert to int
    row1_length = int(row1_length_locator.text_content().strip())
    row2_length = int(row2_length_locator.text_content().strip())

    expected_length = row1_length + row2_length

    # locate New Length input
    new_length_input = page.locator(\'input[name="WeldingNewLength"]\')

    # strict assertion
    expect(new_length_input).to_have_value(str(expected_length))',NULL,'passed','2026-05-03 08:30:20','2026-08-24 22:50:08','','53868dd1-c961-44a2-8c06-d7aa639253e8'),
