for _ in range(20):
    if header.get_attribute("aria-sort") == "descending":
        break
    header.hover()
    header.click(force=True)

id_cells = page.locator("[role=\'gridcell\'][data-field=\'shipmentId\']")

# Get count safely
count = id_cells.count()
assert count > 0, f"No Transit IDs found. Count = {count}"

# Pick the first non-empty value
