(1980,3159,'assertion','def test_search_customer_results_equal(page):

    # Get customer name from textbox field
    customer_name = page.locator(\'role=textbox[name="Customer Name"]\').input_value().strip()

    # Verify searched customer name is visible
    expect(page.locator(f"text={customer_name}")).to_be_visible()

    # Verify every row contains the same customer name
    rows = page.locator("role=row")
    row_count = rows.count()

    for i in range(row_count):
        row = rows.nth(i)

        # Customer Name column
        customer_cell = row.locator("role=gridcell").nth(4)

        expect(customer_cell).to_have_text(customer_name)',NULL,'passed','2026-05-05 10:13:05','2026-08-23 06:20:25','','2f80044d-abf8-488a-ac6b-4f05b412dc17'),
