(2196,3440,'custom','import re

def to_number(txt):
    txt = (txt or "").replace(",", "").strip()
    m = re.search(r"[-+]?\\d+(?:\\.\\d+)?", txt)
    return float(m.group()) if m else 0.0

grid = page.locator("div[role=\'grid\']").filter(
    has=page.locator("[data-field=\'actualYardStockPCS\']")
).first

scroller = grid.locator(".MuiDataGrid-virtualScroller")

found = False

for _ in range(50):

    rows = grid.locator("div[role=\'row\'][data-rowindex]")

    for i in range(rows.count()):

        try:
            row = rows.nth(i)

            actual_pcs = to_number(
                row.locator(
                    "[data-field=\'actualYardStockPCS\']"
                ).text_content(timeout=2000)
            )

            stock_so_pcs = to_number(
                row.locator(
                    "[data-field=\'StockOnSoPCS\']"
                ).text_content(timeout=2000)
            )

            print(actual_pcs, stock_so_pcs)

            if actual_pcs > 30 and stock_so_pcs == 0:

                print("MATCH FOUND")

                row.locator(
                    "[data-field=\'edit\'] button[title=\'Edit\']"
                ).click(force=True)

                found = True
                break

        except:
            continue

    if found:
        break

    scroller.evaluate("(el) => el.scrollTop += 1500")
    page.wait_for_timeout(1000)

assert found, \\
