    re.compile(r"^Cutting Detail Bom#\\s*\\d+\\s*$"),
    timeout=30000
)

# Title validation
title_text = title.inner_text().strip()

assert re.search(
    r"^Cutting Detail Bom#\\s*\\d+\\s*$",
    title_text
), f"Unexpected title: {title_text}"

# Length cells directly
