(2339,3584,'custom','from playwright.sync_api import sync_playwright, expect
def scroll_grid_to_cell(page, scroller_selector, cell_locator, max_steps=30, step=200):
    scroller = page.locator(scroller_selector)
    for _ in range(max_steps):
        if cell_locator.count() > 0:
            try:
                cell_locator.scroll_into_view_if_needed(timeout=500)
                if cell_locator.is_visible():
                    return
            except Exception:
                pass
        scroller.evaluate(f"el => el.scrollLeft += {step}")
        page.wait_for_timeout(100)
    raise AssertionError(f"Cell not found after scrolling {max_steps * step}px")

cell = page.locator("//div[@data-id=\'0\']//*[@data-field=\'unitPrice\']")
scroll_grid_to_cell(page, ".MuiPaper-elevation .MuiDataGrid-virtualScroller", cell)',NULL,'passed','2026-05-07 09:51:55','2026-08-31 10:06:24','','a341d818-e464-45c0-ae3d-1576ee2b6ddb'),
