(2480,3663,'assertion','from playwright.sync_api import expect

# Dynamic value from your framework/util
expected_shipment = str(get_var("bol_number"))

scroller = page.locator(".MuiDataGrid-virtualScroller")
shipment_cell = page.locator(
    f"div[role=\'gridcell\'][data-field=\'shipmentId\'][title=\'{expected_shipment}\']"
)

for _ in range(40):
    if shipment_cell.count() > 0:
        in_view = scroller.evaluate(
            """(el, cell) => {
                if (!cell) return false;
                const s = el.getBoundingClientRect();
                const c = cell.getBoundingClientRect();
                return c.left >= s.left && c.right <= s.right;
            }""",
            shipment_cell.first.element_handle(),
        )
        if in_view:
            break

    at_end = scroller.evaluate(
        """el => {
            const max = el.scrollWidth - el.clientWidth;
            el.scrollLeft = Math.min(el.scrollLeft + 300, max);
            return el.scrollLeft >= max - 1;
        }"""
    )
    page.wait_for_timeout(100)

    if at_end and shipment_cell.count() == 0:
        raise AssertionError(
            f"shipmentId column with value \'{expected_shipment}\' not found after scrolling to end"
        )

# Assert the shipment value matches
expect(shipment_cell.first).to_have_text(expected_shipment)
',NULL,'passed','2026-05-08 02:34:24','2026-08-30 11:59:39','','03067f77-454c-4a56-936d-9d5a073ab4c7'),
