    if found:
        break


    # ============================================================
    # Scroll down
    # ============================================================

    scroller.evaluate(
        "(el) => { el.scrollTop += 1500; }"
    )

    page.wait_for_timeout(1000)


# ============================================================
# Final assertion
# ============================================================

assert found, (
    "No row found where "
