(2756,3943,'custom','import re
from playwright.sync_api import Page, Locator, expect

def transit_grid(page: Page) -> Locator:
    return page.get_by_role("grid").first


def row_by_po(grid: Locator, po_number: str) -> Locator:
    # PO # cell: data-field="purchaseOrderId"
    cell = grid.locator(
        f\'div[role="row"][data-id] [data-field="purchaseOrderId"][title="{po_number}"]\'
    )
    expect(cell).to_be_visible(timeout=30_000)
    return grid.locator(\'div[role="row"][data-id]\').filter(has=cell).first


def assert_shipment_status_intransit_received(
    page: Page,
    *,
    po_number: str,
    grid: Locator | None = None,
) -> None:
    g = grid if grid is not None else transit_grid(page)
    expect(g).to_be_visible(timeout=30_000)

    row = row_by_po(g, po_number)

    # Optional: search result me kam se kam ek data row
    expect(g.locator(\'div[role="row"][data-id]\')).to_have_count(
        1, timeout=15_000
    )  # agar hamesha exactly 1 ho; warna comment out karo

    po_cell = row.locator(\'[data-field="purchaseOrderId"]\')
    expect(po_cell).to_contain_text(re.compile(re.escape(po_number)))

    status_cell = row.locator(\'[data-field="shipmentStatusDesc"]\')
    expect(status_cell).to_be_visible(timeout=10_000)

    # Status icon button ka tooltip / accessible name
    status_btn = status_cell.locator(\'button[title="Intransit Received"]\')
    expect(status_btn).to_be_visible(timeout=10_000)
    expect(status_btn).to_have_attribute("title", "Intransit Received")


