(2878,3984,'read','import re
from playwright.sync_api import expect

# Locate the correct Manage Shipment container
section = page.locator("div.MuiStack-root").filter(
    has_text="Planned In Shipment"
).first

expect(section).to_be_visible(timeout=15_000)

# Get Planned In Shipment text
shipment_text = section.locator(
    "span:has-text(\'Planned In Shipment\')"
).inner_text().strip()

# Extract shipment ID
m = re.search(r"Planned In Shipment\\s+(\\d+)", shipment_text)

if not m:
    raise AssertionError(
        f"Could not parse planned shipment id from: {shipment_text!r}"
    )

planned_shipment_id = m.group(1)

set_var("planned_shipment_id", planned_shipment_id)',NULL,'passed','2026-05-12 02:11:27','2026-08-27 02:08:44','','21356d87-2d0d-45b0-9dae-70edf6d5a0a9'),
