(3235,4467,'custom','from playwright.sync_api import Page, expect

def test_verify_supplier_name_in_rows(page: Page) -> None:

    # The table header \'Supplier Name\' should be visible
    expect(page.locator(\'text=Supplier Name\')).to_be_visible()

    # All data rows (excluding header)
    rows = page.locator(\'role=row\')
    expect(rows).to_have_count_greater_than(0)

    # Verify that no row contains an empty Supplier Name cell
    empty_cells = rows.locator(\'gridcell\', has_text=\'\')
    expect(empty_cells).to_have_count(0)

    # Verify each data row has a non‑empty Supplier Name cell
    # Skip the first row (header)
    row_count = rows.count()
    for i in range(1, row_count):
        row = rows.nth(i)
        supplier_cell = row.locator(\'gridcell\', nth=2)
        expect(supplier_cell).to_be_visible()
        expect(supplier_cell).to_have_text(r\'\\S+\', re=True)','def test_search_customer_results_equal(page):

    # Get customer name from textbox field
    customer_name = page.locator(\'role=textbox[name="Supplier Name"]\').input_value().strip()

    # Verify searched customer name is visible
    expect(page.locator(f"text={customer_name}")).to_be_visible()

    # Verify every row contains the same customer name
    rows = page.locator("role=row")
    row_count = rows.count()

    for i in range(row_count):
        row = rows.nth(i)

        # Customer Name column
        customer_cell = row.locator("role=gridcell").nth(2)

        expect(customer_cell).to_have_text(customer_name)','passed','2026-05-15 03:32:12','2026-08-24 11:02:04','','8d22d5ef-e5cd-404d-ab7d-ac0ba2ccf3e9'),
