(3662,4949,'assertion','from playwright.sync_api import expect

# ---------- QUANTITY ORDERED ----------

qty_cell = page.locator(\'[data-rowindex="0"] [data-field="quantity"]\')

old_qty = float(qty_cell.inner_text().strip())
new_qty = f"{old_qty + 1:.2f}"

print(f"Quantity Ordered : {old_qty:.2f} → {new_qty}")

expect(qty_cell).to_have_text("1.00")

qty_cell.click()
qty_input = qty_cell.locator("input")

qty_input.fill(new_qty)
page.keyboard.press("Tab")

expect(qty_cell).to_have_text(new_qty)

print(f"PASS → Quantity updated to {new_qty}")


# ---------- UNIT PRICE ----------

price_cell = page.locator(\'[data-rowindex="0"] [data-field="unitPrice"]\')

old_price = float(price_cell.inner_text().strip().replace(",", ""))
new_price = old_price + 1

new_price_input = f"{new_price:.2f}"
new_price_display = f"{new_price:,.2f}"

print(f"Unit Price : {old_price:.2f} → {new_price_display}")

expect(price_cell).to_have_text("999.00")

price_cell.click()
price_input = price_cell.locator("input")

price_input.fill(new_price_input)
page.keyboard.press("Enter")

expect(price_input).not_to_be_visible()
expect(price_cell).to_have_text(new_price_display)

print(f"PASS → Unit Price updated to {new_price_display}")','1','passed','2026-05-19 04:46:11','2026-08-26 23:32:01','Quantity Ordered : 1.00 → 2.00
PASS → Quantity updated to 2.00
Unit Price : 999.00 → 1,000.00
PASS → Unit Price updated to 1,000.00',NULL),
