(3687,4976,'assertion','from datetime import datetime
from playwright.sync_api import sync_playwright

BASE_URL = "https://ims.sws.pipe-piling.com/dashboard/ims-invoice/display-shipment/"

SHIPMENT = {
    "bol": "1085494",
    "order": "MTL15498",
    "po": "110023-R",
    "project": "JOB STATUIN-12",
    "from_date": "01/02/2024",
    "to_date": "05/18/2026",
    "customer": "Etpo Geodex Inc",
}


def fill_filter(page, label, value):
    page.get_by_label(label).fill(value)


def click_search(page):
    page.get_by_role("button", name="Search").click()
    page.wait_for_load_state("networkidle")


def get_cell(page, row_index, field):
    row = page.locator(".MuiDataGrid-row").nth(row_index)
    return row.locator(f\'[data-field="{field}"]\').inner_text().strip()


def verify_shipment_row(page):
    rows = page.locator(".MuiDataGrid-row")
    assert rows.count() == 1, "Expected exactly 1 search result row"

    assert get_cell(page, 0, "shipmentId") == SHIPMENT["bol"], "BOL # mismatch"
    assert get_cell(page, 0, "primaryOrderId") == SHIPMENT["order"], "Order # mismatch"
    assert get_cell(page, 0, "poNumber") == SHIPMENT["po"], "PO # mismatch"
    assert get_cell(page, 0, "jobName") == SHIPMENT["project"], "Project Name mismatch"

    customer = get_cell(page, 0, "customerName").replace(" ", "")
    assert SHIPMENT["customer"].replace(" ", "") in customer, "Customer Name mismatch"

    shipment_date = datetime.strptime(get_cell(page, 0, "createdDate"), "%m/%d/%Y")
    from_date = datetime.strptime(SHIPMENT["from_date"], "%m/%d/%Y")
    to_date = datetime.strptime(SHIPMENT["to_date"], "%m/%d/%Y")
    assert from_date <= shipment_date <= to_date, "Shipment Date not in range"

    print("PASS: Search results contain shipment matching entered criteria.")


def main():
    with sync_playwright() as p:
        browser = p.chromium.launch(headless=False)  # headless=True for CI
        page = browser.new_page()
        page.goto(BASE_URL)

        # TODO: Add login here if page asks for sign-in
        # page.fill("#username", "your_user")
        # page.fill("#password", "your_pass")
        # page.click("button[type=\'submit\']")

        page.get_by_role("grid").wait_for(state="visible")

        # Fill all search filters
        fill_filter(page, "BOL #", SHIPMENT["bol"])
        fill_filter(page, "Order #", SHIPMENT["order"])
        fill_filter(page, "PO #", SHIPMENT["po"])
        fill_filter(page, "Project Name", SHIPMENT["project"])
        fill_filter(page, "From Date", SHIPMENT["from_date"])
        fill_filter(page, "To Date", SHIPMENT["to_date"])

        click_search(page)
        verify_shipment_row(page)

        browser.close()


if __name__ == "__main__":
    main()',NULL,'passed','2026-05-19 05:48:23','2026-08-27 02:12:02','','8f160496-1c38-4cf8-bb02-f180c2b83161'),
