(3737,5034,'custom','def test_generate_invoice_popup(page):
    # Click the Generate Invoice button
    page.click("text=Generate Invoice")

    # Verify that the small popup screen appears
    expect(page.locator("text=Preview Invoice")).to_be_visible()

    # Additional verifications for popup contents
    expect(page.locator("text=Invoice Date")).to_be_visible()
    expect(page.locator("text=Choose date, selected date is Feb 20, 2026")).to_be_visible()
    expect(page.locator("text=Invoice Comments")).to_be_visible()
    expect(page.locator("text=02/20/2026")).to_be_visible()','def verify_and_click_preview(page):
    dialog = page.get_by_role("dialog")
    expect(dialog).to_be_visible()
    expect(dialog.get_by_label("Invoice Date")).to_be_visible()
    expect(dialog.get_by_label("Invoice Comments")).to_be_visible()
    preview_btn = dialog.get_by_role("button", name="Preview Invoice")
    expect(preview_btn).to_be_visible()
    preview_btn.click()','passed','2026-05-19 08:04:55','2026-09-10 08:15:42','',NULL),
