(3846,5163,'assertion','# Locate SCRAP row exactly
scrap_row = page.locator(
    "div[role=\'row\']",
    has=page.locator("div[data-field=\'idCol\'][title=\'SCRAP\']")
)

expect(scrap_row).to_be_visible()

# Get only data rows (exclude headers)
non_scrap_rows = page.locator(
    "div[role=\'row\'][data-id]:not(:has(div[data-field=\'idCol\'][title=\'SCRAP\']))"
)

# Validate rows exist
expect(non_scrap_rows).to_have_count(non_scrap_rows.count())

# Validate both stock columns are 0
for i in range(non_scrap_rows.count()):
    row = non_scrap_rows.nth(i)

    stock_sale = row.locator(
        "div[role=\'gridcell\'][data-field=\'netAvailableStockSaleEA\']"
    )

    stock_extra = row.locator(
        "div[role=\'gridcell\'][data-field=\'netAvailableStockSaleEAExtra\']"
    )

    expect(stock_sale).to_have_text("0")
    expect(stock_extra).to_have_text("0")',NULL,'passed','2026-05-20 01:53:52','2026-08-27 08:48:50','',NULL),
