    "//div[@data-field=\'description\' and contains(@title, \'BCZQEN\')]"
).first

expect(
    description_cell
).to_be_visible(
    timeout=10000
)

description_value = (
    description_cell.inner_text()
    .strip()
)

print(
    "\\nDescription value from UI:",
    description_value
)

assert "BCZQEN" in description_value, (
    "\\nDescription validation FAILED.\\n"
    "Expected description to contain: BCZQEN\\n"
    f"Actual description: {description_value}"
)

print(
    "Description validation PASSED: BCZQEN found."
)',NULL,'passed','2026-05-21 01:49:47','2026-08-27 08:36:45','
