(4404,5850,'custom','from playwright.sync_api import Page, expect
import re

def test_verify_bol_number_and_qty_to_invoice(page: Page):

    # Verify "Planned In Shipment" text is displayed
    planned_shipment = page.locator(
        "//span[contains(text(),\'Planned In Shipment\')]"
    )

    expect(planned_shipment).to_be_visible()

    # Get full text dynamically
    shipment_text = planned_shipment.text_content()

    # Extract shipment/BOL number dynamically
    shipment_number = re.search(r"\\d+", shipment_text).group()

    print("Shipment/BOL Number :", shipment_number)

    # Verify number is generated/displayed
    assert shipment_number is not None

    # Verify Qty To Invoice value is 20.00
    qty_to_invoice = page.locator(
        "//div[@role=\'gridcell\' and @data-field=\'qtyToInvoice\']"
    )

    expect(qty_to_invoice).to_have_text(re.compile(r"20\\.00|20"))',NULL,'passed','2026-05-22 00:39:29','2026-09-05 00:26:59','',NULL),
