(4814,6389,'custom','from playwright.sync_api import expect

# Get stored PO Number
po_number = str(get_var("po_number")).strip()
print("Stored PO Number:", po_number)

# Locate all Order/PO cells (data rows only)
order_po_cells = page.locator(
    \'//div[@role="row"][@data-id]//div[@data-field="orderId"]\'
)

count = order_po_cells.count()
print("Order/PO Row Count:", count)

for i in range(count):
    value = order_po_cells.nth(i).inner_text().strip()
    print(f"Row {i + 1}: {value}")

    assert value != po_number, (
        f"PO Number \'{po_number}\' is unexpectedly present in Order/PO column."
    )

print(f"Verified: PO Number \'{po_number}\' is NOT present in the Order/PO column.")','from playwright.sync_api import expect

