(5963,7635,'custom','import re
from playwright.sync_api import expect
 
# Scope inside dialog
dialog = page.locator("div[role=\'dialog\']")
 
# Wait for grid initial load
dialog.locator("div[role=\'row\'][data-id]").first.wait_for()
 
# -------------------------------------------------------------------
# STEP 1: Read total row count from pagination
# Example text: "1–780 of 780"
# -------------------------------------------------------------------
 
pagination_text = dialog.locator(
    "p.MuiTablePagination-displayedRows"
).inner_text().strip()
 
print("Pagination Text:", pagination_text)
 
match = re.search(r"of\\s+(\\d+)", pagination_text)
 
if not match:
    raise Exception("Unable to determine total row count")
 
total_rows = int(match.group(1))
 
print("Total Rows:", total_rows)
 
# -------------------------------------------------------------------
# STEP 2: Iterate using logical data-index
# -------------------------------------------------------------------
 
selected = False
 
for row_index in range(total_rows-1):
 
    print(f"\\nProcessing Row Index: {row_index}")
 
    # Row locator using logical index
    row_locator = dialog.locator(
        f"div[role=\'row\'][data-rowindex=\'{row_index}\']"
    )
 
    # ----------------------------------------------------------------
    # If row not present in DOM -> scroll grid
    # ----------------------------------------------------------------
 
    retry = 0
 
    while row_locator.count() == 0 and retry < 10:
 
        print(f"Row {row_index} not in DOM. Scrolling...")
 
        # Scroll last visible row into view
        visible_rows = dialog.locator("div[role=\'row\'][data-id]")
 
        last_visible = visible_rows.last
 
        last_visible.scroll_into_view_if_needed()
 
        page.wait_for_timeout(300)
 
        retry += 1
 
    # Skip if still not found
    if row_locator.count() == 0:
        print(f"Row {row_index} could not be loaded")
        continue
 
    # Use first matching row
    row = row_locator.first
 
    row.scroll_into_view_if_needed()
 
    # ----------------------------------------------------------------
    # Read values safely
    # ----------------------------------------------------------------
 
    try:
        stock_on_so = row.locator(
            "[data-field=\'StockOnSoPCS\']"
        ).inner_text().strip()
 
        actual_yard = row.locator(
            "[data-field=\'actualYardStockPCS\']"
        ).inner_text().strip()
 
        print("StockOnSoPCS:", stock_on_so)
        print("ActualYardStockPCS:", actual_yard)
 
        stock_on_so_val = float(stock_on_so)
        actual_yard_val = float(actual_yard)
 
    except Exception as e:
        print("Failed reading row:", e)
        continue
 
    # ----------------------------------------------------------------
    # Apply condition
    # ----------------------------------------------------------------
 
    if stock_on_so_val == 0 and actual_yard_val > 1:
 
        print(f"Matching row found at index {row_index}")
 
        checkbox = row.locator(
            "input[type=\'checkbox\'][aria-label=\'Select row\']"
        )
 
        expect(checkbox).to_be_visible()
 
        checkbox.scroll_into_view_if_needed()
 
        checkbox.click(force=True)
 
        selected = True
 
        break
 
# -------------------------------------------------------------------
# Final validation
# -------------------------------------------------------------------
 
if not selected:
    raise Exception("No matching row found")','import re
