(6214,7969,'custom','from playwright.sync_api import Page, expect

def test_logout(page: Page):
    # Navigate to the login page
    page.goto("https://example.com/login")  # Replace with your actual login URL

    # Fill in the login form using example credentials
    page.fill("input[label=\'Email\']", "test@example.com")
    page.fill("input[label=\'Password\']", "TestPass123")

    # Click the login button and wait for navigation
    page.click("button >> text=Login")

    # Verify the dashboard title appears
    expect(page.locator("[data-testid=\'page_title\']")).to_contain_text("Dashboard")

    # Navigate to the Admin home page
    page.get_by_text("ADMIN").click()
    # Wait for the admin page to load
    expect(page.locator("[data-testid=\'page_title\']")).to_contain_text("Admin")

    # Locate and click the logout link
    page.get_by_role("link", name="Logout").click()

    # Verify that the user is redirected back to the login page
    expect(page.locator("input[label=\'Email\']")).to_be_visible()',NULL,'passed','2026-06-02 08:15:24','2026-09-02 01:07:08','',NULL),
