(7973,9982,'assertion','from playwright.sync_api import expect


# ============================================================
# LOCATORS
# ============================================================

scroller = page.locator(
    ".MuiDataGrid-virtualScroller"
)

grid_rows = page.locator(
    \'div[role="row"][data-rowindex]\'
)


# ============================================================
# WAIT FOR GRID
# ============================================================

expect(
    grid_rows.first
).to_be_visible(timeout=15_000)


# ============================================================
# STORE ALL UNIQUE ROWS
#
# MUI DataGrid is virtualized.
# The same DOM row can be reused while scrolling.
#
# data-rowindex is therefore used as the unique row key.
# ============================================================

all_rows = {}


# ============================================================
# READ CURRENTLY VISIBLE ROWS
#
# evaluate_all() reads all currently rendered rows in ONE
# operation, avoiding nth(32) timeout.
# ============================================================

def read_visible_rows():

    visible_rows = grid_rows.evaluate_all(
        """
        rows => rows.map(row => {

            const invoiceCell = row.querySelector(
                \'[role="gridcell"][data-field="invoiceCreditNoteId"]\'
            );

            const customerCell = row.querySelector(
                \'[role="gridcell"][data-field="customerName"]\'
            );

            return {
                rowIndex: row.getAttribute("data-rowindex"),

                invoiceCreditNoteId: invoiceCell
                    ? (
                        invoiceCell.getAttribute("title")
                        || invoiceCell.textContent
                        || ""
                    ).trim()
                    : "",

                customerName: customerCell
                    ? (
                        customerCell.getAttribute("title")
                        || customerCell.textContent
                        || ""
                    ).trim()
                    : ""
            };
        })
        """
    )

    for row in visible_rows:

        row_index = row["rowIndex"]

        if row_index is not None:
            all_rows[row_index] = row


# ============================================================
# SCROLL THROUGH THE ENTIRE TABLE
# ============================================================

previous_scroll_top = -1

while True:

    # Capture currently rendered rows
    read_visible_rows()

    current_scroll_top = scroller.evaluate(
        "(el) => el.scrollTop"
    )

    max_scroll_top = scroller.evaluate(
        "(el) => el.scrollHeight - el.clientHeight"
    )

    # Reached bottom
    if current_scroll_top >= max_scroll_top:
        break

    # Safety condition
    if current_scroll_top == previous_scroll_top:
        break

    previous_scroll_top = current_scroll_top

    # Scroll one viewport
    scroller.evaluate(
        "(el) => el.scrollBy(0, el.clientHeight)"
    )

    # Wait for MUI DataGrid to render new rows
    page.wait_for_timeout(500)


# ============================================================
# CAPTURE FINAL VIEWPORT
# ============================================================

read_visible_rows()


# ============================================================
# SORT ROWS BY ACTUAL DATA ROW INDEX
# ============================================================

ordered_rows = sorted(
    all_rows.values(),
    key=lambda row: int(row["rowIndex"])
)

print(
    f"Total unique grid rows collected: {len(ordered_rows)}"
)


# ============================================================
# IDENTIFY COMPANY GROUPS
#
# IMPORTANT:
#
# invoiceCreditNoteId can contain BOTH:
#
#     PPBC          -> company
#     BC1538191     -> invoice number
#
# Therefore invoice numbers MUST NOT be treated as companies.
# ============================================================

company_groups = []

current_company = None
current_company_row_count = 0

subtotal_count = 0
total_count = 0

total_row_index = None


# ============================================================
# PROCESS EVERY ROW IN GRID ORDER
# ============================================================

for row in ordered_rows:

    invoice_value = row["invoiceCreditNoteId"].strip()
    customer_value = row["customerName"].strip()

    invoice_lower = invoice_value.lower()
    customer_lower = customer_value.lower()


    # ========================================================
    # SUB TOTAL ROW
    # ========================================================

    if "sub total" in customer_lower:

        # A Sub Total must have a company before it
        assert current_company is not None, (
            "\\nSub Total found without a company before it.\\n"
            f"Row index : {row[\'rowIndex\']}\\n"
            f"Customer  : {customer_value}"
        )

        subtotal_count += 1

        company_groups.append({
            "company": current_company,
            "row_count": current_company_row_count,
            "subtotal_row": row["rowIndex"]
        })

        print(
            f"PASS: {current_company} -> Sub Total "
            f"(row {row[\'rowIndex\']})"
        )

        # Reset for next company
        current_company = None
        current_company_row_count = 0

        continue


    # ========================================================
    # TOTAL ROW
    # ========================================================

    if (
        "total" in customer_lower
        and "sub total" not in customer_lower
    ):

        total_count += 1
        total_row_index = row["rowIndex"]

        continue


    # ========================================================
    # EMPTY INVOICE/CREDIT NOTE VALUE
    # ========================================================

    if not invoice_value:
        continue


    # ========================================================
    # IMPORTANT:
    # IGNORE INVOICE NUMBERS
    #
    # Example:
    #
    # PPBC       -> company
    # BC1538191  -> invoice number
    #
    # Invoice numbers contain digits.
    # ========================================================

    if any(char.isdigit() for char in invoice_value):

        # This is a detail/invoice row.
        #
        # It belongs to the current company but is NOT
        # a new company group.
        #
        if current_company is not None:
            current_company_row_count += 1

        continue


    # ========================================================
    # IGNORE TOTAL/SUBTOTAL TEXT IF PRESENT IN THIS FIELD
    # ========================================================

    if "total" in invoice_lower:
        continue


    # ========================================================
    # COMPANY VALUE
    # ========================================================

    if current_company is None:

        # Start a new company group
        current_company = invoice_value
        current_company_row_count = 1

        continue


    # ========================================================
    # SAME COMPANY APPEARS AGAIN
    # ========================================================

    if invoice_value == current_company:

        current_company_row_count += 1

        continue


    # ========================================================
    # DIFFERENT COMPANY BEFORE SUB TOTAL
    # ========================================================

    raise AssertionError(
        "\\nCompany group changed before Sub Total.\\n"
        f"Previous company : {current_company}\\n"
        f"Next company     : {invoice_value}\\n"
        f"Row index        : {row[\'rowIndex\']}"
    )


# ============================================================
# LAST COMPANY MUST HAVE SUB TOTAL
# ============================================================

assert current_company is None, (
    "\\nLast company does not have a Sub Total.\\n"
    f"Company: {current_company}"
)


# ============================================================
# EXTRACT COMPANY ORDER
# ============================================================

actual_companies = [
    group["company"]
    for group in company_groups
]


# ============================================================
# REMOVE DUPLICATE COMPANY GROUPS
#
# This is defensive. Each company should normally occur once
# as a group, because each group ends at a Sub Total.
# ============================================================

unique_company_groups = []

for company in actual_companies:

    if company not in unique_company_groups:
        unique_company_groups.append(company)


# ============================================================
# 1. VALIDATE COMPANY ALPHABETICAL ORDER
# ============================================================

expected_companies = sorted(
    unique_company_groups,
    key=lambda value: value.casefold()
)


assert unique_company_groups == expected_companies, (
    "\\nCompany groups are NOT in alphabetical order.\\n"
    f"Actual   : {unique_company_groups}\\n"
    f"Expected : {expected_companies}"
)


print("")
print(
    "PASS: Company groups are in alphabetical order."
)

print(
    f"Companies: {unique_company_groups}"
)


# ============================================================
# 2. VALIDATE EVERY COMPANY HAS SUB TOTAL
# ============================================================

assert subtotal_count == len(company_groups), (
    "\\nSubtotal count does not match company groups.\\n"
    f"Company groups : {len(company_groups)}\\n"
    f"Subtotals      : {subtotal_count}"
)


assert len(unique_company_groups) == subtotal_count, (
    "\\nEvery company should have exactly one Sub Total.\\n"
    f"Companies : {len(unique_company_groups)}\\n"
    f"Subtotals : {subtotal_count}"
)


print(
    f"PASS: Every company has a Sub Total "
    f"({subtotal_count} found)."
)


# ============================================================
# 3. VALIDATE EXACTLY ONE TOTAL
# ============================================================

assert total_count == 1, (
    "\\nExpected exactly ONE Total row.\\n"
    f"Found: {total_count}"
)


print(
    "PASS: Exactly one Total row found."
)


# ============================================================
# 4. VALIDATE TOTAL IS AT THE BOTTOM
# ============================================================

meaningful_rows = [
    row
    for row in ordered_rows
    if (
        row["invoiceCreditNoteId"].strip()
        or row["customerName"].strip()
    )
]


assert meaningful_rows, (
    "No meaningful rows found in the grid."
)


last_row = meaningful_rows[-1]

last_customer = last_row["customerName"].strip().lower()


assert (
    "total" in last_customer
    and "sub total" not in last_customer
), (
    "\\nTotal row is NOT at the bottom.\\n"
    f"Last row index : {last_row[\'rowIndex\']}\\n"
    f"Invoice value  : {last_row[\'invoiceCreditNoteId\']}\\n"
    f"Customer value : {last_row[\'customerName\']}"
)


print(
    "PASS: Total row is at the bottom."
)


# ============================================================
# 5. FINAL RESULT
# ============================================================

print("")
print("============================================================")
print("PASS: COMPANY-WISE DATA VALIDATION PASSED")
print("============================================================")
print(
    f"Companies : {unique_company_groups}"
)
print(
    f"Subtotals : {subtotal_count}"
)
print(
    "Total     : 1"
)
print("============================================================")',NULL,'passed','2026-06-19 02:55:42','2026-09-02 03:20:54','Total unique grid rows collected: 443
PASS: PPBC -> Sub Total (row 115)
PASS: PPCAL -> Sub Total (row 145)
PASS: PPCNTL -> Sub Total (row 173)
PASS: PPEAST -> Sub Total (row 181)
PASS: PPEDM -> Sub Total (row 291)
PASS: PPMTL -> Sub Total (row 440)

PASS: Company groups are in alphabetical order.
Companies: [\'PPBC\', \'PPCAL\', \'PPCNTL\', \'PPEAST\', \'PPEDM\', \'PPMTL\']
PASS: Every company has a Sub Total (6 found).
PASS: Exactly one Total row found.
PASS: Total row is at the bottom.

============================================================
PASS: COMPANY-WISE DATA VALIDATION PASSED
============================================================
Companies : [\'PPBC\', \'PPCAL\', \'PPCNTL\', \'PPEAST\', \'PPEDM\', \'PPMTL\']
Subtotals : 6
Total     : 1
============================================================',NULL),
