(7982,9991,'custom','from playwright.sync_api import expect
import os

# --------------------------------------------------
# Locate Enabled Excel Export button
# --------------------------------------------------

export_button = page.locator(
    "button[title=\'Excel Export\']:not([disabled])"
)

# Verify exactly one enabled Excel Export button exists
assert export_button.count() == 1, (
    f"Expected 1 enabled Excel Export button, "
    f"but found {export_button.count()}"
)

# Verify button is visible and enabled
expect(export_button).to_be_visible()
expect(export_button).to_be_enabled()

print("SUCCESS: Enabled Excel Export button is visible and enabled.")

# --------------------------------------------------
# Capture Download
# --------------------------------------------------

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# --------------------------------------------------
# Download Information
# --------------------------------------------------

filename = download.suggested_filename

print("Downloaded filename:", filename)

# --------------------------------------------------
# Save Downloaded File
# --------------------------------------------------

download_dir = "/tmp/downloads"
os.makedirs(download_dir, exist_ok=True)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print("Saved file:", file_path)

# --------------------------------------------------
# Verify File Exists
# --------------------------------------------------

assert os.path.exists(file_path), (
    f"Downloaded Excel file was not saved: {file_path}"
)

print("SUCCESS: Downloaded Excel file exists.")

# --------------------------------------------------
# Verify File Is Not Empty
# --------------------------------------------------

file_size = os.path.getsize(file_path)

assert file_size > 0, (
    f"Downloaded Excel file is empty: {file_path}"
)

print(
    f"SUCCESS: Excel file downloaded and is not empty. "
    f"File size: {file_size} bytes"
)

# --------------------------------------------------
# Verify Excel File Extension
# --------------------------------------------------

assert filename.lower().endswith(
    (".xlsx", ".xls")
), (
    f"Expected Excel file, but downloaded: {filename}"
)

print(
    f"SUCCESS: Valid Excel file downloaded: {filename}"
)

# --------------------------------------------------
# Delete File After Verification
# --------------------------------------------------

os.remove(file_path)

assert not os.path.exists(file_path), (
    f"Excel file was not deleted: {file_path}"
)

print("SUCCESS: Excel file was deleted after verification.")','from playwright.sync_api import expect


