(8034,10271,'custom','# ==========================
# Add Products (1 to 12)
# ==========================

for i in range(1, 13):

    product_id = tdm_fetch(
        f"{{UserFlowProductsData.1.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Product ID Row {i}: {product_id}")
        continue

    page.locator("//input[@name=\'partyId\']").wait_for(state="visible")
    page.locator("//input[@name=\'partyId\']").click()
    page.locator("//input[@name=\'partyId\']").clear()
    page.locator("//input[@name=\'partyId\']").fill(str(product_id))

    page.wait_for_timeout(1000)

    page.locator("//button[normalize-space()=\'Add\']").click()

    print(f"Added Product ID Row {i}: {product_id}")

    page.wait_for_timeout(3000)

page.wait_for_timeout(5000)

# ==========================
# Qty, Unit Price & UOM (1 to 12)
# ==========================

for i in range(1, 13):

    qty = tdm_fetch(
        f"{{UserFlowProductsData.1.POQtyOrderedtem{i}}}"
    )
    unit_price = tdm_fetch(
        f"{{UserFlowProductsData.1.POUnitePriceItem{i}}}"
    )
    uam_value = tdm_fetch(
        f"{{UserFlowProductsData.1.UAMSelect{i}}}"
    )

    # ==========================
    # Qty Ordered
    # ==========================

    if (
        qty is not None
        and str(qty).strip() != ""
        and str(qty).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'quantity\'])[{i}]"
        ).click()

        page.wait_for_timeout(1000)

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'quantity\'])[{i}]//input"
        ).fill(str(qty))

        page.wait_for_timeout(1000)

        page.locator(
            "//h6[contains(text(),\'New Purchase Order\')]"
        ).click()

        page.wait_for_timeout(3000)

        print(f"Qty updated for Row {i}: {qty}")

    else:
        print(f"Skipping Qty Row {i}: {qty}")

    # ==========================
    # Unit Price
    # ==========================

    if (
        unit_price is not None
        and str(unit_price).strip() != ""
        and str(unit_price).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'unitPrice\'])[{i}]"
        ).click()

        page.wait_for_timeout(1000)

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'unitPrice\'])[{i}]//input"
        ).fill(str(unit_price))

        page.wait_for_timeout(1000)

        page.locator(
            "//h6[contains(text(),\'New Purchase Order\')]"
        ).click()

        page.wait_for_timeout(3000)

        print(f"Unit Price updated for Row {i}: {unit_price}")

    else:
        print(f"Skipping Unit Price Row {i}: {unit_price}")

    # ==========================
    # UOM
    # ==========================

    if (
        uam_value is not None
        and str(uam_value).strip() != ""
        and str(uam_value).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        page.locator(
            f"(//div[@role=\'gridcell\' and @data-field=\'priceUomId\'])[{i}]"
        ).click()

        page.wait_for_timeout(1000)

        page.locator(
            f"//li[@role=\'option\' and @data-value=\'{uam_value}\']"
        ).click()

        page.wait_for_timeout(2000)

        # Click outside to save
        page.locator(
            "//h6[contains(text(),\'New Purchase Order\')]"
        ).click(force=True)

        page.wait_for_timeout(2000)

        print(f"UOM updated for Row {i}: {uam_value}")

    else:
        print(f"Skipping UOM Row {i}: {uam_value}")

    page.wait_for_timeout(5000)
