(8037,10277,'custom','import json

product = tdm_fetch("{TableProductLogic.${row_number}.BEAMS}")

if product == "NA":
    print("product is NA, skipping everything")
else:
    if isinstance(product, str):
        product = json.loads(product)
    
    set_var("beamsJson", product)
    print(get_var("beamsJson"))
    index = 0

    print("##" * 10)
    for item in product:
        index += 1
        productId = item["input"]["productId"]
        print("productid:",productId)

        findProduct = page.locator(\'//input[@name="partyId"]\')
        addButton = page.locator(\'//*[text()="Add"]\')

        findProduct.clear()
        findProduct.fill(productId)
        addButton.click()
        page.wait_for_timeout(3000)        

    page.wait_for_timeout(3000)
    print("Items added:", index)

    for itemprop in product:
        productId = itemprop["input"]["productId"]
        materialCost = itemprop["input"]["po_price"]
        qtyuom = itemprop["input"]["po_quantity_uom"]
        priceuom = itemprop["input"]["po_price_uom"]
        qty = itemprop["input"]["po_qty"]
        print("productId, materialCost, qtyuom, priceuom, qty", productId, materialCost, qtyuom, priceuom, qty)
        print("--" * 10)

        heading = page.locator("//h6[text()=\'New Purchase Order\']")
   
        materialCostLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'materialCost\']")
        materialCostLoc.click()
        page.wait_for_timeout(2000)
        materialCostInput = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'materialCost\']//input")
        if materialCostInput.count()<1:
            materialCostLoc.click()
            materialCostInput.fill(materialCost)
        else:
            materialCostInput.fill(materialCost)
        heading.click()
        page.wait_for_timeout(4000)
        

        quantityLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'quantity\']")
        quantityLoc.click()
        page.wait_for_timeout(2000)
        quantityInput = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'quantity\']//input")
        if quantityInput.count()<1:
            quantityLoc.click()
            quantityInput.fill(qty)
        else:
            quantityInput.fill(qty)
        heading.click()
        page.wait_for_timeout(4000)

        
        uomLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'qtyUomId\']")
        if uomLoc.get_attribute("title") == qtyuom:
            pass
        else:
            page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'qtyUomId\']").click()
            page.wait_for_timeout(6000)
            page.locator(f"//ul[contains(@class,\'MuiList-root MuiList-padding MuiMenu-list\')]/li[text()=\'{qtyuom}\']").click()
            page.locator(\'h6.MuiTypography-h6\').first.click()
            heading.click()
            page.wait_for_timeout(4000)


        priceuomLoc = page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'priceUomId\']")
        if priceuomLoc.get_attribute("title") == priceuom:
            pass
        else:
            page.locator(f"//*[text()=\'{productId}\']/..//*[@data-field=\'priceUomId\']").click()
            page.wait_for_timeout(6000)
            page.locator(f"//ul[contains(@class,\'MuiList-root MuiList-padding MuiMenu-list\')]/li[text()=\'{priceuom}\']").click()
            page.locator(\'h6.MuiTypography-h6\').first.click()
            heading.click()
            page.wait_for_timeout(4000)
