(8105,10327,'custom','from playwright.sync_api import Page, expect

def verify_shipped_equals_received(page: Page):
    rows = page.locator(\'div[role="row"][data-id]\')

    row_count = rows.count()

    for i in range(row_count):
        row = rows.nth(i)

        shipped = row.locator(\'[data-field="totalQtyShipped"]\')
        received = row.locator(\'[data-field="qtyReceived"]\')

        shipped_value = float(shipped.inner_text().strip())
        received_value = float(received.inner_text().strip())

        assert shipped_value == received_value, (
            f"Row {i+1}: T/PO Qty Shipped={shipped_value} "
            f"but PO Qty Received={received_value}"
        )','from playwright.sync_api import Page, expect

def verify_shipped_equals_received(page: Page):
    rows = page.locator(\'div[role="row"][data-id]\')

    row_count = rows.count()

    for i in range(row_count):
        row = rows.nth(i)

        shipped = row.locator(\'[data-field="totalQtyShipped"]\')
        received = row.locator(\'[data-field="qtyReceived"]\')

        shipped_value = float(shipped.inner_text().strip())
        received_value = float(received.inner_text().strip())

        assert shipped_value == received_value, (
            f"Row {i+1}: T/PO Qty Shipped={shipped_value} "
