(8118,10332,'custom','from playwright.sync_api import expect

for i in range(1, 13):

    product_id = tdm_fetch(
        f"{{UserFlowProductsData.1.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Product ID Row {i}: {product_id}")
        continue

    print(f"Processing Product ID Row {i}: {product_id}")

    # Enter Product ID
    page.locator(
        "//input[@name=\'productIdForHistory\']"
    ).clear()

    page.locator(
        "//input[@name=\'productIdForHistory\']"
    ).fill(str(product_id))

    # Enter PO Number
    page.locator(
        "//input[@name=\'poNumber\']"
    ).clear()

    page.locator(
        "//input[@name=\'poNumber\']"
    ).fill(str(get_var("po_number")))

    # Enter From Date
    page.locator(
        "//legend[contains(.,\'From Date\')]/ancestor::div[contains(@class,\'MuiOutlinedInput-root\')]//input"
    ).clear()

    page.locator(
        "//legend[contains(.,\'From Date\')]/ancestor::div[contains(@class,\'MuiOutlinedInput-root\')]//input"
    ).fill("06/01/2026")

    # Click Search
    page.get_by_role(
        "button",
        name="Search"
    ).click()

    page.wait_for_timeout(5000)

    # Verify Total Weight > 0
    total_weight_text = page.locator(
        \'[data-field="totalWeight"]\'
    ).last.inner_text().strip()

    total_weight = float(
        total_weight_text.replace(",", "")
    )

    print(
        f"Product ID: {product_id} | Total Weight (Tons): {total_weight}"
    )

    assert total_weight > 0, (
        f"Expected Total Weight > 0, but found {total_weight}"
    )

    # Clear Product ID Field
    page.locator(
        "//input[@name=\'productIdForHistory\']"
    ).clear()

    page.wait_for_timeout(1000)

print(
