    if not bol_number:
        print(f"BOL Number not found for Row {i}")
        continue

    print(f"Processing Invoice for BOL: {bol_number}")

    # ==========================
    # Clear BOL #
    # ==========================

    page.locator(
        "//input[@name=\'shipmentId\']"
    ).clear()

    page.wait_for_timeout(2000)

    # ==========================
    # Enter BOL #
    # ==========================

    page.get_by_role(
        "textbox",
        name="BOL #"
    ).fill(str(bol_number))

    page.wait_for_timeout(2000)

    # ==========================
    # Search
    # ==========================

    page.get_by_role(
        "button",
        name="Search"
    ).click()

    page.wait_for_timeout(3000)

    # ==========================
    # Select Checkbox
    # ==========================

    page.locator(
        "//input[@type=\'checkbox\' and @aria-label=\'Select row\']"
    ).check()

    page.wait_for_timeout(2000)

    # ==========================
    # Generate Invoice
    # ==========================

    page.get_by_role(
        "button",
        name="Generate Invoice"
    ).click()

    page.wait_for_timeout(3000)

    # ==========================
    # Preview Invoice
    # ==========================

    page.get_by_role(
        "button",
        name="Preview Invoice"
    ).click()

    page.wait_for_timeout(5000)

    # ==========================
    # Click OK Popup
    # ==========================

    ok_btn = page.locator(
        "//button[normalize-space()=\'Ok\']"
    )

    if ok_btn.count() > 0:

        ok_btn.wait_for(
            state="visible",
            timeout=15000
