        f"{{UserFlowProductsData.1.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
    ):
        print(f"Skipping Row {i} - Product ID not found")
        continue

    # ==========================
    # Get BOL Number
    # ==========================

    bol_number = get_var(f"bol_number{i}")

    if not bol_number:
        print(f"BOL Number not found for Row {i}")
        continue

    print(f"Verifying BOL: {bol_number}")

    # ==========================
    # Clear BOL Field
    # ==========================

    bol_input = page.locator("//input[@name=\'shipmentId\']")

    expect(bol_input).to_be_visible(timeout=30000)

    bol_input.clear()

    page.wait_for_timeout(2000)

    # ==========================
    # Enter BOL Number
    # ==========================

    bol_input.fill(str(bol_number))

    page.wait_for_timeout(2000)

    # ==========================
    # Search
    # ==========================

    search_btn = page.locator("//button[normalize-space()=\'Search\']")

    expect(search_btn).to_be_visible(timeout=30000)

    search_btn.click()

    page.wait_for_timeout(5000)

    # ==========================
    # Click Edit
    # ==========================

    edit_btn = page.locator("//button[@title=\'Edit\']").first

    expect(edit_btn).to_be_visible(timeout=30000)

    edit_btn.click()

    page.wait_for_timeout(5000)

    # ==========================
    # Validate Total Amount
    # ==========================

    expected_value = get_var(
        f"order{i:02d}_total"
    )

    total_locator = page.locator(
        "(//div[@role=\'gridcell\' and @data-field=\'cartItemTotal\'])[1]"
    )

    expect(total_locator).to_be_visible(timeout=30000)

    actual_value = total_locator.inner_text().strip()

    assert actual_value == expected_value, (
        f"Row {i} Failed - "
        f"Expected: {expected_value}, "
        f"Actual: {actual_value}"
    )

    print(
        f"Row {i} Verified Successfully - Total: {actual_value}"
    )

    # ==========================
    # Close Dialog
    # ==========================

    close_btn = page.locator(
        "(//div[@role=\'dialog\']//*[name()=\'svg\' and contains(@class,\'iconify\')])[1]"
    )

    expect(close_btn).to_be_visible(timeout=30000)

    close_btn.click()

    page.wait_for_timeout(3000)

    print(f"BOL {bol_number} verification completed")

