(8471,10917,'assertion','from playwright.sync_api import expect

grid = page.locator(".MuiDataGrid-virtualScroller").first
expect(grid).to_be_visible()

allowed_statuses = {"ORDER_APPROVED", "ORDER_CREATED"}
excluded_statuses = {
    "NEED_APPROVAL_FOR_SHIPPING",
    "NEED_APPROVAL_FOR_INVOICE"
}

validated_rows = set()
last_scroll = -1

while True:

    # Read all visible rows in one JS execution
    visible_rows = grid.evaluate("""
    (grid) => {
        return [...grid.querySelectorAll(\'div[data-id][role="row"]\')].map(row => ({
            id: row.getAttribute(\'data-id\'),
            status: row.querySelector(\'div[data-field="Status"] button\')?.getAttribute(\'title\')
        }));
    }
    """)

    for row in visible_rows:

        if row["id"] in validated_rows:
            continue

        validated_rows.add(row["id"])

        # Skip excluded statuses
        if row["status"] in excluded_statuses:
            continue

        assert row["status"] in allowed_statuses, \\
            f"Order {row[\'id\']} has invalid status {row[\'status\']}"

    current_scroll = grid.evaluate("el => el.scrollTop")
    max_scroll = grid.evaluate("el => el.scrollHeight - el.clientHeight")

    if current_scroll == last_scroll or current_scroll >= max_scroll:
        break

    last_scroll = current_scroll

    grid.evaluate("el => el.scrollBy(0, 600)")
    page.wait_for_timeout(300)

print(f"✓ Validated {len(validated_rows)} rows.")',NULL,'passed','2026-06-29 03:08:06','2026-09-07 01:32:30','✓ Validated 26 rows.',NULL),
(8472,10918,'assertion','from playwright.sync_api import expect

# Locate all Order cells
order_cells = page.locator("//div[@role=\'gridcell\' and @data-field=\'Order\']")

count = order_cells.count()
assert count > 0, "No orders found."

for i in range(count):
    order_cell = order_cells.nth(i)
    expect(order_cell).to_be_visible()

    order_id = order_cell.inner_text().strip()

    assert order_id.startswith("EAS"), (
        f"Order ID \'{order_id}\' does not belong to PPEAST company."
    )

print(f"Verified all {count} displayed Order IDs start with \'EAS\'.")',NULL,'passed','2026-06-29 03:08:32','2026-09-07 01:33:18','Verified all 23 displayed Order IDs start with \'EAS\'.',NULL),
(8473,10919,'assertion','from playwright.sync_api import expect

grid = page.locator(".MuiDataGrid-virtualScroller").first
expect(grid).to_be_visible()

orders = {}
last_scroll = -1

while True:
    rows = page.locator(
        ".MuiDataGrid-virtualScrollerRenderZone div[data-id][role=\'row\']"
    ).all()

    for row in rows:
        order_no = row.get_attribute("data-id")
        row_index = row.get_attribute("data-rowindex")

        if not order_no or row_index is None:
            continue

        # Store using the actual grid row index
        orders[int(row_index)] = order_no

    current_scroll = grid.evaluate("el => el.scrollTop")
    max_scroll = grid.evaluate(
        "el => el.scrollHeight - el.clientHeight"
    )

    if current_scroll >= max_scroll or current_scroll == last_scroll:
        break

    last_scroll = current_scroll

    # Scroll gradually so virtualized rows are not skipped
    next_scroll = min(
        current_scroll + grid.evaluate("el => el.clientHeight / 2"),
        max_scroll
    )

    grid.evaluate(
        "(el, y) => el.scrollTop = y",
        next_scroll
    )

    page.wait_for_timeout(300)


# Sort by the grid\'s actual row index
ordered_orders = [
    orders[index]
    for index in sorted(orders)
]

print(f"scrollTop={current_scroll}, maxScroll={max_scroll}")
print(f"orders collected={len(ordered_orders)}")

print("Collected order sequence:")
for i, order_no in enumerate(ordered_orders):
    print(f"Row {i}: {order_no}")


# Verify Order Number is descending
for i in range(len(ordered_orders) - 1):
    current_order = ordered_orders[i]
    next_order = ordered_orders[i + 1]

    if current_order < next_order:
        raise AssertionError(
            f"Sorting failed.\\n"
            f"Grid row {i}: {current_order}\\n"
            f"Grid row {i + 1}: {next_order}"
        )

print(
    f"✓ Verified {len(ordered_orders)} orders are sorted "
    f"by Order Number descending."
)',NULL,'passed','2026-06-29 03:08:55','2026-09-07 01:33:02','scrollTop=291, maxScroll=291
