(8862,11220,'assertion','from decimal import Decimal, ROUND_HALF_UP
from playwright.sync_api import expect

# Locators
sub_total_input = page.locator(\'text=Sub Total ($)\').first.locator(\'..\').locator(\'input\')
gst_input = page.locator(\'text=H.S.T./G.S.T. ($)\').first.locator(\'..\').locator(\'input\')
pst_input = page.locator(\'text=P.S.T. ($)\').first.locator(\'..\').locator(\'input\')

# Read subtotal
sub_total_text = sub_total_input.input_value().replace(",", "")
sub_total = Decimal(sub_total_text)

# Calculate taxes using financial rounding
gst_expected = (sub_total * Decimal("0.05")).quantize(
    Decimal("0.01"),
    rounding=ROUND_HALF_UP
)

pst_expected = (sub_total * Decimal("0.07")).quantize(
    Decimal("0.01"),
    rounding=ROUND_HALF_UP
)

# Assertions
expect(gst_input).to_have_value(f"{gst_expected:,.2f}")
expect(pst_input).to_have_value(f"{pst_expected:,.2f}")',NULL,'passed','2026-07-01 09:10:31','2026-09-05 02:41:54','',NULL),
