(9251,11811,'assertion','import os
import csv
import re

# --------------------------------------------------
# Export Invoices Report as CSV
# --------------------------------------------------

export_button = page.locator(
    "xpath=//span[normalize-space()=\'Export as CSV\']"
)

expect(export_button).to_be_visible()

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# --------------------------------------------------
# Download Information
# --------------------------------------------------

filename = download.suggested_filename

print("Filename:", filename)

# --------------------------------------------------
# Download Location
# --------------------------------------------------

download_dir = "/tmp/downloads"
os.makedirs(download_dir, exist_ok=True)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print("Saved file:", file_path)

# --------------------------------------------------
# Verify File Exists
# --------------------------------------------------

assert os.path.exists(file_path), (
    f"Downloaded file was not saved: {file_path}"
)

assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)

# --------------------------------------------------
# Verify CSV File
# --------------------------------------------------

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded: {filename}"
)

print("Invoices.csv downloaded successfully.")

# --------------------------------------------------
# Get UI Pagination Total Row Count
# Example: 1–106 of 106
# --------------------------------------------------

pagination = page.locator(
    ".MuiTablePagination-displayedRows"
)

expect(pagination).to_be_visible()

pagination_text = pagination.inner_text().strip()

print("UI Pagination:", pagination_text)

# --------------------------------------------------
# Extract Total Rows From Pagination
# --------------------------------------------------

pagination_match = re.search(
    r"\\d+\\s*[–-]\\s*\\d+\\s+of\\s+(\\d+)",
    pagination_text
)

assert pagination_match is not None, (
    f"Unable to extract total row count from pagination: "
    f"{pagination_text}"
)

ui_total_rows = int(
    pagination_match.group(1)
)

print(
    "Total rows displayed in UI:",
    ui_total_rows
)

# --------------------------------------------------
# Read Invoices.csv
# --------------------------------------------------

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)
    rows = list(reader)

assert len(rows) > 0, (
    "Invoices.csv does not contain any data."
)

# --------------------------------------------------
# Find Header Row
# --------------------------------------------------

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip().strip(\'="\')
        for column in row
    ]

    if (
        "Allow Email" in cleaned_row
        and "Invoice #" in cleaned_row
        and "Status" in cleaned_row
        and "Order #" in cleaned_row
        and "BOL #" in cleaned_row
    ):
        header_row_index = index
        break

assert header_row_index is not None, (
    "Invoice CSV header row was not found."
)

headers = [
    column.strip().strip(\'="\')
    for column in rows[header_row_index]
]

print(
    "Invoice CSV header found at row:",
    header_row_index + 1
)

# --------------------------------------------------
# Get CSV Data Rows
# --------------------------------------------------

data_rows = rows[header_row_index + 1:]

# Remove completely blank rows
data_rows = [
    row
    for row in data_rows
    if any(cell.strip() for cell in row)
]

csv_total_rows = len(data_rows)

print(
    "Total data rows in Invoices.csv:",
    csv_total_rows
)

# --------------------------------------------------
# Verify UI Row Count == CSV Row Count
# --------------------------------------------------

assert csv_total_rows == ui_total_rows, (
    f"UI and CSV row counts do not match. "
    f"UI rows: {ui_total_rows}, "
    f"CSV rows: {csv_total_rows}"
)

print(
    f"SUCCESS: UI pagination total rows ({ui_total_rows}) "
    f"match the CSV data rows ({csv_total_rows})."
)

# --------------------------------------------------
# Verify Expected Invoice Columns
# --------------------------------------------------

expected_columns = [
    "Allow Email",
    "Invoice #",
    "Status",
    "Order #",
    "BOL #",
    "Customer Name",
    "Project Name",
    "PO #",
    "Invoice Date"
]

for column in expected_columns:

    assert column in headers, (
        f"Expected column \'{column}\' "
        f"was not found in Invoices.csv."
    )

print(
    "SUCCESS: All expected Invoice columns "
    "are present in the CSV."
)

# --------------------------------------------------
# Final Verification
# --------------------------------------------------

print(
    "SUCCESS: Invoices.csv contains the same number "
    "of data rows as displayed in the UI pagination."
)

# --------------------------------------------------
# Delete Invoices.csv After Verification
# --------------------------------------------------

assert os.path.exists(file_path), (
    f"Invoices.csv does not exist: {file_path}"
)

os.remove(file_path)

assert not os.path.exists(file_path), (
    f"Invoices.csv was not deleted: {file_path}"
)

print(
    "SUCCESS: Invoices.csv was deleted after verification."
)',NULL,'passed','2026-07-03 05:06:45','2026-08-27 10:16:14','Filename: Invoices.csv
Saved file: /tmp/downloads/Invoices.csv
Invoices.csv downloaded successfully.
UI Pagination: 1–431 of 431
Total rows displayed in UI: 431
Invoice CSV header found at row: 7
Total data rows in Invoices.csv: 431
SUCCESS: UI pagination total rows (431) match the CSV data rows (431).
SUCCESS: All expected Invoice columns are present in the CSV.
SUCCESS: Invoices.csv contains the same number of data rows as displayed in the UI pagination.
SUCCESS: Invoices.csv was deleted after verification.',NULL),
