for i in range(count):
    checkbox = page.locator(
        f"(//input[@aria-label=\'Select row\' or @aria-label=\'Unselect row\'])[{i+1}]"
    )

    checkbox.check(force=True)
    page.wait_for_timeout(1000)

print("All rows selected successfully.")','from playwright.sync_api import expect

