(9667,12289,'custom','import re

# Scrollable grid
grid = page.locator("div.MuiDataGrid-virtualScroller").first

visited = set()
all_products = []

selected_product_id = None
selected_description = None
selected_pipe_length_ft = None

last_scroll = -1
match_found = False

while True:

    rows = page.locator("//div[@role=\'row\' and @data-rowindex]")

    for i in range(rows.count()):

        row = rows.nth(i)

        try:

            product_id = row.locator("[data-field=\'idCol\']").inner_text().strip()

            # Skip duplicate products
            if product_id in visited:
                continue

            visited.add(product_id)

            description = row.locator("[data-field=\'description\']").inner_text().strip()

            net_available_ft = float(
                row.locator("[data-field=\'netAvailableStockSaleFT\']")
                .inner_text()
                .replace(",", "")
                .strip()
            )

            po_inbound = float(
                row.locator("[data-field=\'PoTransferInbound\']")
                .inner_text()
                .replace(",", "")
                .strip()
            )

            bo_on_po = float(
                row.locator("[data-field=\'boOnPoFT\']")
                .inner_text()
                .replace(",", "")
                .strip()
            )

            # Extract Pipe Length (Example: 22.00 Ft)
            match = re.search(r\'(\\d+\\.\\d+)\\s*Ft\', description)

            pipe_length_ft = match.group(1) + " Ft" if match else ""

            # Store all rows
            all_products.append({
                "Product ID": product_id,
                "Description": description,
                "Pipe Length FT": pipe_length_ft,
                "Net Available FT": net_available_ft
            })

            print(
                f"{product_id} | "
                f"Pipe={pipe_length_ft} | "
                f"Net={net_available_ft} | "
                f"PO={po_inbound} | "
                f"BO={bo_on_po}"
            )

            # Match Condition
            if (
                po_inbound == 0
                and bo_on_po == 0
                and net_available_ft > 0
            ):

                selected_product_id = product_id
                selected_description = description
                selected_pipe_length_ft = pipe_length_ft

                set_var("selected_product_id", selected_product_id)
                set_var("selected_description", selected_description)
                set_var("selected_ft", selected_pipe_length_ft)

                match_found = True
                print("\\nMATCH FOUND")
                break

        except Exception as e:
            print(f"Skipping row due to error: {e}")

    # Exit while loop if match found
    if match_found:
        break

    # Save current scroll position
    current_scroll = grid.evaluate("(el) => el.scrollTop")

    # Scroll down one viewport
    grid.evaluate("(el) => el.scrollTop += el.clientHeight")

    page.wait_for_timeout(700)

    # Check if scroll moved
    new_scroll = grid.evaluate("(el) => el.scrollTop")

    # End of grid
    if new_scroll == current_scroll or new_scroll == last_scroll:
        break

    last_scroll = new_scroll

# Store all products
set_var("all_products", all_products)

print("\\n====================================")

if match_found:
    print("Selected Product ID :", get_var("selected_product_id"))
    print("Selected Description:", get_var("selected_description"))
    print("Selected FT :", get_var("selected_ft"))
else:
    print("No matching product found.")

print(f"Products Checked : {len(visited)}")
