(9893,12519,'custom','from playwright.sync_api import expect

# Locate all Sales Order cells
sales_orders = page.locator("//div[@role=\'gridcell\' and @data-field=\'orderId\']")

expect(sales_orders.first).to_be_visible()

count = sales_orders.count()

verified = 0

for i in range(count):
    order = sales_orders.nth(i).inner_text().strip()

    # Skip blank cells
    if not order:
        continue

    assert order.startswith("BC"), f"Sales Order \'{order}\' does not start with \'BC\'"
    verified += 1

print(f"Verified {verified} Sales Orders have \'BC\' prefix.")','from playwright.sync_api import expect

# Locate all Sales Order cells
sales_orders = page.locator("//div[@role=\'gridcell\' and @data-field=\'orderId\']")

expect(sales_orders.first).to_be_visible()

count = sales_orders.count()

verified = 0

for i in range(count):
    order = sales_orders.nth(i).inner_text().strip()

    # Skip blank cells
    if not order:
        continue

    assert order.startswith("BC"), f"Sales Order \'{order}\' does not start with \'BC\'"
    verified += 1

print(f"Verified {verified} Sales Orders have \'BC\' prefix.")','passed','2026-07-08 04:36:29','2026-09-06 02:08:00','Verified 20 Sales Orders have \'BC\' prefix.',NULL),
