(10069,12700,'custom','import json

product = tdm_fetch("{TableProductLogic.${row_number}.PIPE}")
print(product)
if product == "NA":
    print("product is NA, skipping everything")
else:
    page.wait_for_timeout(2000)
    page.locator("//label[text()=\'Enter Product ID\']/..//button[@title=\'Find\']").click()
    
    product_type = page.locator(\'#autocomplete-productType\')
    product_option= page.locator("//div[contains(@class,\'base-Popper-root\')]//*[text()=\'PIPE\']")

    if product_type.input_value() != "PIPE":
        product_type.click()
        product_type.clear()
        product_type.fill("PIPE")
        product_option.click()

    if isinstance(product, str):
        product = json.loads(product)

    set_var("totalPipes", product)

    index = 0
    for item in product:
        index += 1
        productId = item["productId"]
        od = item["outerdiameterFrom"]
        od_to = item["outerdiameterTo"]
        wt = item["wallthicknessFrom"]
        wt_to = item["wallthicknessTo"]
        ln = item["lengthFrom"]
        ln_to = item["lengthTo"]

        print(productId, od, od_to, wt, wt_to, ln, ln_to)

        if productId:
            page.locator(\'(//input[@name="productId"])[2]\').wait_for(state="visible")
            page.locator(\'(//input[@name="productId"])[2]\').click()
            page.locator(\'(//input[@name="productId"])[2]\').clear()
            page.locator(\'(//input[@name="productId"])[2]\').fill(productId)
        else:
            if od:
                page.locator("//input[@id=\'autocomplete-oDRangeFrom\']").wait_for(state="visible")
                page.locator("//input[@id=\'autocomplete-oDRangeFrom\']").click()
                page.locator("//input[@id=\'autocomplete-oDRangeFrom\']").clear()
                page.locator("//input[@id=\'autocomplete-oDRangeFrom\']").fill(od)
                page.locator(f"//div[contains(@class,\'base-Popper-root\')]//*[contains(., \'{od}\')]").first.click()

            if od_to:
                page.locator("//input[@id=\'autocomplete-oDRangeTo\']").wait_for(state="visible")
                page.locator("//input[@id=\'autocomplete-oDRangeTo\']").click()
                page.locator("//input[@id=\'autocomplete-oDRangeTo\']").clear()
                page.locator("//input[@id=\'autocomplete-oDRangeTo\']").fill(od_to)
                page.locator(f"//div[contains(@class,\'base-Popper-root\')]//*[contains(., \'{od_to}\')]").first.click()

            if wt:
                page.locator("//input[@id=\'autocomplete-walltRangeFrom\']").wait_for(state="visible")
                page.locator("//input[@id=\'autocomplete-walltRangeFrom\']").click()
                page.locator("//input[@id=\'autocomplete-walltRangeFrom\']").clear()
                page.locator("//input[@id=\'autocomplete-walltRangeFrom\']").fill(wt)
                page.locator(f"//div[contains(@class,\'base-Popper-root\')]//*[contains(., \'{wt}\')]").first.click()

            if wt_to:
                page.locator("//input[@id=\'autocomplete-walltRangeTo\']").wait_for(state="visible")
                page.locator("//input[@id=\'autocomplete-walltRangeTo\']").click()
                page.locator("//input[@id=\'autocomplete-walltRangeTo\']").clear()
                page.locator("//input[@id=\'autocomplete-walltRangeTo\']").fill(wt_to)
                page.locator(f"//div[contains(@class,\'base-Popper-root\')]//*[contains(., \'{wt_to}\')]").first.click()

            if ln:
                page.locator("//input[@name=\'lengthRangeFrom\']").click()
                page.locator("//input[@name=\'lengthRangeFrom\']").clear()
                page.locator("//input[@name=\'lengthRangeFrom\']").fill(ln)

            if ln_to:
                page.locator("//input[@name=\'lengthRangeTo\']").click()
                page.locator("//input[@name=\'lengthRangeTo\']").clear()
                page.locator("//input[@name=\'lengthRangeTo\']").fill(ln_to)

        try:
            page.locator(\'[value="false"][name="allAvailable"]\').click()
            page.locator(\'[value="false"][name="allSelectLoc"]\').click()
        except Exception:
            print("Locator already in enabled state")


        page.wait_for_timeout(3000)        
        page.locator(".MuiDialogContent-root .MuiGrid-root div.MuiBox-root button:first-child").click()

        checkbox = page.locator("[aria-label=\'Select row\']").first
        try:
            checkbox.wait_for(state="visible", timeout=5000)
            checkbox.click()
            
            productid = page.locator("[role=\'gridcell\'][data-field=\'idCol\']").first.inner_text()
            set_var(f"productid{index}", productid)

            page.locator(".MuiDialogContent-root .MuiGrid-root div.MuiBox-root button:last-child").click()

            if index < len(product):
                page.wait_for_timeout(3000)
                page.locator("//label[normalize-space()=\'Enter Product ID\']/ancestor::div[contains(@class,\'MuiFormControl-root\')]//button[@title=\'Find\']").click()
                page.wait_for_timeout(3000)
        except Exception:
