serial_number_row2 = \'\'.join(random.choices(string.ascii_uppercase + string.digits, k=6))

# Ensure both serial numbers are unique
while serial_number_row2 == serial_number_row1:
    serial_number_row2 = \'\'.join(random.choices(string.ascii_uppercase + string.digits, k=6))

# Combine as comma-separated values
