(10834,13494,'custom','from playwright.sync_api import expect


# ============================================================
# Find Order Details Product Grid
# ============================================================

order_grid = page.locator(
    "//div[@role=\'grid\']"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Product ID\']]"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Qty Ordered\']]"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Qty Shipped\']]"
    "[.//div[@role=\'columnheader\' and normalize-space()=\'Status\']]"
).first

expect(
    order_grid
).to_be_visible(timeout=30000)

print("Order Details product grid found.")


# ============================================================
# Get Rows
# ============================================================

rows = order_grid.locator(
    "xpath=.//div[@role=\'rowgroup\']/div[@role=\'row\']"
)

row_count = rows.count()

print(
    f"Total rows found: {row_count}"
)


# ============================================================
# Validation Result
# ============================================================

valid_row_found = False


# ============================================================
