(11112,13777,'custom','from playwright.sync_api import expect

# Get stored Transit ID
stored_transit_id = get_var("intransit_id")

# All Transit ID cells
transit_ids = page.locator("//div[@role=\'gridcell\' and @data-field=\'transitId\']")
count = transit_ids.count()

for i in range(count):
    transit_text = transit_ids.nth(i).inner_text().strip()

    if stored_transit_id in transit_text:
        # Verify Stock Reserved (PCS) in the same row (same index)
        expect(
            page.locator("//div[@role=\'gridcell\' and @data-field=\'stockReservedPCS\']").nth(i)
        ).to_have_text("5")

        print(f"Verified Stock Reserved (PCS) = 5 for Transit ID: {transit_text}")
