(11137,13765,'assertion','from playwright.sync_api import expect

# Only Unit Price cells from data rows
unit_price_cells = page.locator(
    "//div[@data-rowindex]//div[@data-field=\'unitPrice\']"
)

expect(unit_price_cells.first).to_be_visible()

row_count = unit_price_cells.count()

# First row unit price
first_unit_price = unit_price_cells.first.get_attribute("title").strip()

# Validate all rows
for i in range(row_count):
    current_price = unit_price_cells.nth(i).get_attribute("title").strip()

    assert current_price == first_unit_price, (
        f"Unit Price mismatch at row {i + 1}. "
        f"Expected: {first_unit_price}, Actual: {current_price}"
    )

print(f"✓ All {row_count} rows have the same Unit Price: {first_unit_price}")',NULL,'passed','2026-07-17 09:48:07','2026-07-17 09:58:00','✓ All 3 rows have the same Unit Price: 74.15',NULL),
