(11570,14264,'custom','import re
from playwright.sync_api import expect
# Scope inside dialog
dialog = page.locator("div[role=\'dialog\']")
# Wait for grid initial load
dialog.locator("div[role=\'row\'][data-id]").first.wait_for()
# -------------------------------------------------------------------
# STEP 1: Read total row count from pagination
# Example text: "1–780 of 780"
# -------------------------------------------------------------------
pagination_text = dialog.locator(
    "p.MuiTablePagination-displayedRows"
).inner_text().strip()
print("Pagination Text:", pagination_text)
match = re.search(r"of\\s+(\\d+)", pagination_text)
if not match:
    raise Exception("Unable to determine total row count")
total_rows = int(match.group(1))
print("Total Rows:", total_rows)
# -------------------------------------------------------------------
# STEP 2: Iterate using logical data-index
# -------------------------------------------------------------------
selected = False
for row_index in range(total_rows-1):
    print(f"\\nProcessing Row Index: {row_index}")
    # Row locator using logical index
    row_locator = dialog.locator(
        f"div[role=\'row\'][data-rowindex=\'{row_index}\']"
    )
    # ----------------------------------------------------------------
    # If row not present in DOM -> scroll grid
    # ----------------------------------------------------------------
    retry = 0
    while row_locator.count() == 0 and retry < 10:
        print(f"Row {row_index} not in DOM. Scrolling...")
        # Scroll last visible row into view
        visible_rows = dialog.locator("div[role=\'row\'][data-id]")
        last_visible = visible_rows.last
        last_visible.scroll_into_view_if_needed()
        page.wait_for_timeout(300)
        retry += 1
    # Skip if still not found
    if row_locator.count() == 0:
        print(f"Row {row_index} could not be loaded")
        continue
    # Use first matching row
    row = row_locator.first
    row.scroll_into_view_if_needed()
    # ----------------------------------------------------------------
    # Read values safely
    # ----------------------------------------------------------------
    try:
        stock_on_so = row.locator(
            "[data-field=\'StockOnSoPCS\']"
        ).inner_text().strip()
        actual_yard = row.locator(
            "[data-field=\'actualYardStockPCS\']"
        ).inner_text().strip()
        print("StockOnSoPCS:", stock_on_so)
        print("ActualYardStockPCS:", actual_yard)
        stock_on_so_val = float(stock_on_so)
        actual_yard_val = float(actual_yard)
    except Exception as e:
        print("Failed reading row:", e)
        continue
    # ----------------------------------------------------------------
    # Apply condition
    # ----------------------------------------------------------------
    if stock_on_so_val == 0 and actual_yard_val > 10:
        print(f"Matching row found at index {row_index}")
        checkbox = row.locator(
            "input[type=\'checkbox\'][aria-label=\'Select row\']"
        )
        expect(checkbox).to_be_visible()
        checkbox.scroll_into_view_if_needed()
        checkbox.click(force=True)
        selected = True
        break
# -------------------------------------------------------------------
# Final validation
# -------------------------------------------------------------------
if not selected:
    raise Exception("No matching row found")','def parse_num(s):
    if s is None:
        return None
    s = s.strip().replace(",", "")
    if s == "" or s == "-":
        return None
    try:
        return float(s)
    except ValueError:
        return None


grid = page.locator(\'.MuiDataGrid-main\').first
grid.wait_for(state="visible")

scroller = grid.locator(\'.MuiDataGrid-virtualScroller\')
scrollbar_v = grid.locator(\'.MuiDataGrid-scrollbar--vertical\')

try:
    page.locator(\'[aria-label="Select all rows"]\').first.click()
    page.wait_for_timeout(500)
    page.locator(\'[aria-label="Unselect all rows"]\').first.click()
    page.wait_for_timeout(500)
except Exception as e:
    print("clear-select skipped:", e)


def scroll_info():
    return scrollbar_v.evaluate(
        "el => ({top: el.scrollTop, max: el.scrollHeight - el.clientHeight})"
    )


def scroll_by(delta):
    scrollbar_v.evaluate(f"el => {{ el.scrollTop = el.scrollTop + {delta}; }}")
    scroller.evaluate(f"el => {{ el.scrollTop = el.scrollTop + {delta}; }}")
    try:
        scroller.hover()
        page.mouse.wheel(0, delta)
    except Exception:
        pass


def scroll_to_top():
    scrollbar_v.evaluate("el => { el.scrollTop = 0; }")
    scroller.evaluate("el => { el.scrollTop = 0; }")


scroll_to_top()
page.wait_for_timeout(800)

seen_ids = set()
found_data_id = None
found_product_id = None
stale_scrolls = 0
MAX_STALE = 4
SCROLL_STEP = 300

while True:
    rows = page.locator(\'div[role="row"][data-id]\')
    count = rows.count()
    new_in_this_pass = 0

    for i in range(count):
        row = rows.nth(i)
        data_id = row.get_attribute("data-id")
        if data_id is None or data_id in seen_ids:
            continue
        seen_ids.add(data_id)
        new_in_this_pass += 1

        so_cell = row.locator(\'[data-field="StockOnSoPCS"]\')
        yard_cell = row.locator(\'[data-field="actualYardStockPCS"]\')
        if so_cell.count() == 0 or yard_cell.count() == 0:
            continue

        so_val = parse_num(so_cell.get_attribute("title"))
        yard_val = parse_num(yard_cell.get_attribute("title"))
        if so_val is None or yard_val is None:
            continue

        print(f"  data-id={data_id}  SO={so_val}  Yard={yard_val}")

        if so_val < yard_val:
            found_data_id = data_id
            id_cell = row.locator(\'[data-field="idCol"]\')
            found_product_id = (
                id_cell.get_attribute("title") or id_cell.inner_text()
            ).strip()
            break

    if found_data_id is not None:
        break

    info = scroll_info()
    print(f"scroll top={info[\'top\']} max={info[\'max\']} new={new_in_this_pass} seen={len(seen_ids)}")

    if new_in_this_pass == 0:
        stale_scrolls += 1
    else:
        stale_scrolls = 0

    if info["top"] >= info["max"] - 1 or stale_scrolls >= MAX_STALE:
        print("reached bottom or no new rows after scrolling")
        break

    scroll_by(SCROLL_STEP)
    page.wait_for_timeout(500)

assert found_data_id is not None, "No row found where Stock on S/O (PCS) < Actual Yard Stock (PCS)"

set_var("rowProductId", found_product_id)
print("Matched product:", found_product_id, "data-id:", found_data_id)

target_row = page.locator(f\'div[role="row"][data-id="{found_data_id}"]\')

if target_row.count() == 0:
    scroll_to_top()
    page.wait_for_timeout(500)
    while target_row.count() == 0:
        before = scrollbar_v.evaluate("el => el.scrollTop")
        scroll_by(SCROLL_STEP)
        page.wait_for_timeout(500)
        after = scrollbar_v.evaluate("el => el.scrollTop")
        if after == before:
            break

target_row.scroll_into_view_if_needed()
page.wait_for_timeout(300)
target_row.locator(\'input[aria-label="Select row"]\').check(force=True)','passed','2026-07-20 05:41:46','2026-09-07 02:04:06','Pagination Text: 1–249 of 249
