(11829,14200,'assertion','from playwright.sync_api import expect

order_no = get_var("order_number")

row = page.locator("div[role=\'row\']").filter(
    has=page.locator(f"div[data-field=\'orderID\']:has-text(\'{order_no}\')")
)

expect(row).to_be_visible()

# Get values from stored variables
sales_hold_allocated = float(get_var("original_hold_allocated"))
qty_received = float(get_var("qty_received"))

# Locate Hold Allocated cell
hold_allocated_cell = row.locator("div[data-field=\'holdAllocatedPCE\']")

expect(hold_allocated_cell).to_be_visible()

# Capture value from the grid cell
hold_allocated = float(hold_allocated_cell.inner_text().strip())

# Calculate expected value
expected_hold_allocated = sales_hold_allocated - qty_received

# Verify
assert hold_allocated == expected_hold_allocated, (
    f"Hold Allocated mismatch. "
    f"Expected: {expected_hold_allocated}, Actual: {hold_allocated}"
)

print(f"✓ Hold Allocated reduced value verified successfully: {hold_allocated}")',NULL,'passed','2026-07-21 01:47:00','2026-07-21 03:10:45','✓ Hold Allocated reduced value verified successfully: 5.0',NULL),
