def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.

    Handles:
    - whitespace
    - accents
    - non-breaking spaces
    - punctuation spacing
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


def normalize_number(value):
    """
    Converts UI/PDF quantity such as:

        2
        2.0
        2.00
        2,00

    into:

        2
    """

    if value is None:
        return None

    value = str(value).strip()

    # Handle decimal comma
    value = value.replace(",", ".")

    try:

        number = float(value)

        if number.is_integer():
            return str(int(number))

        return f"{number:g}"

    except Exception:

        return value


def text_contains_all_tokens(text, tokens):
    """
    Returns True when every meaningful token exists
    in the normalized text.
    """

    normalized = normalize_text(text)

    for token in tokens:

        normalized_token = normalize_text(
            token
        )

        if not normalized_token:
            continue

        if normalized_token not in normalized:
            return False

    return True


