# ------------------------------------------------------------
# PDF rows are expected to look similar to:
#
# 1 18.2871 M 6,060 16.000 x 101.00# Profile en H - 60.00 pi. - A572 La Chine 1
# 1 12.1914 M 3,520 16.000 x 88.00# Profile en H - 40.00 pi. - A572 La Chine 2
# 1 18.2871 M 5,280 16.000 x 88.00# Profile en H - 60.00 pi. - A572 La Chine 3
#
# Structure:
#
# PCE
# LONGUEUR numeric value
# LONGUEUR unit
# POIDS
# DESCRIPTION
# ITEM #
#
# We validate only:
#
#     LONGUEUR unit == M
#
# for EVERY Item #.
# ------------------------------------------------------------


# ============================================================
# 20. BUILD ITEM ROW REGEX
# ============================================================

item_row_pattern = re.compile(

    r"(?:^|\\s)"

    # --------------------------------------------------------
    # PCE quantity
    # --------------------------------------------------------
    r"(?P<pce>\\d+)"

    r"\\s+"

    # --------------------------------------------------------
    # LONGUEUR numeric value
    #
    # Examples:
    # 18.2871
    # 12.1914
    # 18.2871
    # --------------------------------------------------------
    r"(?P<longueur>\\d+(?:\\.\\d+)?)"

    r"\\s+"

    # --------------------------------------------------------
    # LONGUEUR UNIT
    #
    # THIS IS THE VALUE WE ARE VALIDATING.
    # --------------------------------------------------------
    r"(?P<longueur_unit>[A-Za-z]+)"

    r"\\s+"

    # --------------------------------------------------------
    # POIDS
    # --------------------------------------------------------
    r"(?P<weight>[\\d,]+(?:\\.\\d+)?)"

    r"\\s+"

    # --------------------------------------------------------
    # Description
    #
    # Non-greedy because the Item # is at the end.
    # --------------------------------------------------------
    r"(?P<description>.*?)"

    r"\\s+"

    # --------------------------------------------------------
    # ITEM #
    # --------------------------------------------------------
    r"(?P<item_number>\\d+)"

    r"(?=\\s|$)",

    re.IGNORECASE
)


# ============================================================
# 21. FIND ALL ITEM ROWS
# ============================================================

item_matches = list(
    item_row_pattern.finditer(
        pdf_text_normalized
    )
)


print(
    "\\nPotential Item rows found:",
    len(item_matches)
)


# ============================================================
# 22. FAIL IF NO ITEM ROWS WERE FOUND
# ============================================================

assert item_matches, (

    "\\nNo Item rows could be identified in the BOL PDF.\\n\\n"

    "Expected rows containing:\\n"

    "PCE Quantity + LONGUEUR + Unit + POIDS + "
    "Description + Item #\\n\\n"

    f"PDF URL:\\n"
    f"{pdf_url}\\n\\n"

    f"PDF Text:\\n"
    f"{pdf_text_normalized}"
)


# ============================================================
# 23. VALIDATE EVERY ITEM NUMBER
# ============================================================

validated_items = []

failed_items = []

seen_item_numbers = set()


for match in item_matches:

    item_number = (
        match.group(
            "item_number"
        )
    )

    pce_quantity = (
        match.group(
            "pce"
        )
    )

    longueur_value = (
        match.group(
            "longueur"
        )
    )

    longueur_unit = (
        match.group(
            "longueur_unit"
        )
    )

    weight = (
        match.group(
            "weight"
        )
    )

    description = (
        match.group(
            "description"
        )
        .strip()
    )


    # --------------------------------------------------------
    # Avoid duplicate matches for the same Item #.
    # --------------------------------------------------------

    if item_number in seen_item_numbers:

        continue


    seen_item_numbers.add(
        item_number
    )


    print(
        "\\n------------------------------------------------------------"
    )

    print(
        f"Item #{item_number}"
    )

    print(
        "------------------------------------------------------------"
    )

    print(
        "PCE Quantity:",
        pce_quantity
    )

    print(
        "LONGUEUR:",
        longueur_value
    )

    print(
        "LONGUEUR Unit:",
        longueur_unit
    )

    print(
        "POIDS:",
        weight
    )

    print(
        "Description:",
        description
    )


    # ========================================================
    # VALIDATE LONGUEUR UNIT
    # ========================================================

    if normalize_text(
        longueur_unit
    ) == "m":

        print(
            f"Item #{item_number} LONGUEUR unit = M: PASS"
        )

        validated_items.append(
            item_number
        )

    else:

        print(
            f"Item #{item_number} LONGUEUR unit = M: FAIL"
        )

        failed_items.append(
            {
                "item_number": item_number,
                "actual_unit": longueur_unit,
                "longueur": longueur_value,
                "pce": pce_quantity,
                "weight": weight,
                "description": description
            }
        )


# ============================================================
# 24. VERIFY AT LEAST ONE ITEM WAS FOUND
# ============================================================

assert validated_items or failed_items, (

    "\\nNo valid Item # records were extracted "
    "from the BOL PDF."
)


# ============================================================
# 25. REPORT FAILED ITEMS
# ============================================================

if failed_items:

    print(
        "\\n============================================================"
    )

    print(
        "LONGUEUR UNIT VALIDATION FAILED"
    )

    print(
        "============================================================"
    )


    for failed_item in failed_items:

        print(
            f"\\nItem #{failed_item[\'item_number\']}"
        )

        print(
            "Expected LONGUEUR Unit: M"
        )

        print(
            "Actual LONGUEUR Unit:",
            failed_item["actual_unit"]
        )

        print(
            "LONGUEUR:",
            failed_item["longueur"]
        )

        print(
            "PCE:",
            failed_item["pce"]
        )

        print(
            "POIDS:",
            failed_item["weight"]
        )

        print(
            "Description:",
            failed_item["description"]
        )


    raise AssertionError(

        "\\nLONGUEUR unit validation failed.\\n\\n"

        "Every Item # must have LONGUEUR unit = M.\\n\\n"

        f"Failed Items:\\n"
        f"{failed_items}\\n\\n"

        f"PDF URL:\\n"
        f"{pdf_url}\\n\\n"

        f"PDF Text:\\n"
        f"{pdf_text_normalized}"
    )


# ============================================================
# 26. FINAL ALL-ITEM VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "ALL ITEM LONGUEUR UNIT VALIDATION PASSED"
)

print(
    "============================================================"
)


print(
    "Items validated:",
    len(validated_items)
)


print(
    "Item Numbers:",
    ", ".join(
        sorted(
            validated_items,
            key=lambda x: int(x)
        )
    )
)


for item_number in sorted(
    validated_items,
    key=lambda x: int(x)
):

    print(
        f"Item #{item_number} "
        f"LONGUEUR Unit: PASS (M)"
    )


print(
    "============================================================"
)

print(
    "ALL ITEMS LONGUEUR UNIT = M: PASS"
)

print(
    "============================================================"
)


# ============================================================
# 27. VERIFY SAVED PDF
# ============================================================

with open(
    downloaded_pdf_path,
    "rb"
) as downloaded_pdf_file:

    downloaded_pdf_bytes = (
        downloaded_pdf_file.read()
    )


assert downloaded_pdf_bytes.startswith(
    b"%PDF"
), (
    "Saved PDF is not valid."
)


assert (
    downloaded_pdf_bytes
    == pdf_bytes
), (
    "Saved PDF bytes do not match "
    "the browser PDF response."
)


print(
    "Saved PDF bytes verification PASSED."
)


# ============================================================
# 28. RE-OPEN SAVED PDF
# ============================================================

downloaded_reader = PdfReader(
    BytesIO(
        downloaded_pdf_bytes
    )
)


assert len(
    downloaded_reader.pages
) > 0, (
    "Saved PDF contains no pages."
)


downloaded_pdf_text = ""


for downloaded_page in downloaded_reader.pages:

    downloaded_pdf_text += (
        downloaded_page.extract_text()
        or ""
    )

    downloaded_pdf_text += "\\n"


downloaded_pdf_text_normalized = (
    normalize_text(
        downloaded_pdf_text
    )
)


assert downloaded_pdf_text_normalized, (
    "Downloaded PDF text is empty."
)


# ============================================================
# 29. VERIFY ALL ITEM NUMBERS / LONGUEUR UNIT = M
#     AGAINST SAVED PDF
# ============================================================

print(
    "\\n============================================================"
)

print(
    "VERIFY ALL ITEM NUMBERS / LONGUEUR UNIT = M "
    "AGAINST SAVED PDF"
)

print(
    "============================================================"
)


# ------------------------------------------------------------
# Find all item rows again from the SAVED PDF text.
# ------------------------------------------------------------

saved_item_matches = list(
    item_row_pattern.finditer(
        downloaded_pdf_text_normalized
    )
)


print(
    "\\nPotential Item rows found in saved PDF:",
    len(saved_item_matches)
)


assert saved_item_matches, (

    "\\nNo Item rows could be identified "
    "in the saved BOL PDF.\\n\\n"

    f"Expected structure:\\n"

    "PCE Quantity + LONGUEUR + Unit + POIDS + "
    "Description + Item #\\n\\n"

    f"Saved PDF text:\\n"
    f"{downloaded_pdf_text_normalized}"
)


# ============================================================
# 30. VALIDATE ALL SAVED PDF ITEMS
# ============================================================

saved_validated_items = []

saved_failed_items = []

saved_seen_item_numbers = set()


for match in saved_item_matches:

    item_number = (
        match.group(
            "item_number"
        )
    )

    pce_quantity = (
        match.group(
            "pce"
        )
    )

    longueur_value = (
        match.group(
            "longueur"
        )
    )

    longueur_unit = (
        match.group(
            "longueur_unit"
        )
    )

    weight = (
        match.group(
            "weight"
        )
    )

    description = (
        match.group(
            "description"
        )
        .strip()
    )


    # --------------------------------------------------------
    # Avoid duplicate matches for the same Item #.
    # --------------------------------------------------------

    if item_number in saved_seen_item_numbers:

        continue


    saved_seen_item_numbers.add(
        item_number
    )


    print(
        "\\n------------------------------------------------------------"
    )

    print(
        f"Saved PDF Item #{item_number}"
    )

    print(
        "------------------------------------------------------------"
    )

    print(
        "PCE Quantity:",
        pce_quantity
    )

    print(
        "LONGUEUR:",
        longueur_value
    )

    print(
        "LONGUEUR Unit:",
        longueur_unit
    )

    print(
        "POIDS:",
        weight
    )

    print(
        "Description:",
        description
    )


    # ========================================================
    # VALIDATE SAVED PDF LONGUEUR UNIT
    # ========================================================

    if normalize_text(
        longueur_unit
    ) == "m":

        print(
            f"Saved PDF Item #{item_number} "
            f"LONGUEUR unit = M: PASS"
        )

        saved_validated_items.append(
            item_number
        )

    else:

        print(
            f"Saved PDF Item #{item_number} "
            f"LONGUEUR unit = M: FAIL"
        )

        saved_failed_items.append(
            {
                "item_number": item_number,
                "actual_unit": longueur_unit,
                "longueur": longueur_value,
                "pce": pce_quantity,
                "weight": weight,
                "description": description
            }
        )


# ============================================================
# 31. FAIL IF SAVED PDF HAS ANY INVALID ITEM
# ============================================================

if saved_failed_items:

    print(
        "\\n============================================================"
    )

    print(
        "SAVED PDF LONGUEUR UNIT VALIDATION FAILED"
    )

    print(
        "============================================================"
    )


    for failed_item in saved_failed_items:

        print(
            f"\\nItem #{failed_item[\'item_number\']}"
        )

        print(
            "Expected LONGUEUR Unit: M"
        )

        print(
            "Actual LONGUEUR Unit:",
            failed_item["actual_unit"]
        )

        print(
            "LONGUEUR:",
            failed_item["longueur"]
        )

        print(
            "PCE:",
            failed_item["pce"]
        )

        print(
            "POIDS:",
            failed_item["weight"]
        )

        print(
            "Description:",
            failed_item["description"]
        )


    raise AssertionError(

        "\\nSaved PDF LONGUEUR unit validation failed.\\n\\n"

        "Every Item # in the saved PDF must have "
        "LONGUEUR unit = M.\\n\\n"

        f"Failed Items:\\n"
        f"{saved_failed_items}\\n\\n"

        f"Saved PDF Text:\\n"
        f"{downloaded_pdf_text_normalized}"
    )


# ============================================================
# 32. VERIFY SAVED PDF ITEM COUNT
# ============================================================

assert (
    len(saved_validated_items)
    == len(validated_items)
), (

    "\\nItem count mismatch between original PDF "
    "and saved PDF.\\n\\n"

    f"Original PDF items: "
    f"{validated_items}\\n"

    f"Saved PDF items: "
    f"{saved_validated_items}"
)


# ============================================================
# 33. VERIFY SAVED PDF ITEM NUMBERS
# ============================================================

assert (
    set(saved_validated_items)
    == set(validated_items)
), (

    "\\nItem number mismatch between original PDF "
    "and saved PDF.\\n\\n"

    f"Original PDF items: "
    f"{validated_items}\\n"

    f"Saved PDF items: "
    f"{saved_validated_items}"
)


print(
    "\\n============================================================"
)

print(
    "SAVED PDF ALL-ITEM LONGUEUR VALIDATION PASSED"
)

print(
    "============================================================"
)


print(
    "Saved PDF Items validated:",
    len(saved_validated_items)
)


print(
    "Saved PDF Item Numbers:",
    ", ".join(
        sorted(
            saved_validated_items,
            key=lambda x: int(x)
        )
    )
)


for item_number in sorted(
    saved_validated_items,
    key=lambda x: int(x)
):

    print(
        f"Saved PDF Item #{item_number} "
        f"LONGUEUR Unit: PASS (M)"
    )


# ============================================================
# 34. FINAL VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "PRINT BOL PDF VALIDATION PASSED"
)

print(
    "============================================================"
)


print(
    f"All Item Numbers                  : PASS "
    f"({len(validated_items)} items)"
)


print(
    "All LONGUEUR Units                : PASS (M)"
)


print(
    "Print button                      : PASS"
)


print(
    "Print BOL menu                    : PASS"
)


print(
    "PDF HTTP response                 : PASS"
)


print(
    "PDF HTTP Status                   : PASS (200)"
)


print(
