)


print(
    "PDF is valid                      : PASS"
)


print(
    "Saved PDF is valid                : PASS"
)


print(
    "Saved PDF all Item Numbers        : PASS"
)


print(
    "Saved PDF all LONGUEUR Units      : PASS (M)"
)


print(
    "============================================================"
)


# ============================================================
# 35. CLEANUP
# ============================================================

