(13097,15783,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


def normalize_number(value):
    """
    Converts values such as:

        2
        2.0
        2.00
        2,00

    into:

        2
    """

    if value is None:
        return None

    value = str(value).strip()

    # Handle decimal comma
    value = value.replace(",", ".")

    try:

        number = float(value)

        if number.is_integer():
            return str(int(number))

        return f"{number:g}"

    except Exception:

        return value


# ============================================================
# 1. GET ITEM #2 ROW FROM UI
# ============================================================

print(
    "\\n============================================================"
)

print(
    "GETTING ITEM #2 QUANTITY ORDERED FROM UI"
)

print(
    "============================================================"
)


# ------------------------------------------------------------
# EXACT ITEM #2 ROW
# ------------------------------------------------------------

item2_row = page.locator(
    "//div[@data-id=\'2\' and @data-rowindex=\'1\']"
).first


expect(
    item2_row
).to_be_visible(
    timeout=10000
)


# ------------------------------------------------------------
# VERIFY ITEM #2 ROW
# ------------------------------------------------------------

item2_row_text = item2_row.inner_text()


print(
    "\\nItem #2 row text from UI:"
)

print(
    item2_row_text
)


# Verify row belongs to Item #2
item_number_cell = item2_row.locator(
    "div[data-field=\'orderItemSeqIdIndex\']"
).first


expect(
    item_number_cell
).to_be_visible(
    timeout=10000
)


ui_item_number = (
    item_number_cell.inner_text()
    .strip()
)


assert ui_item_number == "2", (
    "\\nIncorrect UI row located.\\n"
    f"Expected Item #: 2\\n"
    f"Actual Item #: {ui_item_number}\\n"
    f"Row text:\\n{item2_row_text}"
)


print(
    "UI Item #2 row verification PASSED."
)


# ============================================================
# 2. GET QTY ORDERED FROM UI
# ============================================================

print(
    "\\n============================================================"
)

print(
    "GETTING QTY ORDERED FROM UI"
)

print(
    "============================================================"
)


# ------------------------------------------------------------
# EXACT LOCATOR PROVIDED
#
# //div[@data-id=\'2\' and @data-rowindex=\'1\']
# //div[@data-field=\'quantity\']
# ------------------------------------------------------------

quantity_locator = page.locator(
    "//div[@data-id=\'2\' and @data-rowindex=\'1\']"
    "//div[@data-field=\'quantity\']"
).first


expect(
    quantity_locator
).to_be_visible(
    timeout=10000
)


ui_quantity_raw = (
    quantity_locator.inner_text()
)


ui_quantity_normalized = " ".join(
    ui_quantity_raw.split()
)


ui_quantity_numeric = normalize_number(
    ui_quantity_normalized
)


print(
    "\\nUI Qty Ordered:"
)

print(
    "Raw value:",
    ui_quantity_raw
)

print(
    "Normalized value:",
    ui_quantity_normalized
)

print(
    "Numeric value:",
    ui_quantity_numeric
)


assert ui_quantity_numeric is not None, (
    "\\nUnable to determine Qty Ordered from UI.\\n"
    f"Raw value: {ui_quantity_raw}"
)


ui_quantity_decimal = float(
    ui_quantity_numeric
)


print(
    "UI Qty Ordered as decimal:",
    f"{ui_quantity_decimal:.2f}"
)


# ============================================================
# 3. VERIFY UI QUANTITY IS 2
# ============================================================
#
# This is the value that must appear in the PDF PCE column.
# ============================================================

expected_pdf_pce_quantity = (
    ui_quantity_numeric
)


print(
    "\\nExpected PDF PCE quantity:",
    expected_pdf_pce_quantity
)


# ============================================================
# 4. LOCATE PRINT BUTTON
# ============================================================

print_button = page.locator(
    "//button[@id=\'print-button\' and normalize-space()=\'Print\']"
).first


expect(
    print_button
).to_be_visible(
    timeout=10000
)


expect(
    print_button
).to_be_enabled(
    timeout=10000
)


print(
    "\\nPrint button is visible and enabled."
)


# ============================================================
# 5. COUNT TABS BEFORE PRINT
# ============================================================

tabs_before = len(
    context.pages
)


print(
    "Tabs before clicking Print:",
    tabs_before
)


# ============================================================
# 6. OPEN PRINT MENU
# ============================================================

print(
    "\\n============================================================"
)

print(
    "OPENING PRINT MENU"
)

print(
    "============================================================"
)


print_bol_menu = page.get_by_role(
    "menuitem",
    name="Print BOL",
    exact=True
).last


# ------------------------------------------------------------
# Check whether menu is already open.
# ------------------------------------------------------------

try:

    if print_bol_menu.is_visible():

        print(
            "Print menu is already open."
        )

    else:

        print(
            "Print menu is closed."
        )

        print(
            "Clicking Print button once..."
        )

        print_button.click(
            force=True
        )

except Exception:

    print(
        "Print BOL menu item is not currently available."
    )

    print(
        "Clicking Print button once..."
    )

    print_button.click(
        force=True
    )


# ------------------------------------------------------------
# Wait for Print BOL menu item.
# ------------------------------------------------------------

try:

    expect(
        print_bol_menu
    ).to_be_visible(
        timeout=10000
    )

except Exception as e:

    print(
        "\\nPrint BOL menu item was not found."
    )

    print(
        "Current page URL:",
        page.url
    )

    print(
        "Current Print BOL count:",
        page.get_by_role(
            "menuitem",
            name="Print BOL",
            exact=True
        ).count()
    )

    raise AssertionError(
        "\\nPrint BOL menu could not be opened.\\n\\n"
        "The Print button was clicked, but the "
        "\'Print BOL\' menuitem did not become visible.\\n\\n"
        f"Original error:\\n{e}"
    )


assert print_bol_menu.is_visible(), (
    "\\nPrint BOL menu item is not visible."
)


print(
    "Print BOL menu opened successfully."
)


# ============================================================
# 7. PDF RESPONSE PREDICATE
# ============================================================

def is_bol_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_shipment_pdf = (
            "/api/scadmin/control/shipment.pdf"
            in response_url
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        return (
            is_shipment_pdf
            and is_pdf_content
        )

    except Exception:

        return False


# ============================================================
# 8. CLICK PRINT BOL
# ============================================================

print(
    "\\n============================================================"
)

print(
    "CLICKING PRINT BOL"
)

print(
    "============================================================"
)


pdf_response = None
pdf_page = None


try:

    # --------------------------------------------------------
    # Register listeners BEFORE clicking Print BOL.
    # --------------------------------------------------------

    with page.expect_response(
        is_bol_pdf_response,
        timeout=30000
    ) as pdf_response_info:

        with context.expect_page(
            timeout=30000
        ) as new_page_info:

            print_bol_menu.click(
                force=True
            )


    # --------------------------------------------------------
    # Get actual PDF browser response.
    # --------------------------------------------------------

    pdf_response = (
        pdf_response_info.value
    )


    # --------------------------------------------------------
    # Get newly opened PDF tab.
    # --------------------------------------------------------

    pdf_page = (
        new_page_info.value
    )


    print(
        "Print BOL clicked successfully."
    )

    print(
        "New PDF tab detected."
    )


except Exception as e:

    raise AssertionError(
        "\\nPrint BOL was clicked, but the "
        "PDF response/new tab was not detected.\\n\\n"
        f"Error: {e}"
    )


# ============================================================
# 9. WAIT FOR PDF TAB
# ============================================================

try:

    pdf_page.wait_for_load_state(
        "domcontentloaded",
        timeout=30000
    )

except Exception:

    # Chrome PDF viewer may not expose normal DOM state.
    pass


print(
    "PDF tab URL:",
    pdf_page.url
)


# ============================================================
# 10. VERIFY PDF RESPONSE
# ============================================================

pdf_url = pdf_response.url

pdf_status = pdf_response.status

pdf_content_type = (
    pdf_response.headers.get(
        "content-type",
        ""
    ).lower()
)


print(
    "\\n================ PDF RESPONSE ================"
)

print(
    "PDF URL:",
    pdf_url
)

print(
    "HTTP Status:",
    pdf_status
)

print(
    "Content-Type:",
    pdf_content_type
)

print(
    "=============================================="
)


assert pdf_status == 200, (

    "\\nPDF HTTP response failed.\\n"
    f"Expected: 200\\n"
    f"Actual: {pdf_status}\\n"
    f"URL: {pdf_url}"
)


print(
    "PDF HTTP response verification PASSED."
)


assert (
    "application/pdf"
    in pdf_content_type
), (

    "\\nExpected application/pdf.\\n"
    f"Actual Content-Type: {pdf_content_type}\\n"
    f"URL: {pdf_url}"
)


print(
    "PDF Content-Type verification PASSED."
)


# ============================================================
# 11. VERIFY NEW PDF TAB
# ============================================================

tabs_after = len(
    context.pages
)


print(
    "\\nTabs before clicking Print BOL:",
    tabs_before
)

print(
    "Tabs after clicking Print BOL:",
    tabs_after
)


assert tabs_after > tabs_before, (

    "\\nBOL PDF did not open in a new tab.\\n"
    f"Tabs before: {tabs_before}\\n"
    f"Tabs after: {tabs_after}"
)


print(
    "PDF opened in new tab successfully."
)


# ============================================================
# 12. GET PDF BYTES FROM BROWSER RESPONSE
# ============================================================
#
# Use the authenticated browser response directly.
# Do NOT use context.request.get(pdf_url).
# ============================================================

print(
    "\\nDownloading Print BOL PDF..."
)

print(
    "Reading PDF body from actual browser response..."
)


pdf_bytes = (
    pdf_response.body()
)


assert pdf_bytes, (
    "PDF response body is empty."
)


print(
    "PDF body downloaded successfully."
)

print(
    "PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 13. VERIFY PDF HEADER
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (

    "\\nDownloaded browser response is NOT a valid PDF.\\n"
    f"PDF URL: {pdf_url}\\n"
    f"HTTP Status: {pdf_status}\\n"
    f"Content-Type: {pdf_content_type}\\n"
    f"PDF body size: {len(pdf_bytes)} bytes\\n"
    f"First 100 bytes: {repr(pdf_bytes[:100])}"
)


print(
    "Downloaded PDF signature verification PASSED."
)


# ============================================================
# 14. SAVE PDF
# ============================================================

download_dir = "/tmp/downloads"


os.makedirs(
    download_dir,
    exist_ok=True
)


downloaded_pdf_path = os.path.join(
    download_dir,
    "Print_BOL.pdf"
)


if os.path.exists(
    downloaded_pdf_path
):

    os.remove(
        downloaded_pdf_path
    )


with open(
    downloaded_pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )


assert os.path.exists(
    downloaded_pdf_path
), (
    "Downloaded PDF file does not exist."
)


downloaded_file_size = (
    os.path.getsize(
        downloaded_pdf_path
    )
)


assert downloaded_file_size > 0, (
    "Downloaded PDF file is empty."
)


print(
    "\\nPDF saved successfully:",
    downloaded_pdf_path
)

print(
    "Downloaded PDF size:",
    downloaded_file_size,
    "bytes"
)

print(
    "PDF download verification PASSED."
)


# ============================================================
# 15. READ PDF WITH PYPDF
# ============================================================

reader = PdfReader(
    BytesIO(pdf_bytes)
)


assert len(
    reader.pages
) > 0, (
    "PDF contains no pages."
)


print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 16. EXTRACT PDF TEXT
# ============================================================

pdf_text = ""


for pdf_document_page in reader.pages:

    page_text = (
        pdf_document_page.extract_text()
        or ""
    )

    pdf_text += (
        page_text
        + "\\n"
    )


assert pdf_text.strip(), (
    "Unable to extract text from BOL PDF."
)


print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n=============================================="
)


# ============================================================
# 17. NORMALIZE PDF TEXT
# ============================================================

pdf_text_normalized = normalize_text(
    pdf_text
)


print(
    "\\nNormalized PDF text:"
)

print(
    pdf_text_normalized
)


# ============================================================
# 18. VALIDATE ITEM #2 PCE QUANTITY
# ============================================================
#
# IMPORTANT:
#
# We ONLY validate:
#
#     UI Qty Ordered = 2.00
#
# against:
#
#     PDF Item #2 PCE = 2
#
# We DO NOT validate:
#
#     Length
#     Unit
#     Weight
#     Product Description
#     Other PDF fields
#
# In the PDF, the Item #2 row is structured like:
#
#     2    80.00    PI    8,080    ...    2
#     ^
#     |
#     PCE quantity
#
# The final 2 is the Item #.
#
# Therefore the validation checks that Item #2\'s row starts
# with the UI Qty Ordered value.
# ============================================================

print(
    "\\n============================================================"
)

print(
    "VALIDATING ITEM #2 PCE QUANTITY"
)

print(
    "============================================================"
)


print(
    "UI Qty Ordered:",
    ui_quantity_raw
)

print(
    "Normalized UI Qty Ordered:",
    expected_pdf_pce_quantity
)

print(
    "Expected PDF PCE Quantity:",
    expected_pdf_pce_quantity
)


# ------------------------------------------------------------
# Find Item #2 PDF row.
#
# The BOL table row starts with the PCE quantity and ends
# with Item #2.
#
# We intentionally do NOT compare the other columns.
# ------------------------------------------------------------

expected_pce_pattern = re.escape(
    expected_pdf_pce_quantity
)


item2_pdf_row_pattern = re.compile(

    r"(?:^|\\s)"

    # PCE quantity at beginning of row
    + expected_pce_pattern

    + r"(?:\\.0+)?"

    # Everything else in the Item #2 row is ignored.
    + r"\\s+"

    + r".*?"

    # Item #2 at the end of the row.
    + r"\\s+2"

    + r"(?:\\s|$)",

    re.IGNORECASE
)


item2_pdf_match = (
    item2_pdf_row_pattern.search(
        pdf_text_normalized
    )
)


# ============================================================
# 19. FALLBACK ITEM #2 PCE VALIDATION
# ============================================================
#
# PDF text extraction can sometimes place the table contents
# on separate lines.
#
# If the full-row regex does not match, we use a simpler
# validation based on the PDF table structure:
#
#     <PCE quantity> ... <Item # 2>
#
# Again, no other field is compared.
# ============================================================

if item2_pdf_match:

    matched_pdf_row = (
        item2_pdf_match.group(0).strip()
    )

    print(
        "\\nItem #2 PDF row located successfully."
    )

    print(
        "Matched PDF row:"
    )

    print(
        matched_pdf_row
    )

else:

    print(
        "\\nFull Item #2 row pattern did not match."
    )

    print(
        "Attempting fallback PCE quantity validation..."
    )


    # --------------------------------------------------------
    # Find occurrences of Item #2.
    # --------------------------------------------------------

    item2_occurrences = list(
        re.finditer(
            r"(?:^|\\s)2(?:\\s|$)",
            pdf_text_normalized
        )
    )


    assert item2_occurrences, (

        "\\nItem #2 was not found in BOL PDF.\\n\\n"

        f"Expected PDF PCE quantity: "
        f"{expected_pdf_pce_quantity}\\n\\n"

        f"PDF URL:\\n"
        f"{pdf_url}\\n\\n"

        f"PDF Text:\\n"
        f"{pdf_text_normalized}"
    )


    pce_quantity_found = False


    # --------------------------------------------------------
    # Inspect text around Item #2 occurrences.
    #
    # We only care whether the expected PCE quantity appears
    # before Item #2 in the same extracted row/region.
    # --------------------------------------------------------

    for occurrence in item2_occurrences:

        start_position = (
            occurrence.start()
        )

        # Look backward for a reasonable table-row boundary.
        previous_newline = (
            pdf_text_normalized.rfind(
                "\\n",
                0,
                start_position
            )
        )

        if previous_newline == -1:

            row_start = 0

        else:

            row_start = (
                previous_newline + 1
            )


        row_text = (
            pdf_text_normalized[
                row_start:
                occurrence.end()
            ]
        )


        print(
            "\\nCandidate Item #2 PDF text:"
        )

        print(
            row_text
        )


        # ----------------------------------------------------
        # The first meaningful numeric token in the row must
        # equal the UI Qty Ordered.
        # ----------------------------------------------------

        first_number_match = re.search(
            r"(?<![\\w.])\\d+(?:\\.\\d+)?",
            row_text
        )


        if not first_number_match:

            continue


        first_pdf_number = normalize_number(
            first_number_match.group(0)
        )


        print(
            "First numeric value in candidate row:",
            first_pdf_number
        )


        if (
            first_pdf_number
            == expected_pdf_pce_quantity
        ):

            pce_quantity_found = True

            print(
                "Expected PCE quantity found "
                "for Item #2."
            )

            break


    assert pce_quantity_found, (

        "\\nItem #2 PCE quantity mismatch.\\n\\n"

        f"UI Qty Ordered: "
        f"{ui_quantity_numeric}\\n"

        f"Expected PDF PCE quantity: "
        f"{expected_pdf_pce_quantity}\\n\\n"

        "The expected quantity was not found "
        "as the PCE quantity for Item #2.\\n\\n"

        f"PDF URL:\\n"
        f"{pdf_url}\\n\\n"

        f"PDF Text:\\n"
        f"{pdf_text_normalized}"
    )


# ============================================================
# 20. FINAL UI/PDF QUANTITY COMPARISON
# ============================================================

pdf_pce_quantity = (
    expected_pdf_pce_quantity
)


print(
    "\\n============================================================"
)

print(
    "UI / PDF PCE QUANTITY COMPARISON"
)

print(
    "============================================================"
)

print(
    "UI Qty Ordered:",
    ui_quantity_numeric
)

print(
    "PDF PCE Quantity:",
    pdf_pce_quantity
)


assert (
    float(ui_quantity_numeric)
    == float(pdf_pce_quantity)
), (

    "\\nQty Ordered / PCE quantity mismatch.\\n"

    f"UI Qty Ordered: "
    f"{ui_quantity_numeric}\\n"

    f"PDF PCE Quantity: "
    f"{pdf_pce_quantity}"
)


print(
    "\\nUI/PDF PCE quantity comparison PASSED."
)


# ============================================================
# 21. VERIFY SAVED PDF
# ============================================================

with open(
    downloaded_pdf_path,
    "rb"
) as downloaded_pdf_file:

    downloaded_pdf_bytes = (
        downloaded_pdf_file.read()
    )


assert downloaded_pdf_bytes.startswith(
    b"%PDF"
), (
    "Saved PDF is not valid."
)


assert (
    downloaded_pdf_bytes
    == pdf_bytes
), (
    "Saved PDF bytes do not match "
    "the browser PDF response."
)


print(
    "Saved PDF bytes verification PASSED."
)


# ============================================================
# 22. RE-OPEN SAVED PDF
# ============================================================

downloaded_reader = PdfReader(
    BytesIO(
        downloaded_pdf_bytes
    )
)


assert len(
    downloaded_reader.pages
) > 0, (
    "Saved PDF contains no pages."
)


downloaded_pdf_text = ""


for downloaded_page in downloaded_reader.pages:

    downloaded_pdf_text += (
        downloaded_page.extract_text()
        or ""
    )

    downloaded_pdf_text += "\\n"


downloaded_pdf_text_normalized = (
    normalize_text(
        downloaded_pdf_text
    )
)


assert downloaded_pdf_text_normalized, (
    "Downloaded PDF text is empty."
)


# ============================================================
# 23. VERIFY PCE QUANTITY AGAINST SAVED PDF
# ============================================================
#
# We repeat only the PCE quantity validation on the actual
# saved PDF. No other fields are checked.
# ============================================================

saved_pdf_item2_pattern = re.compile(

    r"(?:^|\\s)"

    + re.escape(
        expected_pdf_pce_quantity
    )

    + r"(?:\\.0+)?"

    + r"\\s+"

    + r".*?"

    + r"\\s+2"

    + r"(?:\\s|$)",

    re.IGNORECASE
)


saved_pdf_item2_match = (
    saved_pdf_item2_pattern.search(
        downloaded_pdf_text_normalized
    )
)


if saved_pdf_item2_match:

    print(
        "\\nSaved PDF Item #2 PCE quantity found."
    )

    print(
        "Saved PDF matched text:"
    )

    print(
        saved_pdf_item2_match.group(0).strip()
    )

else:

    # --------------------------------------------------------
    # Fallback: verify expected PCE quantity exists in the
    # saved PDF text before Item #2.
    # --------------------------------------------------------

    saved_pdf_item2_occurrences = list(
        re.finditer(
            r"(?:^|\\s)2(?:\\s|$)",
            downloaded_pdf_text_normalized
        )
    )


    saved_pdf_pce_quantity_found = False


    for occurrence in saved_pdf_item2_occurrences:

        start_position = (
            occurrence.start()
        )


        previous_newline = (
            downloaded_pdf_text_normalized.rfind(
                "\\n",
                0,
                start_position
            )
        )


        if previous_newline == -1:

            row_start = 0

        else:

            row_start = (
                previous_newline + 1
            )


        row_text = (
            downloaded_pdf_text_normalized[
                row_start:
                occurrence.end()
            ]
        )


        first_number_match = re.search(
            r"(?<![\\w.])\\d+(?:\\.\\d+)?",
            row_text
        )


        if not first_number_match:

            continue


        first_pdf_number = normalize_number(
            first_number_match.group(0)
        )


        if (
            first_pdf_number
            == expected_pdf_pce_quantity
        ):

            saved_pdf_pce_quantity_found = True

            break


    assert saved_pdf_pce_quantity_found, (

        "\\nSaved PDF Item #2 PCE quantity "
        "verification failed.\\n\\n"

        f"Expected PCE quantity: "
        f"{expected_pdf_pce_quantity}\\n\\n"

        f"Saved PDF text:\\n"
        f"{downloaded_pdf_text_normalized}"
    )


print(
    "Saved PDF Item #2 PCE quantity verification PASSED."
)


# ============================================================
# 24. FINAL VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "PRINT BOL PCE QUANTITY VALIDATION PASSED"
)

print(
    "============================================================"
)

print(
