(13286,15964,'custom','import re
from playwright.sync_api import expect

# -----------------------------------------
# Active Dialog
# -----------------------------------------
dialog = page.locator("div[role=\'dialog\']").last
expect(dialog).to_be_visible()

# -----------------------------------------
# Pagination
# -----------------------------------------
pagination = dialog.locator(
    "p.MuiTablePagination-displayedRows"
).inner_text().strip()

print("Pagination :", pagination)

match = re.search(r"of\\s+(\\d+)", pagination)
if not match:
    raise Exception("Unable to read pagination.")

total_rows = int(match.group(1))
print("Total Rows :", total_rows)

visited = set()
selected = False

while not selected:

    # Get currently visible rows
    rows = dialog.locator("div[role=\'row\'][data-id]")

    visible_rows = rows.count()
    print("Visible Rows :", visible_rows)

    for i in range(visible_rows):

        try:
            current_row = rows.nth(i)
            current_row.scroll_into_view_if_needed()

            row_id = current_row.get_attribute("data-id")

            if not row_id:
                continue

            if row_id in visited:
                continue

            visited.add(row_id)

            stock_locator = current_row.locator(
                "div[data-field=\'stockOnSoLBS\']"
            )

            net_locator = current_row.locator(
                "div[data-field=\'netStockAvailableAfterBulkTransferLBS\']"
            )

            if stock_locator.count() == 0 or net_locator.count() == 0:
                print(f"Cells not found for Row : {row_id}")
                continue

            stock = float(
                stock_locator.inner_text().replace(",", "").strip() or "0"
            )

            net = float(
                net_locator.inner_text().replace(",", "").strip() or "0"
            )

            print(f"Row={row_id}  Stock={stock}  Net={net}")

            if stock == 0 and net == 0:

                print("Matching Row Found")

                checkbox = current_row.locator(
                    "xpath=.//input[@type=\'checkbox\' and @aria-label=\'Select row\']"
                )

                checkbox.scroll_into_view_if_needed()
                checkbox.click(force=True)

                print("Checkbox clicked successfully.")

                selected = True
                break

        except Exception as e:
            print(f"Row {i} Error : {e}")

    if selected:
        break

    if len(visited) >= total_rows:
        break

    # Scroll the virtual grid
    dialog.locator(".MuiDataGrid-virtualScroller").evaluate(
        "(element) => element.scrollBy(0, 600)"
    )

    page.wait_for_timeout(700)

if not selected:
    raise Exception("Matching row not found")

print("Script completed successfully.")','import re
