(13952,16724,'custom','from playwright.sync_api import expect

previous_cumulative_qty = get_var("current_cumulative_qty")

cumulative_qty_cell = page.locator(
    "//div[@role=\'gridcell\' and @data-field=\'currentStockPCS\']"
).last

expect(cumulative_qty_cell).to_be_visible()

new_cumulative_qty = int(
    cumulative_qty_cell.text_content().strip().replace(",", "")
)

expected_cumulative_qty = previous_cumulative_qty + 5

assert new_cumulative_qty == expected_cumulative_qty, (
    f"Expected Cumulative Qty to be {expected_cumulative_qty}, "
    f"but found {new_cumulative_qty}"
)

print(f"Previous: {previous_cumulative_qty}")
print(f"Current: {new_cumulative_qty}")
