(14417,17167,'custom','from playwright.sync_api import expect

page.wait_for_load_state("networkidle")

while True:
    rows = page.locator("xpath=//div[@role=\'row\' and @data-rowindex]")

    found = False

    for i in range(rows.count()):
        row = rows.nth(i)

        # Shipment Status
        shipment_status = (
            row.locator("xpath=.//div[@data-field=\'shipmentStatusIdDesc\']")
            .text_content() or ""
        ).strip()

        # Order Status
        order_status = (
            row.locator("xpath=.//div[@data-field=\'statusStr\']//button")
            .get_attribute("title") or ""
        ).strip()

        # Order Number
        order_number = (
            row.locator("xpath=.//div[@data-field=\'orderId\']")
            .text_content() or ""
        ).strip()

        # Click Edit only if:
        # 1. Shipment Status is blank
        # 2. Status is ORDER_APPROVED
        # 3. Order Number does NOT start with EAS
        if (
            shipment_status == ""
            and order_status == "ORDER_APPROVED"
            and not order_number.startswith("EAS")
        ):
            row.locator("xpath=.//*[@title=\'Edit\']").click()
            found = True
            break

    if found:
        break

    # Scroll to load more rows
    last_row = rows.last
    previous_index = last_row.get_attribute("data-rowindex")

    last_row.scroll_into_view_if_needed()
    page.mouse.wheel(0, 1200)
    page.wait_for_timeout(1000)

    # Stop if no new rows are loaded
    new_last_index = page.locator(
        "xpath=//div[@role=\'row\' and @data-rowindex]"
    ).last.get_attribute("data-rowindex")

    if previous_index == new_last_index:
        raise Exception(
            "No row found with blank Shipment Status, ORDER_APPROVED status, and Order # not starting with EAS."
        )','from playwright.sync_api import expect

page.wait_for_load_state("networkidle")

while True:
    # Get all visible rows
    rows = page.locator("//div[@role=\'row\' and @data-rowindex]")

    found = False

    for i in range(rows.count()):
        row = rows.nth(i)

        shipment_status = (
            row.locator(".//div[@data-field=\'shipmentStatusIdDesc\']")
            .inner_text()
            .strip()
        )

        if shipment_status == "":
            row.locator(".//button[@title=\'Edit\']").click()
            found = True
            break

    if found:
        break

    # Scroll to load more rows
    last_row = rows.last
    previous_index = last_row.get_attribute("data-rowindex")

    last_row.scroll_into_view_if_needed()
    page.mouse.wheel(0, 1200)
    page.wait_for_timeout(1000)

    # Stop if no new rows are loaded
    new_last_index = page.locator("//div[@role=\'row\' and @data-rowindex]").last.get_attribute("data-rowindex")
    if previous_index == new_last_index:
        raise Exception("No row found with blank Shipment Status.")','PENDING','2026-08-03 03:23:09','2026-08-03 03:23:09',NULL,NULL),
