(14532,17283,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.

    Handles:
    - whitespace
    - accents
    - non-breaking spaces
    - punctuation spacing
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


def normalize_number(value):
    """
    Converts UI quantity such as:

        2
        2.0
        2.00
        2,00

    into:

        2
    """

    if value is None:
        return None

    value = str(value).strip()

    value = value.replace(",", ".")

    try:

        number = float(value)

        if number.is_integer():
            return str(int(number))

        return f"{number:g}"

    except Exception:

        return value


def text_contains_all_tokens(text, tokens):
    """
    Returns True when every meaningful token exists
    in the normalized text.
    """

    normalized = normalize_text(text)

    for token in tokens:

        normalized_token = normalize_text(
            token
        )

        if not normalized_token:
            continue

        if normalized_token not in normalized:

            return False

    return True


# ============================================================
# 1. CAPTURE DYNAMIC MANAGE SHIPMENT VALUES FROM UI
# ============================================================

print(
    "\\n============================================================"
)

print(
    "CAPTURING MANAGE SHIPMENT VALUES FROM UI"
)

print(
    "============================================================"
)


# ============================================================
# HELPER - GET DYNAMIC FIELD VALUE FROM MANAGE SHIPMENT
# ============================================================

def get_manage_shipment_field_value(page, field_label):
    """
    Dynamically retrieves a Manage Shipment field value.

    Handles:
        - normal <input>
        - readonly <input>
        - textarea
        - select
        - role=combobox
        - buttons used by dropdown controls
        - visible text inside the field container

    The value is located relative to the field label instead
    of using a global following::input[1] locator.
    """

    print(
        f"\\nLocating Manage Shipment field: {field_label}"
    )

    # --------------------------------------------------------
    # Find the visible label/text
    # --------------------------------------------------------

    label_candidates = [
        page.get_by_text(
            field_label,
            exact=True
        ).filter(
            visible=True
        ),
        page.locator(
            f"//*[normalize-space()=\'{field_label}\']"
        ).filter(
            visible=True
        )
    ]

    label = None

    for candidate in label_candidates:

        try:

            count = candidate.count()

            for i in range(count):

                current = candidate.nth(i)

                if current.is_visible():

                    label = current
                    break

            if label is not None:
                break

        except Exception:
            continue

    if label is None:

        raise AssertionError(
            f"\\nCould not locate visible Manage Shipment "
            f"field label: {field_label}"
        )

    print(
        f"Found field label: {field_label}"
    )

    # ========================================================
    # STRATEGY 1 - INPUT INSIDE NEAREST FIELD CONTAINER
    # ========================================================

    try:

        input_locator = label.locator(
            "xpath=ancestor::*[.//input][1]//input"
        ).filter(
            visible=True
        )

        if input_locator.count() > 0:

            for i in range(
                input_locator.count()
            ):

                field = input_locator.nth(i)

                try:

                    value = field.input_value(
                        timeout=3000
                    )

                except Exception:

                    value = ""

                value = " ".join(
                    str(value).split()
                ).strip()

                if value:

                    print(
                        f"{field_label} captured from input: "
                        f"{value}"
                    )

                    return value

    except Exception:
        pass

    # ========================================================
    # STRATEGY 2 - TEXTAREA
    # ========================================================

    try:

        textarea_locator = label.locator(
            "xpath=ancestor::*[.//textarea][1]//textarea"
        ).filter(
            visible=True
        )

        if textarea_locator.count() > 0:

            for i in range(
                textarea_locator.count()
            ):

                field = textarea_locator.nth(i)

                try:

                    value = field.input_value(
                        timeout=3000
                    )

                except Exception:

                    value = ""

                value = " ".join(
                    str(value).split()
                ).strip()

                if value:

                    print(
                        f"{field_label} captured from textarea: "
                        f"{value}"
                    )

                    return value

    except Exception:
        pass

    # ========================================================
    # STRATEGY 3 - COMBOBOX
    # ========================================================

    try:

        combo_locator = label.locator(
            "xpath=ancestor::*[.//*[@role=\'combobox\']][1]"
            "//*[@role=\'combobox\']"
        ).filter(
            visible=True
        )

        if combo_locator.count() > 0:

            for i in range(
                combo_locator.count()
            ):

                combo = combo_locator.nth(i)

                # Try input value first
                try:

                    value = combo.input_value(
                        timeout=3000
                    )

                except Exception:

                    value = ""

                value = " ".join(
                    str(value).split()
                ).strip()

                if value:

                    print(
                        f"{field_label} captured from combobox "
                        f"input value: {value}"
                    )

                    return value

                # Try text content
                try:

                    value = combo.inner_text(
                        timeout=3000
                    )

                except Exception:

                    value = ""

                value = " ".join(
                    str(value).split()
                ).strip()

                if value:

                    print(
                        f"{field_label} captured from combobox "
                        f"text: {value}"
                    )

                    return value

    except Exception:
        pass

    # ========================================================
    # STRATEGY 4 - BUTTON / DROPDOWN FIELD
    # ========================================================

    try:

        button_locator = label.locator(
            "xpath=ancestor::*[.//button][1]//button"
        ).filter(
            visible=True
        )

        if button_locator.count() > 0:

            for i in range(
                button_locator.count()
            ):

                button = button_locator.nth(i)

                try:

                    value = button.inner_text(
                        timeout=3000
                    )

                except Exception:

                    value = ""

                value = " ".join(
                    str(value).split()
                ).strip()

                if value:

                    print(
                        f"{field_label} captured from button: "
                        f"{value}"
                    )

                    return value

    except Exception:
        pass

    # ========================================================
    # STRATEGY 5 - FIELD CONTAINER TEXT
    # ========================================================

    try:

        container = label.locator(
            "xpath=ancestor::*["
            ".//input or "
            ".//textarea or "
            ".//button or "
            ".//*[@role=\'combobox\']"
            "][1]"
        )

        if container.count() > 0:

            for i in range(
                container.count()
            ):

                current_container = (
                    container.nth(i)
                )

                if not current_container.is_visible():
                    continue

                try:

                    value = (
                        current_container.inner_text(
                            timeout=3000
                        )
                    )

                except Exception:

                    value = ""

                value = " ".join(
                    str(value).split()
                ).strip()

                # Remove the field label itself
                normalized_label = normalize_text(
                    field_label
                )

                normalized_value = normalize_text(
                    value
                )

                if (
                    normalized_value
                    and normalized_value
                    != normalized_label
                ):

                    print(
                        f"{field_label} captured from "
                        f"field container: {value}"
                    )

                    return value

    except Exception:
        pass

    # ========================================================
    # STRATEGY 6 - JAVASCRIPT ATTRIBUTE/VALUE FALLBACK
    # ========================================================

    try:

        parent = label.locator(
            "xpath=.."
        )

        # Look for elements near the label
        elements = parent.locator(
            "input, textarea, button, "
            "[role=\'combobox\'], "
            "[role=\'button\'], "
            "select"
        ).filter(
            visible=True
        )

        for i in range(
            elements.count()
        ):

            element = elements.nth(i)

            try:

                extracted = element.evaluate(
                    """
                    el => {
                        return (
                            el.value ||
                            el.innerText ||
                            el.textContent ||
                            el.getAttribute(\'aria-label\') ||
                            el.getAttribute(\'title\') ||
                            \'\'
                        );
                    }
                    """
                )

            except Exception:

                extracted = ""

            extracted = " ".join(
                str(extracted).split()
            ).strip()

            if extracted:

                print(
                    f"{field_label} captured using "
                    f"fallback: {extracted}"
                )

                return extracted

    except Exception:
        pass

    # ========================================================
    # NOTHING FOUND
    # ========================================================

    raise AssertionError(
        f"\\nUnable to capture value for "
        f"Manage Shipment field: {field_label}\\n\\n"
        "The field was located, but no value could be "
        "extracted from input, textarea, combobox, button, "
        "or field container."
    )


