def is_bol_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_shipment_pdf = (
            "/api/scadmin/control/shipment.pdf"
            in response_url
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        return (
            is_shipment_pdf
            and is_pdf_content
        )

    except Exception:

        return False


