(14622,17375,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.

    Handles:
    - whitespace
    - accents
    - non-breaking spaces
    - punctuation spacing
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


# ============================================================
# 1. CAPTURE SHIPPING INSTRUCTIONS FROM EDIT SHIPMENT
# ============================================================

