(14625,17379,'custom','from playwright.sync_api import expect
import re

order_locator = page.locator(
    "xpath=//span[contains(@class,\'MuiTypography-caption\') and contains(.,\'Order # :\')]"
)

expect(order_locator).to_be_visible(timeout=15000)

text = order_locator.inner_text().strip()

order_number = re.search(r"Order\\s*#\\s*:\\s*(\\S+)", text).group(1)

set_var("order_number", order_number)

print(order_number)','from playwright.sync_api import expect
