pdf_page = None


try:

    with page.expect_response(
        is_bol_pdf_response,
        timeout=30000
    ) as pdf_response_info:

        with context.expect_page(
            timeout=30000
        ) as new_page_info:

            print_bol_menu.click(
                force=True
            )


    pdf_response = (
        pdf_response_info.value
    )

    pdf_page = (
        new_page_info.value
    )


    print(
        "Print BOL clicked successfully."
    )

    print(
        "New PDF tab detected."
    )


except Exception as e:

    raise AssertionError(
        "\\nPrint BOL was clicked, "
        "but the PDF response/new tab "
        "was not detected.\\n\\n"

