(14660,17415,'custom','from playwright.sync_api import expect

# Locate the first Product ID cell
product_id_cell = page.locator("//div[@data-id=\'1\' and @data-rowindex=\'0\']//div[@data-field=\'productId\']")

# Verify it is visible
expect(product_id_cell).to_be_visible()

# Capture Product ID value
