(15069,17828,'custom','from datetime import datetime, timedelta
from playwright.sync_api import expect

# Calculate date 3 days from today
target_date = datetime.now() + timedelta(days=3)
target_day = str(target_date.day)
target_month_year = target_date.strftime("%B %Y")

# Click the calendar icon (NOT the input)
calendar_btn = page.locator(
    "//button[contains(@aria-label,\'Choose date\')]"
)
expect(calendar_btn).to_be_visible()
calendar_btn.click()

# Wait for calendar to open by checking month/year
month_header = page.locator(
    "//div[contains(@class,\'MuiPickersCalendarHeader-root\')]//div[contains(text(),\',\') or contains(text(),\'20\')]"
).first

expect(month_header).to_be_visible()

# Navigate to the required month if needed
next_btn = page.locator(
    "(//button[contains(@class,\'MuiPickersArrowSwitcher-button\')])[2]"
)

while target_month_year not in month_header.inner_text():
    next_btn.click()
    page.wait_for_timeout(300)

# Select the target day
page.locator(
    f"//button[@role=\'gridcell\' and normalize-space()=\'{target_day}\' and not(@disabled)]"
).click()

print(f"Shipment Date selected: {target_date.strftime(\'%m/%d/%Y\')}")','from datetime import datetime, timedelta
from playwright.sync_api import expect

# Calculate date 3 days from today
target_date = datetime.now() + timedelta(days=3)
target_day = str(target_date.day)
target_month_year = target_date.strftime("%B %Y")

# Click Shipment Date input
shipment_date = page.locator("//input[@placeholder=\'MM/DD/YYYY\']")
expect(shipment_date).to_be_visible()
shipment_date.click()

# Wait for calendar popup
calendar_header = page.locator("//div[contains(@class,\'MuiPickersCalendarHeader-label\')]")
expect(calendar_header).to_be_visible()

# Navigate to target month/year if different
while calendar_header.inner_text().strip() != target_month_year:
    page.locator("//button[@title=\'Next month\']").click()

# Click the target day
page.locator(
    f"//button[@role=\'gridcell\' and normalize-space()=\'{target_day}\' and not(@disabled)]"
).click()

print(f"Shipment Date selected: {target_date.strftime(\'%m/%d/%Y\')}")','passed','2026-08-06 02:54:25','2026-09-05 11:46:29','Shipment Date selected: 09/08/2026',NULL),
