(15089,17848,'custom','from datetime import datetime, timedelta
from playwright.sync_api import expect

# Read the selected Shipment Date (08/09/2026)
shipment_date_input = page.locator("//input[@placeholder=\'MM/DD/YYYY\']")
shipment_date = shipment_date_input.input_value().strip()

# Calculate invalid date (Shipment Date + 3 days)
invalid_date = datetime.strptime(shipment_date, "%m/%d/%Y") + timedelta(days=3)
invalid_day = str(invalid_date.day)
invalid_month_year = invalid_date.strftime("%B %Y")

# Open the calendar
calendar_btn = page.locator("//button[contains(@aria-label,\'Choose date\')]")
expect(calendar_btn).to_be_visible()
calendar_btn.click()

# Get displayed month
calendar_header = page.locator(
    "//div[contains(@class,\'MuiPickersCalendarHeader-label\')]"
).last

expect(calendar_header).to_be_visible()

# Navigate to the target month if required
next_btn = page.locator(
    "(//button[contains(@class,\'MuiPickersArrowSwitcher-button\')])[2]"
)

while calendar_header.inner_text().strip() != invalid_month_year:
    next_btn.click()
    expect(calendar_header).to_have_text(invalid_month_year)

# Locate the invalid date
invalid_day_btn = page.locator(
