print(f"Verified {invalid_date.strftime(\'%m/%d/%Y\')} is disabled.")','from datetime import datetime, timedelta
from playwright.sync_api import expect

# Read the currently selected shipment date (e.g. 08/09/2026)
shipment_date_input = page.locator("//input[@placeholder=\'MM/DD/YYYY\']")
current_shipment_date = shipment_date_input.input_value().strip()

# Calculate invalid date (Shipment Date + 3 days)
invalid_date = datetime.strptime(current_shipment_date, "%m/%d/%Y") + timedelta(days=3)
invalid_day = str(invalid_date.day)
invalid_month_year = invalid_date.strftime("%B %Y")

# Open calendar
page.locator("//button[contains(@aria-label,\'Choose date\')]").click()

# Navigate to the required month if necessary
month_header = page.locator(
    "//div[contains(@class,\'MuiPickersCalendarHeader-label\')]"
)

next_btn = page.locator(
    "(//button[contains(@class,\'MuiPickersArrowSwitcher-button\')])[2]"
)

while month_header.inner_text().strip() != invalid_month_year:
    next_btn.click()
    page.wait_for_timeout(300)

# Try to select Shipment Date + 3 days (e.g. 08/12/2026)
invalid_day_btn = page.locator(
    f"//button[@role=\'gridcell\' and normalize-space()=\'{invalid_day}\']"
)

expect(invalid_day_btn).to_be_visible()

try:
    invalid_day_btn.click(timeout=2000)
except Exception:
    print("Date is not clickable, as expected.")

# Verify Shipment Date has NOT changed
expect(shipment_date_input).to_have_value(current_shipment_date)

print(
    f"Verified user cannot select {invalid_date.strftime(\'%m/%d/%Y\')}. "
    f"Shipment Date remains {current_shipment_date}."
)','passed','2026-08-06 06:44:05','2026-09-05 11:48:28','Verified 09/11/2026 is disabled.',NULL),
