(15764,18530,'custom','from playwright.sync_api import expect

# Locate the FIND PARTY dialog
dialog = page.get_by_role("dialog")

expect(dialog).to_be_visible()

# Get the first customer row
# nth(0) = header row
# nth(1) = first customer row
first_row = dialog.get_by_role("row").nth(1)

expect(first_row).to_be_visible()

# Capture the first Customer ID
# Grid cells:
# nth(0) = Add
# nth(1) = Customer ID
customer_id_cell = first_row.get_by_role("gridcell").nth(1)

expect(customer_id_cell).to_be_visible()

customer_id = customer_id_cell.inner_text().strip()

print(f"First Customer ID: {customer_id}")

# Locate and click the Add (+) button
add_button = first_row.get_by_role(
    "button",
    name="Add"
)

expect(add_button).to_be_visible()
add_button.click()


set_var("customer_id",customer_id)

print(f"Clicked Add button for Customer ID: {customer_id}")','from playwright.sync_api import expect

