(16274,19022,'custom','import os
import csv


# ============================================================
# Export Daily Stock Movement Report as CSV
# ============================================================

export_button = page.locator(
    "xpath=//span[text()=\'Export as CSV\']"
)

expect(export_button).to_be_visible()

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value


# ============================================================
# Download Information
# ============================================================

filename = download.suggested_filename

print("Filename:", filename)


# ============================================================
# Download Location
# ============================================================

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)


# ============================================================
# Save Downloaded File
# ============================================================

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print(
    "Saved file:",
    file_path
)


# ============================================================
# Verify File Exists
# ============================================================

assert os.path.exists(file_path), (
    f"File was not saved: {file_path}"
)


# ============================================================
# Verify File Is Not Empty
# ============================================================

assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)


# ============================================================
# Verify Daily Stock Movement Report CSV
# ============================================================

daily_stock_file = file_path

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded: {filename}"
)

print(
    "Daily Stock Movement Report CSV found successfully."
)


# ============================================================
# Read CSV
# ============================================================

with open(
    daily_stock_file,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)

    rows = list(reader)


# ============================================================
# Verify CSV Contains Data
# ============================================================

assert len(rows) >= 2, (
    "Daily Stock Movement Report.csv "
    "does not contain expected data."
)


# ============================================================
# Find Header Row
# ============================================================

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip()
        for column in row
    ]

    if (
        "Qty Change (+/- Pcs)" in cleaned_row
        and "Qty Change (+/-)" in cleaned_row
    ):

        header_row_index = index

        break


assert header_row_index is not None, (
    "Qty Change (+/- Pcs) and "
    "Qty Change (+/-) columns were not found."
)


# ============================================================
# Get Headers
# ============================================================

headers = [
    column.strip()
    for column in rows[header_row_index]
]


# ============================================================
# Get Column Indexes
# ============================================================

pcs_column_index = headers.index(
    "Qty Change (+/- Pcs)"
)

qty_column_index = headers.index(
    "Qty Change (+/-)"
)

print(
    "Qty Change (+/- Pcs) column found."
)

print(
    "Qty Change (+/-) column found."
)


# ============================================================
# Get Data Rows
# ============================================================

data_rows = rows[
    header_row_index + 1:
]

assert len(data_rows) > 0, (
    "No data rows found below the headers."
)


# ============================================================
# Counters
# ============================================================

pcs_valid_count = 0
qty_valid_count = 0

pcs_negative_count = 0
pcs_positive_count = 0
pcs_zero_count = 0

qty_negative_count = 0
qty_positive_count = 0
qty_zero_count = 0


# ============================================================
# Verify Qty Change (+/- Pcs)
# ============================================================

for row_number, row in enumerate(
    data_rows,
    start=header_row_index + 2
):

    if len(row) <= pcs_column_index:
        continue

    value = row[
        pcs_column_index
    ].strip()

    # Skip blank cells
    if not value:
        continue

    # --------------------------------------------------------
    # Convert to numeric
    # --------------------------------------------------------

    try:

        numeric_value = float(
            value.replace(",", "")
        )

    except ValueError:

        raise AssertionError(
            "Invalid Qty Change (+/- Pcs) "
            f"value at CSV row {row_number}: "
            f"\'{value}\'"
        )

    pcs_valid_count += 1

    # --------------------------------------------------------
    # Count value type
    # --------------------------------------------------------

    if numeric_value < 0:

        pcs_negative_count += 1

    elif numeric_value > 0:

        pcs_positive_count += 1

    else:

        pcs_zero_count += 1


# ============================================================
# Verify Qty Change (+/- Pcs) Contains Data
# ============================================================

assert pcs_valid_count > 0, (
    "No valid values found under "
    "Qty Change (+/- Pcs)."
)

print(
    "Qty Change (+/- Pcs) values verified successfully."
)

print(
    "Total Qty Change (+/- Pcs) values:",
    pcs_valid_count
)

print(
    "Negative Qty Change (+/- Pcs) values:",
    pcs_negative_count
)

print(
    "Positive Qty Change (+/- Pcs) values:",
    pcs_positive_count
)

print(
    "Zero Qty Change (+/- Pcs) values:",
    pcs_zero_count
)


