    # --------------------------------------------------------

    if numeric_value < 0:

        negative_qty_values.append(
            numeric_value
        )


# ============================================================
# Verify Qty Change (+/-) Contains Data
# ============================================================

assert len(qty_values) > 0, (
    "No valid values found under "
    "Qty Change (+/-)."
)

print(
    "Qty Change (+/-) contains valid numeric data."
)

print(
    "Total Qty Change (+/-) values:",
    len(qty_values)
)

print(
    "Negative Qty Change (+/-) values:",
    len(negative_qty_values)
)


# ============================================================
# Verify Negative Stock Movement Exists
# ============================================================

assert len(negative_pcs_values) > 0, (
    "No negative values found under "
    "Qty Change (+/- Pcs)."
)

assert len(negative_qty_values) > 0, (
    "No negative values found under "
    "Qty Change (+/-)."
)


# ============================================================
# Final Success Message
# ============================================================

print(
    "SUCCESS: Daily Stock Movement Report CSV "
    "contains valid numeric values in both "
    "Qty Change columns and negative stock "
    "movement values were found."
)


