(16493,19283,'custom','import os
from datetime import datetime

# --------------------------------------------------
# Export Third Party Pipe Inventory Report as Excel
# --------------------------------------------------

export_button = page.locator("button[title=\'Excel Export\']")

expect(export_button).to_be_visible()

with page.expect_download(timeout=60000) as download_info:
    export_button.click()

download = download_info.value

# --------------------------------------------------
# Download Information
# --------------------------------------------------

filename = download.suggested_filename

print("Filename:", filename)

# --------------------------------------------------
# Get Application Date from Header
# --------------------------------------------------

app_date = page.locator(
    "header.headerNewUpdate p"
).nth(1).inner_text().strip()

print("Application Date:", app_date)

# Convert MM/DD/YYYY -> MM-DD-YYYY
current_date = datetime.strptime(
    app_date,
    "%m/%d/%Y"
).strftime("%m-%d-%Y")

expected_filename = (
    f"thirdPartyPipeInventoryReport-As-Of-{current_date}.xls"
)

# --------------------------------------------------
# Verify Dynamic Filename
# --------------------------------------------------

assert filename == expected_filename, (
    f"Expected filename: {expected_filename}, "
    f"but downloaded: {filename}"
)

print("Verified filename:", filename)

# --------------------------------------------------
# Download Location
# --------------------------------------------------

download_dir = "/tmp/downloads"

os.makedirs(download_dir, exist_ok=True)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print("Saved file:", file_path)

