(16596,19406,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for UI/PDF comparison.

    Handles:
    - whitespace
    - accents
    - non-breaking spaces
    - punctuation spacing
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


# ============================================================
# 1. CAPTURE VALUES FROM GENERATE PICKLIST SCREEN
# ============================================================
#
# IMPORTANT:
#
# Shipping Carrier and Carrier BOL are captured HERE,
# while the user-entered values are still on the
# Generate Picklist screen.
#
# We do NOT click Generate Picklist here.
#
# The existing test flow is responsible for continuing
# with Generate BOL.
# ============================================================

print(
    "\\n============================================================"
)

print(
    "CAPTURING VALUES FROM GENERATE PICKLIST SCREEN"
)

print(
    "============================================================"
)


# ------------------------------------------------------------
# Shipping Carrier
# ------------------------------------------------------------

shipping_carrier_input = page.locator(
    "#autocomplete-shippingCarrier"
)


expect(
    shipping_carrier_input
).to_be_visible(
    timeout=10000
)


ui_shipping_carrier = (
    shipping_carrier_input.input_value(
        timeout=10000
    )
)


ui_shipping_carrier = " ".join(
    ui_shipping_carrier.split()
).strip()


assert ui_shipping_carrier, (
    "\\nShipping Carrier value is empty "
    "on Generate Picklist screen."
)


print(
    "Shipping Carrier captured from Generate Picklist:",
    ui_shipping_carrier
)


# ------------------------------------------------------------
# Carrier BOL
# ------------------------------------------------------------

carrier_bol_input = page.locator(
    "input[name=\'carrierBol\']"
)


expect(
    carrier_bol_input
).to_be_visible(
    timeout=10000
)


ui_carrier_bol = (
    carrier_bol_input.input_value(
        timeout=10000
    )
)


ui_carrier_bol = " ".join(
    ui_carrier_bol.split()
).strip()


assert ui_carrier_bol, (
    "\\nCarrier BOL value is empty "
    "on Generate Picklist screen."
)


print(
    "Carrier BOL captured from Generate Picklist:",
    ui_carrier_bol
)


# ============================================================
# 2. EXTRACT SHIPPING CARRIER NAME
# ============================================================
#
# Example:
#
# JYS100 - PRC TRUCKING LTD
#
# becomes:
#
# PRC TRUCKING LTD
#
# The carrier code is not required for the PDF validation.
# ============================================================

