from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize UI/PDF text for comparison.

    Handles:
    - accents
    - unicode
    - non-breaking spaces
    - whitespace
    - different dash characters
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Unicode normalization
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove accents
    value = "".join(
        char
        for char in value
        if not unicodedata.combining(char)
    )

    # Normalize dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


def clean_input_value(value):
    """
    Clean a value read from an input.
    """

    if value is None:
        return ""

    return " ".join(
        str(value).split()
    ).strip()


