(16613,19364,'custom','# --------------------------------------------------
# Get Grid
# --------------------------------------------------

grid = page.locator("div[role=\'grid\']")


# --------------------------------------------------
# Verify More Than One Data Row Is Displayed
# --------------------------------------------------

rows = grid.locator("div[role=\'row\'][aria-rowindex]")

data_row_count = 0

for i in range(rows.count()):
    row = rows.nth(i)

    # Get Product Code cell
    product_code = row.locator(
        "div[role=\'gridcell\'][data-field=\'itemCode\']"
    )

    if product_code.count() > 0:
        product_value = product_code.inner_text().strip()

        # Exclude blank rows and Grand Total row
        if product_value and product_value != "Grand Total":
            data_row_count += 1


assert data_row_count > 1, (
    f"Expected more than 1 data row to be displayed, "
    f"but found {data_row_count}"
)

print(
    f"Verified: More than one data row is displayed. "
    f"Data rows found: {data_row_count}"
)


# --------------------------------------------------
# Verify Total Cost ($) Column Is Displayed
# --------------------------------------------------

total_cost_header = grid.locator(
    "div[role=\'columnheader\'][aria-label=\'Total Cost ($)\']"
)

assert total_cost_header.count() > 0, (
    "Total Cost ($) column is not displayed."
)

print("Verified: Total Cost ($) column is displayed.")


# --------------------------------------------------
# Verify Total Cost ($) Column Contains Data
# --------------------------------------------------

total_cost_cells = grid.locator(
    "div[role=\'gridcell\'][data-field=\'value\']"
)

total_cost_data_count = 0

for i in range(total_cost_cells.count()):
    cell = total_cost_cells.nth(i)

    value = cell.inner_text().strip()

    if value:
        total_cost_data_count += 1


assert total_cost_data_count > 0, (
    "Total Cost ($) column is displayed, "
    "but no data is present in the column."
)

print(
    f"Verified: Total Cost ($) column contains data. "
    f"Data cells found: {total_cost_data_count}"
)','# --------------------------------------------------
