(16681,19517,'custom','import re
from playwright.sync_api import expect


def assert_cutting_bom_overlay(page):

    # --------------------------------------------------
    # Locate Cutting Detail BOM dialog
    # --------------------------------------------------
    dialog = page.locator("div[role=\'dialog\']").filter(
        has=page.get_by_role(
            "heading",
            name=re.compile(r"Cutting Detail Bom#\\s*\\d+")
        )
    )

    expect(dialog).to_be_visible(timeout=15000)

    # --------------------------------------------------
    # Verify BOM title
    # --------------------------------------------------
    title = dialog.get_by_role(
        "heading",
        name=re.compile(r"Cutting Detail Bom#")
    ).first

    expect(title).to_be_visible(timeout=5000)

    title_text = title.inner_text().strip()

    assert re.search(
        r"Cutting Detail Bom#\\s*\\d+",
        title_text
    ), f"Title should contain BOM number, got: {title_text!r}"

    # --------------------------------------------------
    # Locate BOM grid
    # --------------------------------------------------
    grid = dialog.get_by_role("grid").first

    expect(grid).to_be_visible(timeout=15000)

    # --------------------------------------------------
    # Locate only data rows
    # Excludes header row
    # --------------------------------------------------
    rows = grid.locator(
        \'div[role="rowgroup"] div[role="row"]\'
    )

    expect(rows).to_have_count(3, timeout=15000)

    # --------------------------------------------------
    # First two rows: Strip Width = 23.50
    #
    # Column order:
    # 0 = Row number
    # 1 = Product ID
    # 2 = Strip Width
    # 3 = Serial Number
    # 4 = Scrap
    # 5 = Qty
    # 6 = Cost/PCE
    # 7 = Description
    # --------------------------------------------------
    for i in range(2):

        cells = rows.nth(i).get_by_role("gridcell")

        strip_width = (
            cells.nth(2)
            .inner_text()
            .strip()
            .replace(",", "")
        )

        val = float(strip_width)

        assert abs(val - 23.50) < 0.01, (
            f"Row {i + 1}: expected Strip Width 23.50, "
            f"got {strip_width!r}"
        )

    # --------------------------------------------------
    # Last row checks
    # --------------------------------------------------
    last = rows.nth(2)

    cells = last.get_by_role("gridcell")

    product_id = (
        cells.nth(1)
        .inner_text()
        .strip()
    )

    scrap_flag = (
        cells.nth(4)
        .inner_text()
        .strip()
    )

    description = (
        cells.nth(7)
        .inner_text()
        .strip()
    )

    # --------------------------------------------------
    # Verify Description = Scrap
    # --------------------------------------------------
    assert re.fullmatch(
        r"(?i)scrap",
        description
    ), (
        f"Last row Description should be Scrap, "
        f"got {description!r}"
    )

    # --------------------------------------------------
    # Verify Product ID = SCRAP
    # --------------------------------------------------
    assert product_id.upper() == "SCRAP", (
        f"Last row Product ID should be SCRAP, "
        f"got {product_id!r}"
    )

    # --------------------------------------------------
    # Verify Scrap = Yes
    # --------------------------------------------------
    assert scrap_flag.lower() == "yes", (
        f"Last row Scrap should be Yes, "
        f"got {scrap_flag!r}"
    )


assert_cutting_bom_overlay(page)','import re
from playwright.sync_api import expect


def assert_cutting_bom_overlay(page):

    # --------------------------------------------------
    # Locate Cutting Detail BOM dialog
    # --------------------------------------------------
    dialog = page.locator("div[role=\'dialog\']").filter(
        has=page.get_by_role(
            "heading",
            name=re.compile(r"Cutting Detail Bom#\\s*\\d+")
        )
    )

    expect(dialog).to_be_visible(timeout=15000)

    # --------------------------------------------------
    # Verify BOM title
    # --------------------------------------------------
    title = dialog.get_by_role(
        "heading",
        name=re.compile(r"Cutting Detail Bom#")
    ).first

    expect(title).to_be_visible(timeout=5000)

    title_text = title.inner_text().strip()

    assert re.search(
        r"Cutting Detail Bom#\\s*\\d+",
        title_text
    ), f"Title should contain BOM number, got: {title_text!r}"

    # --------------------------------------------------
    # Locate BOM grid
    # --------------------------------------------------
    grid = dialog.get_by_role("grid").first

    expect(grid).to_be_visible(timeout=15000)

    # --------------------------------------------------
    # Locate only data rows
    # Excludes header row
    # --------------------------------------------------
    rows = grid.locator(
        \'div[role="rowgroup"] div[role="row"]\'
    )

    expect(rows).to_have_count(3, timeout=15000)

    # --------------------------------------------------
    # First two rows: Strip Width = 23.50
    #
    # Column order:
    # 0 = Row number
    # 1 = Product ID
    # 2 = Strip Width
    # 3 = Serial Number
    # 4 = Scrap
    # 5 = Qty
    # 6 = Cost/PCE
    # 7 = Description
    # --------------------------------------------------
    for i in range(2):

        cells = rows.nth(i).get_by_role("gridcell")

        strip_width = (
            cells.nth(2)
            .inner_text()
            .strip()
            .replace(",", "")
        )

        val = float(strip_width)

        assert abs(val - 23.50) < 0.01, (
            f"Row {i + 1}: expected Strip Width 23.50, "
            f"got {strip_width!r}"
        )

    # --------------------------------------------------
    # Last row checks
    # --------------------------------------------------
    last = rows.nth(2)

    cells = last.get_by_role("gridcell")

    product_id = (
        cells.nth(1)
        .inner_text()
        .strip()
    )

    scrap_flag = (
        cells.nth(4)
        .inner_text()
        .strip()
    )

    description = (
        cells.nth(7)
        .inner_text()
        .strip()
    )

    # --------------------------------------------------
    # Verify Description = Scrap
    # --------------------------------------------------
    assert re.fullmatch(
        r"(?i)scrap",
        description
    ), (
        f"Last row Description should be Scrap, "
        f"got {description!r}"
    )

    # --------------------------------------------------
    # Verify Product ID = SCRAP
    # --------------------------------------------------
    assert product_id.upper() == "SCRAP", (
        f"Last row Product ID should be SCRAP, "
        f"got {product_id!r}"
    )

    # --------------------------------------------------
    # Verify Scrap = Yes
    # --------------------------------------------------
    assert scrap_flag.lower() == "yes", (
        f"Last row Scrap should be Yes, "
        f"got {scrap_flag!r}"
    )


