(16947,19756,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os


# ============================================================
# 1. Verify Confirmation Dialog
# ============================================================

dialog = page.locator(
    "div[role=\'dialog\']"
).filter(
    has_text="Do you want to save Inventory Adustment?"
)

expect(dialog).to_be_visible(timeout=10000)

ok_button = dialog.get_by_role(
    "button",
    name="Ok"
)

expect(ok_button).to_be_visible(timeout=5000)

print("Confirmation dialog found.")
print("OK button found.")


# ============================================================
# 2. Prepare PDF Body Capture
# ============================================================

pdf_data = {
    "bytes": None,
    "url": None,
    "content_type": None
}


def capture_pdf_response(response):

    try:

        # Capture ONLY the original PDF API response
        if (
            "/api/scadmin/control/imsInventoryAdjustmentPdf.pdf"
            in response.url
        ):

            content_type = response.headers.get(
                "content-type",
                ""
            ).lower()

            print(
                "PDF API response detected:",
                response.url
            )

            print(
                "PDF Content-Type:",
                content_type
            )

            # Capture body immediately
            body = response.body()

            pdf_data["bytes"] = body
            pdf_data["url"] = response.url
            pdf_data["content_type"] = content_type

            print(
                "PDF response body captured successfully."
            )

            print(
                "Captured PDF size:",
                len(body),
                "bytes"
            )

    except Exception as e:

        print(
            "Unable to capture PDF response body:",
            e
        )


# Register response listener BEFORE clicking OK
context.on(
    "response",
    capture_pdf_response
)


# ============================================================
# 3. Count Tabs Before OK Click
# ============================================================

tabs_before = len(context.pages)

print(
    "Tabs before OK click:",
    tabs_before
)


# ============================================================
# 4. Click OK and Wait for New PDF Tab
# ============================================================

with context.expect_page(timeout=15000) as new_page_info:

    ok_button.click()

pdf_page = new_page_info.value

print(
    "New PDF tab opened successfully."
)


# ============================================================
# 5. Verify New Tab
# ============================================================

tabs_after = len(context.pages)

print(
    "Tabs after OK click:",
    tabs_after
)

assert tabs_after > tabs_before, (
    f"Expected a new PDF tab. "
    f"Before={tabs_before}, "
    f"After={tabs_after}"
)


# ============================================================
# 6. Wait for PDF API Response Capture
# ============================================================

pdf_page.wait_for_timeout(3000)

print(
    "PDF tab URL:",
    repr(pdf_page.url)
)


# ============================================================
# 7. Verify PDF API Body Was Captured
# ============================================================

assert pdf_data["bytes"] is not None, (
    "PDF API response body was not captured."
)

pdf_bytes = pdf_data["bytes"]

print(
    "PDF API URL:",
    pdf_data["url"]
)

print(
    "PDF Content-Type:",
    pdf_data["content_type"]
)

print(
    "PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 8. Validate PDF Content Type
# ============================================================

assert "application/pdf" in (
    pdf_data["content_type"]
), (
    "API response is not a PDF. "
    f"Content-Type: {pdf_data[\'content_type\']}"
)


# ============================================================
# 9. Validate PDF Header
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Captured response is not a valid PDF."
)

print(
    "Valid PDF detected."
)


# ============================================================
# 10. Save PDF Locally
# ============================================================

pdf_path = (
    "/tmp/inventory_adjustment.pdf"
)

with open(
    pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )

print(
    "PDF saved at:",
    pdf_path
)


# ============================================================
# 11. Verify PDF File
# ============================================================

assert os.path.exists(
    pdf_path
), (
    f"PDF file was not saved: {pdf_path}"
)

assert os.path.getsize(
    pdf_path
) > 0, (
    "PDF file is empty."
)


# ============================================================
# 12. Read PDF Using pypdf
# ============================================================

reader = PdfReader(
    BytesIO(pdf_bytes)
)

print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 13. Extract PDF Text
# ============================================================

pdf_text = ""

for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    try:

        page_text = (
            pdf_document_page.extract_text()
            or ""
        )

        pdf_text += (
            f"\\n--- PDF Page {page_number} ---\\n"
            + page_text
        )

    except Exception as e:

        print(
            f"Unable to extract text from "
            f"PDF page {page_number}: {e}"
        )


# ============================================================
# 14. Print PDF Content
# ============================================================

print(
    "\\n================ PDF TEXT ================\\n"
)

print(pdf_text)

print(
    "\\n===========================================\\n"
)


# ============================================================
# 15. Expected PDF Text
# ============================================================

expected_text = "Inventory Adjustment PDF"

print(
    "Expected PDF text:",
    expected_text
)


# ============================================================
# 16. Validate Expected Text
# ============================================================

assert expected_text.lower() in pdf_text.lower(), (

    "\\nPDF VALIDATION FAILED\\n"
    f"Expected text was not found:\\n"
    f"{expected_text}\\n"
)

print(
    "PDF VALIDATION PASSED: "
    f"\'{expected_text}\' found in PDF."
)


# ============================================================
# 17. Verify Additional PDF Content
# ============================================================

expected_pdf_values = [
    "Inventory Adjustment PDF",
    "Type PIPE",
    "Net Weight Change (Tons)",
    "Net Value Change ($)",
    "ADJUSTMENT REF#",
    "Adjustment Date",
    "Adjusted By",
    "Yard Location",
    "Product ID",
    "Product Description"
]

for expected_value in expected_pdf_values:

    assert expected_value.lower() in pdf_text.lower(), (
        f"Expected PDF content was not found: "
        f"{expected_value}"
    )

    print(
        f"Verified PDF content: {expected_value}"
    )


# ============================================================
# 18. Delete PDF After Validation
# ============================================================

assert os.path.exists(
    pdf_path
), (
    f"PDF file does not exist: {pdf_path}"
)

os.remove(
    pdf_path
)

assert not os.path.exists(
    pdf_path
), (
    f"PDF file was not deleted: {pdf_path}"
)

print(
    "PDF deleted successfully."
)


# ============================================================
# 19. IMPORTANT
