# No. of Coils
expect(
    coil_row.locator(".//div[@data-field=\'numberOfCoils\']")
).to_have_text("2")

# Total Weight (Tons)
expect(
    coil_row.locator(".//div[@data-field=\'totalWeight\']")
).to_have_text("34.4")

# Width
expect(
    coil_row.locator(".//div[@data-field=\'width\']")
).to_have_text("48")

# Thickness
expect(
    coil_row.locator(".//div[@data-field=\'thickness\']")
).to_have_text("0.375")

# Production Test
expect(
    coil_row.locator(".//div[@data-field=\'productionTest\']")
).to_have_text("Y")


# =========================
# Validate Attachment Items
# =========================

attachment_grid = page.locator(
    "//p[normalize-space()=\'Attachment Items\']/following::div[@role=\'grid\'][1]"
)

expect(attachment_grid).to_be_visible()

attachment_row = attachment_grid.locator(
    "//div[@role=\'row\' and @data-rowindex=\'0\']"
)

# QTY
expect(
    attachment_row.locator(".//div[@data-field=\'quantity\']")
).to_have_text("1")

# Plates
expect(
    attachment_row.locator(".//div[@data-field=\'plates\']")
).to_have_text("2")

# Connectors
expect(
    attachment_row.locator(".//div[@data-field=\'connectors\']")
).to_have_text("2")

# Cones
