text = transit_text.inner_text()

match = re.search(r"Shipment\\s*#\\s*\\((\\d+)\\)", text)

if not match:
    raise AssertionError("Shipment number not found")

shipment_number = match.group(1)

print("Shipment Number:", shipment_number)

