(17352,20158,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os


# ============================================================
# 1. Locate Print Button
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(print_button).to_be_visible(timeout=10000)

print("Print button found.")


# ============================================================
# 2. Prepare PDF Response Capture
# ============================================================

pdf_data = {
    "bytes": None,
    "url": None
}


def handle_response(response):

    try:

        content_type = response.headers.get(
            "content-type",
            ""
        ).lower()

        if "application/pdf" in content_type:

            body = response.body()

            if body.startswith(b"%PDF"):

                pdf_data["bytes"] = body
                pdf_data["url"] = response.url

                print(
                    "PDF response captured:",
                    response.url
                )

    except Exception:
        pass


# Register PDF response listener
context.on(
    "response",
    handle_response
)


# ============================================================
# 3. Click Print and Wait for New Tab
# ============================================================

with context.expect_page(timeout=15000) as new_page_info:

    print_button.click()

pdf_page = new_page_info.value

print("Print button clicked.")
print("PDF opened in new tab.")


# ============================================================
# 4. Wait for PDF Response
# ============================================================

page.wait_for_timeout(5000)


# ============================================================
# 5. Verify PDF Response
# ============================================================

assert pdf_data["bytes"] is not None, (
    "PDF response was not captured."
)

print(
    "PDF API response captured successfully."
)

print(
    "PDF API URL:",
    pdf_data["url"]
)


# ============================================================
# 6. Read PDF Directly From Memory
# ============================================================

reader = PdfReader(
    BytesIO(pdf_data["bytes"])
)


# ============================================================
# 7. Extract PDF Text
# ============================================================

pdf_text = ""

for pdf_page_content in reader.pages:

    pdf_text += (
        pdf_page_content.extract_text()
        or ""
    )


# ============================================================
# 8. Verify PDF Content
# ============================================================

assert pdf_text.strip(), (
    "PDF content is empty."
)


# ============================================================
# 9. Display PDF Content Only
# ============================================================

print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)


# ============================================================
# 10. Temporarily Save PDF
# ============================================================

pdf_path = "/tmp/print_pdf.pdf"

with open(
    pdf_path,
    "wb"
) as file:

    file.write(
        pdf_data["bytes"]
    )


# ============================================================
# 11. Delete Temporary PDF
# ============================================================

if os.path.exists(pdf_path):

    os.remove(
        pdf_path
    )


assert not os.path.exists(pdf_path), (
    "Temporary PDF was not deleted."
)

print(
    "Temporary PDF deleted successfully."
)

print(
    "PDF content extracted successfully."
)


# ============================================================
# IMPORTANT
# ============================================================
# Do NOT do:
#
#     page = pdf_page
#
# Keep original application page active.
# ============================================================','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os


# Print button
print_button = page.locator(
