(17573,20379,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os


# ============================================================
# 1. Click PRINT_CREDIT_NOTE Print Button
# ============================================================

print_button = page.locator(
    "//button[@permission=\'PRINT_CREDIT_NOTE\' "
    "and normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(timeout=10000)

print(
    "Credit Note Print button found."
)


# ============================================================
# 2. Get Credit ID From UI
# ============================================================

credit_id_input = page.locator(
    "//input[@name=\'creditId\']"
)

expect(
    credit_id_input
).to_be_visible(timeout=10000)

credit_id = credit_id_input.input_value().strip()

assert credit_id, (
    "Credit ID value is empty in UI."
)

print(
    "Credit ID from UI:",
    credit_id
)


# ============================================================
# 3. Prepare PDF Response Capture
# ============================================================

pdf_data = {
    "bytes": None,
    "url": None
}


def handle_response(response):

    # PDF already captured, ignore additional responses
    if pdf_data["bytes"] is not None:
        return

    try:

        content_type = response.headers.get(
            "content-type",
            ""
        ).lower()

        if "application/pdf" not in content_type:
            return

        # Capture only the Credit Note PDF
        if "/api/scadmin/control/imsCredit.pdf" not in response.url:
            return

        body = response.body()

        if body and body.startswith(b"%PDF"):

            pdf_data["bytes"] = body
            pdf_data["url"] = response.url

            print(
                "PDF response captured:",
                response.url
            )

            print(
                "PDF size:",
                len(body),
                "bytes"
            )

    except Exception as e:

        print(
            "Unable to capture PDF response:",
            e
        )


# Register listener BEFORE clicking Print
context.on(
    "response",
    handle_response
)


# ============================================================
# 4. Click Print and Verify New PDF Tab
# ============================================================

with context.expect_page(
    timeout=15000
) as new_page_info:

    print_button.click()

pdf_page = new_page_info.value

print(
    "Print button clicked."
)

print(
    "PDF opened in new tab."
)


# ============================================================
# 5. Wait for PDF Response
# ============================================================

pdf_page.wait_for_timeout(
    5000
)


# ============================================================
# 6. Verify PDF Response
# ============================================================

assert pdf_data["bytes"] is not None, (
    "PDF response was not captured."
)

pdf_bytes = pdf_data["bytes"]

print(
    "PDF response captured successfully."
)

print(
    "PDF URL:",
    pdf_data["url"]
)

print(
    "PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 7. Extract PDF Text
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Captured response is not a valid PDF."
)

reader = PdfReader(
    BytesIO(pdf_bytes)
)

pdf_text = ""

for pdf_document_page in reader.pages:

    pdf_text += (
        pdf_document_page.extract_text()
        or ""
    )


# ============================================================
# 8. Verify PDF Content
# ============================================================

assert pdf_text.strip(), (
    "PDF content is empty."
)


# ============================================================
# 9. Verify Credit ID In PDF
# ============================================================

assert credit_id in pdf_text, (
    f"Credit ID \'{credit_id}\' from UI "
    "was not found in the PDF."
)

print(
    f"Credit ID verification PASSED: "
    f"\'{credit_id}\' found in PDF."
)


# ============================================================
# 10. Temporarily Save PDF
# ============================================================

pdf_path = "/tmp/credit_note.pdf"

with open(
    pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )


# ============================================================
# 11. Delete Temporary PDF
# ============================================================

if os.path.exists(
    pdf_path
):

    os.remove(
        pdf_path
    )

assert not os.path.exists(
    pdf_path
), (
    "Temporary PDF was not deleted."
)

print(
    "Temporary PDF deleted successfully."
)


# ============================================================
# 12. Final Result
# ============================================================

print(
    "Credit Note PDF validation completed successfully."
)


# ============================================================
# IMPORTANT
# ============================================================
# Do NOT do:
#
#     page = pdf_page
#
# Keep the original application page active.
