    "PDF request was not captured."
)


# ============================================================
# 9. Get Actual PDF URL
# ============================================================

pdf_request = (
    pdf_request_data["request"]
)

pdf_url = (
    pdf_request.url
)


print(
    "\\n================ PDF REQUEST ================\\n"
)

print(
    "Actual PDF URL:",
    pdf_url
)

print(
    "Request Method:",
    pdf_request.method
)

print(
    "Resource Type:",
    pdf_request.resource_type
)

print(
    "\\n==============================================\\n"
)


# ============================================================
# 10. Verify PDF URL
# ============================================================

assert pdf_url, (
    "PDF URL was not captured."
)

assert (
    "/scadmin/genPdfs/" in pdf_url
), (
    f"Unexpected PDF URL: {pdf_url}"
)

assert (
