        # Store PDF bytes.
        # --------------------------------------------------------

        pdf_response_data[
            "bytes"
        ] = body

        pdf_response_data[
            "url"
        ] = response_url


        print(
            "\\nPDF HTTP RESPONSE DETECTED"
