from pypdf import PdfReader
from io import BytesIO
from datetime import datetime
import os
import re


# ================================================================
# HELPERS
# ================================================================

def normalize_text(value):
    if value is None:
        return ""

    return re.sub(
        r"\\s+",
        " ",
        str(value)
    ).strip().lower()


def normalize_number(value):
    if value is None:
        return None

    text = str(value).strip().replace(",", "")

    try:
        return float(text)
    except (ValueError, TypeError):
        return None


def normalize_supplier_text(value):
    text = normalize_text(value)

    replacements = {
        "qc": "quebec",
        "can": "canada",
        "usa": "united states",
        "u.s.a.": "united states",
        "u.s.": "united states",
    }

    for old, new in replacements.items():
        text = re.sub(
            rf"\\b{re.escape(old)}\\b",
            new,
            text
        )

    return text


def verify_equal(label, ui_value, pdf_value):
    ui_norm = normalize_text(ui_value)
    pdf_norm = normalize_text(pdf_value)

    print(f"{label}:")
    print(f"  UI  : {ui_value}")
    print(f"  PDF : {pdf_value}")

    assert ui_norm == pdf_norm, (
        f"{label} mismatch. "
        f"UI=\'{ui_value}\' PDF=\'{pdf_value}\'"
    )

    print(f"PASS: {label}")


def verify_number_equal(
    label,
    ui_value,
    pdf_value,
    tolerance=0.0001
):
    ui_num = normalize_number(ui_value)
    pdf_num = normalize_number(pdf_value)

    print(f"{label}:")
    print(f"  UI  : {ui_value}")
    print(f"  PDF : {pdf_value}")

    assert ui_num is not None, (
        f"Invalid UI number for {label}: {ui_value}"
    )

    assert pdf_num is not None, (
        f"Invalid PDF number for {label}: {pdf_value}"
    )

    assert abs(ui_num - pdf_num) <= tolerance, (
        f"{label} mismatch. "
        f"UI=\'{ui_value}\' PDF=\'{pdf_value}\'"
    )

    print(f"PASS: {label}")


def get_cell_value(locator):
    value = locator.inner_text().strip()

    if not value:
        value = (
            locator.get_attribute("title")
            or ""
        )

    return value.strip()


def parse_ui_date(value):
    if not value:
        return None

    value = value.strip()

    formats = [
        "%m/%d/%Y",
        "%m-%d-%Y",
        "%Y-%m-%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d-%b-%Y",
        "%d-%B-%Y",
        "%m/%d/%y",
        "%m-%d-%y",
        "%d/%m/%y",
        "%d-%m-%y",
    ]

    for fmt in formats:
        try:
            return datetime.strptime(
                value,
                fmt
            ).date()
        except ValueError:
            pass

    return None


def extract_date_from_text(text):
    if not text:
        return None

    patterns = [
        r"\\b\\d{1,2}/\\d{1,2}/\\d{4}\\b",
        r"\\b\\d{4}-\\d{1,2}-\\d{1,2}\\b",
        r"\\b\\d{1,2}-(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)-\\d{4}\\b",
        r"\\b\\d{1,2}-[A-Za-z]+-\\d{4}\\b",
        r"\\b\\d{1,2}/\\d{1,2}/\\d{2}\\b",
        r"\\b\\d{1,2}-\\d{1,2}-\\d{2}\\b",
    ]

    for pattern in patterns:
        match = re.search(
            pattern,
            text,
            flags=re.IGNORECASE
        )

        if match:
            return match.group(0)

    return None


