from pypdf import PdfReader
from io import BytesIO
from datetime import datetime
import os
import re


# ============================================================
# 1. Helper Functions
# ============================================================

def normalize_text(value):
    if value is None:
        return ""

    return re.sub(
        r"\\s+",
        " ",
        str(value)
    ).strip().lower()


def normalize_number(value):
    if value is None:
        return ""

    value = str(value).strip()

    value = re.sub(
        r"[,$]",
        "",
        value
    )

    value = re.sub(
        r"\\s*(ft|lbs|pcs|pce|ea|mt|ton|lb)\\s*$",
        "",
        value,
        flags=re.IGNORECASE
    )

    try:
        number = float(value)

        if number.is_integer():
            return str(int(number))

        return str(number)

    except Exception:
        return normalize_text(value)


def normalize_supplier_text(value):
    value = normalize_text(value)

    value = re.sub(
        r"\\bqc\\b",
        "quebec",
        value,
        flags=re.IGNORECASE
    )

    value = re.sub(
        r"\\bcan\\b",
        "canada",
        value,
        flags=re.IGNORECASE
    )

    value = re.sub(
        r"\\busa\\b",
        "united states",
        value,
        flags=re.IGNORECASE
    )

    return normalize_text(value)


def verify_equal(
    expected_value,
    actual_value,
    field_name
):
    expected_normalized = normalize_text(
        expected_value
    )

    actual_normalized = normalize_text(
        actual_value
    )

    assert expected_normalized == actual_normalized, (
        f"\\n\\nVALIDATION FAILED: {field_name}\\n"
        f"Expected : \'{expected_value}\'\\n"
        f"Actual   : \'{actual_value}\'\\n"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"Expected=\'{expected_value}\' | "
        f"Actual=\'{actual_value}\'"
    )


def verify_number_equal(
    expected_value,
    actual_value,
    field_name
):
    expected_normalized = normalize_number(
        expected_value
    )

    actual_normalized = normalize_number(
        actual_value
    )

    assert expected_normalized == actual_normalized, (
        f"\\n\\nNUMERIC VALIDATION FAILED: {field_name}\\n"
        f"Expected : \'{expected_value}\'\\n"
        f"Actual   : \'{actual_value}\'\\n"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"Expected=\'{expected_value}\' | "
        f"Actual=\'{actual_value}\'"
    )


def get_cell_value(locator):

    value = locator.get_attribute(
        "title"
    )

    if not value:
        value = (
            locator
            .inner_text()
            .strip()
        )

    return value.strip()


def convert_ui_date_to_pdf_format(
    order_date_ui
):

    ui_date_formats = [
        "%m/%d/%Y",
        "%m/%d/%y",
        "%Y-%m-%d",
        "%d/%m/%Y",
        "%d-%m-%Y",
        "%d-%b-%Y",
        "%d-%B-%Y"
    ]

    for date_format in ui_date_formats:

        try:

            ui_order_date_obj = datetime.strptime(
                order_date_ui,
                date_format
            )

            return ui_order_date_obj.strftime(
                "%d-%b-%Y"
            )

        except ValueError:
