print(
    "Captured PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 18. Verify New PDF Tab
# ============================================================

tabs_after = len(
    context.pages
)

print(
    "Tabs after Print PO:",
    tabs_after
)

assert tabs_after > tabs_before, (
    f"\\nExpected new PDF tab.\\n"
    f"Before={tabs_before}\\n"
    f"After={tabs_after}"
)


# ============================================================
# 19. Verify PDF Content-Type
# ============================================================

assert (
    "application/pdf"
    in pdf_data["content_type"]
), (
    "Response is not a PDF.\\n"
    f"Content-Type: "
    f"{pdf_data[\'content_type\']}"
)

print(
    "Valid PDF detected."
)


# ============================================================
# 20. PDF Tab URL
# ============================================================

pdf_page.wait_for_timeout(
    2000
)

print(
    "PDF tab URL:",
    repr(pdf_page.url)
)


# ============================================================
# 21. Save Temporary PDF
# ============================================================

pdf_path = (
    "/tmp/print_po.pdf"
)

with open(
    pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )


assert os.path.exists(
    pdf_path
), (
    f"PDF file was not saved: {pdf_path}"
)

assert os.path.getsize(
    pdf_path
) > 0, (
    "PDF file is empty."
)

print(
    "PDF saved temporarily at:",
    pdf_path
)


# ============================================================
# 22. Read PDF
# ============================================================

reader = PdfReader(
    BytesIO(
        pdf_bytes
    )
)

print(
    "PDF page count:",
    len(
        reader.pages
    )
)


# ============================================================
# 23. Extract PDF Text
# ============================================================

pdf_text = ""


for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    try:

        page_text = (
            pdf_document_page
            .extract_text()
            or ""
        )

        pdf_text += (
            f"\\n--- PDF Page {page_number} ---\\n"
            + page_text
        )

    except Exception as e:

        print(
            f"Unable to extract PDF page "
            f"{page_number}: {e}"
        )


# ============================================================
# 24. Verify PDF Text
# ============================================================

assert pdf_text.strip(), (
    "PDF text extraction returned empty text."
)

print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)

pdf_normalized = normalize_text(
    pdf_text
)


# ============================================================
# 25. Verify PO # vs CUSTOMER PO #
# ============================================================

customer_po_match = re.search(
    r"CUSTOMER\\s+PO\\s*#?\\s*"
    r"([A-Za-z0-9_-]+)",
    pdf_text,
    flags=re.IGNORECASE
)

assert customer_po_match is not None, (
    "CUSTOMER PO not found in PDF."
)

customer_po_pdf = (
    customer_po_match
    .group(1)
    .strip()
)

print(
    "PDF CUSTOMER PO:",
    customer_po_pdf
)

verify_equal(
    po_ui,
    customer_po_pdf,
    "UI PO # vs PDF CUSTOMER PO"
)


# ============================================================
# 26. Verify PDF Order Date vs UI Order Date
# ============================================================

order_date_match = re.search(
    r"Order\\s+Date\\s+"
    r"(\\d{1,2}-"
    r"(?:Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)"
    r"-\\d{4})",
    pdf_text,
    flags=re.IGNORECASE
)

assert order_date_match is not None, (
    "Order Date not found in PDF."
)

pdf_order_date = (
    order_date_match
    .group(1)
    .strip()
)

print(
    "PDF Order Date:",
    pdf_order_date
)


expected_pdf_order_date = (
    convert_ui_date_to_pdf_format(
        order_date_ui
    )
)

assert expected_pdf_order_date is not None, (
    "\\nUnable to parse UI Order Date.\\n"
    f"UI Order Date: \'{order_date_ui}\'"
)

print(
    "Expected PDF Order Date from UI:",
    expected_pdf_order_date
)

verify_equal(
    expected_pdf_order_date,
    pdf_order_date,
    "UI Order Date vs PDF Order Date"
)


# ============================================================
# 27. Supplier Details Partial Match
# ============================================================

supplier_pdf_normalized = normalize_supplier_text(
    pdf_text
)

print(
    "\\n========== SUPPLIER PARTIAL MATCH ==========\\n"
)

matched_supplier_value = None


for ui_value in supplier_ui_values:

    ui_value_normalized = normalize_supplier_text(
        ui_value
    )

    if not ui_value_normalized:
        continue

    if (
        ui_value_normalized
        in supplier_pdf_normalized
    ):

        matched_supplier_value = (
            ui_value
        )

        break


assert matched_supplier_value is not None, (
    "\\nSUPPLIER VALIDATION FAILED.\\n"
    "No meaningful Supplier value from UI "
    "was found in PDF.\\n"
    f"UI Supplier Values: "
    f"{supplier_ui_values}\\n"
)

print(
    "VALIDATION PASSED: Supplier Details"
)

print(
    "Matched UI Supplier Value:",
    matched_supplier_value
)


# ============================================================
# 28. Verify Item Description
# ============================================================

item_description_normalized = normalize_text(
    item_description_ui
)

assert (
    item_description_normalized
    in pdf_normalized
), (
    f"\\nItem Description validation failed.\\n"
    f"UI Item Description:\\n"
    f"{item_description_ui}"
)

print(
    "VALIDATION PASSED: Item Description"
)


# ============================================================
# 29. Verify Qty Ordered
# ============================================================

qty_ui_normalized = normalize_number(
    qty_ordered_ui
)


pdf_qty_matches = re.findall(
    r"\\b"
    r"(\\d+(?:\\.\\d+)?)"
    r"\\s+"
    r"(PCE|PCS|EA)"
    r"\\b",
    pdf_text,
    flags=re.IGNORECASE
)

assert pdf_qty_matches, (
    "Quantity + UOM was not found in PDF."
)

qty_verified = False


for quantity, uom in pdf_qty_matches:

    if (
        normalize_number(quantity)
        == qty_ui_normalized
    ):

        print(
            "PDF Quantity:",
            quantity
        )

        print(
            "PDF UOM:",
            uom
        )

        qty_verified = True

        break


assert qty_verified, (
    f"\\nQty Ordered validation failed.\\n"
    f"UI Qty Ordered: {qty_ordered_ui}\\n"
    f"PDF Quantity/UOM values: "
    f"{pdf_qty_matches}"
)

print(
    "VALIDATION PASSED: Qty Ordered"
)


# ============================================================
# 30. Verify Material Cost
# ============================================================

material_cost_ui_normalized = normalize_number(
    material_cost_ui
)


pdf_material_cost_matches = re.findall(
    r"\\b"
    r"(\\d+(?:,\\d{3})*(?:\\.\\d+)?)"
    r"\\s*/\\s*"
    r"[A-Z]{1,5}"
    r"\\b",
    pdf_text,
    flags=re.IGNORECASE
)

assert pdf_material_cost_matches, (
    "Material Cost was not found in PDF."
)

material_cost_verified = False


for pdf_material_cost in pdf_material_cost_matches:

    if (
        normalize_number(pdf_material_cost)
        == material_cost_ui_normalized
    ):

        material_cost_verified = True

        print(
            "PDF Material Cost:",
            pdf_material_cost
        )

        break


assert material_cost_verified, (
    f"\\nMaterial Cost validation failed.\\n"
    f"UI Material Cost: {material_cost_ui}\\n"
    f"PDF Material Costs: "
    f"{pdf_material_cost_matches}"
)

print(
    "VALIDATION PASSED: Material Cost"
)


# ============================================================
# 31. Final Validation Summary
# ============================================================

print(
    "\\n"
    "============================================================"
)

print(
    "ALL PURCHASE ORDER UI VS PDF VALIDATIONS PASSED"
)

print(
    "============================================================"
)

print(
    "PO # verified."
)

print(
    "Supplier Details partial match verified."
)

print(
    "UI Order Date matched with PDF Order Date."
)

print(
    "Item Description verified."
)

print(
    "Qty Ordered verified."
)

print(
    "Material Cost verified."
)


# ============================================================
# 32. DELETE TEMPORARY PDF
# ============================================================

print(
    "\\n========== PDF CLEANUP ==========\\n"
)

if os.path.exists(
    pdf_path
):

    os.remove(
        pdf_path
    )

    print(
        "Temporary PDF deleted successfully:",
        pdf_path
    )

else:

    print(
        "Temporary PDF not found:",
        pdf_path
    )


# ============================================================
# 33. VERIFY PDF DELETED
# ============================================================

assert not os.path.exists(
    pdf_path
), (
    f"PDF file was not deleted: {pdf_path}"
)

print(
    "PDF deletion verification passed."
)


# ============================================================
# 34. FINAL RESULT
# ============================================================

print(
    "\\n"
    "============================================================"
)

print(
    "PURCHASE ORDER PDF VALIDATION COMPLETED SUCCESSFULLY"
)

print(
