from pypdf import PdfReader
from io import BytesIO
from datetime import datetime
import os
import re


# ============================================================
# 1. Helper Functions
# ============================================================

def normalize_text(value):
    if value is None:
        return ""

    return re.sub(
        r"\\s+",
        " ",
        str(value)
    ).strip().lower()


def verify_contains(
    pdf_text,
    value,
    field_name
):
    normalized_pdf = normalize_text(pdf_text)
    normalized_value = normalize_text(value)

    assert normalized_value in normalized_pdf, (
        f"\\n\\nVALIDATION FAILED: {field_name}\\n"
        f"Expected Value : \'{value}\'\\n"
        f"PDF Value/Text : \'{pdf_text}\'"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"Value=\'{value}\'"
    )


def verify_equal(
    ui_value,
    pdf_value,
    field_name
):
    ui_normalized = normalize_text(ui_value)
    pdf_normalized = normalize_text(pdf_value)

    assert ui_normalized == pdf_normalized, (
        f"\\n\\nVALIDATION FAILED: {field_name}\\n"
        f"UI Value  : \'{ui_value}\'\\n"
        f"PDF Value : \'{pdf_value}\'"
    )

    print(
        f"VALIDATION PASSED: {field_name} | "
        f"UI=\'{ui_value}\' | "
        f"PDF=\'{pdf_value}\'"
    )


# ============================================================
# 2. Locate Sales Order PDF Button
# ============================================================

order_pdf_button = page.locator(
    "//button[@title=\'Sales Order PDF\']"
)

expect(
    order_pdf_button
).to_be_visible(
    timeout=10000
)

print(
    "Sales Order PDF button found."
)


# ============================================================
# 3. PDF Response Storage
# ============================================================

pdf_data = {
    "bytes": None,
    "url": None,
    "content_type": None
}


# ============================================================
# 4. Click Sales Order PDF
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before Sales Order PDF:",
    tabs_before
)

with context.expect_page(
    timeout=15000
) as new_page_info:

    with context.expect_event(
        "response",
        predicate=lambda response: (
            "application/pdf"
            in response.headers.get(
                "content-type",
                ""
            ).lower()
        ),
        timeout=15000
    ) as pdf_response_info:

        order_pdf_button.click(
            force=True
        )


# ============================================================
# 5. Get New PDF Tab
# ============================================================

pdf_page = new_page_info.value

print(
    "Sales Order PDF button clicked."
)

print(
    "Sales Order PDF opened in new tab."
)


# ============================================================
# 6. Verify New Tab
# ============================================================

tabs_after = len(
    context.pages
)

print(
    "Tabs after Sales Order PDF:",
    tabs_after
)

assert tabs_after > tabs_before, (
    f"\\nExpected Sales Order PDF in new tab.\\n"
    f"Before={tabs_before}\\n"
    f"After={tabs_after}"
)

print(
    "Sales Order PDF opened in new tab successfully."
)


# ============================================================
# 7. Get PDF Response
# ============================================================

pdf_response = pdf_response_info.value

pdf_data["url"] = pdf_response.url

pdf_data["content_type"] = (
    pdf_response.headers.get(
        "content-type",
        ""
    ).lower()
)

print(
    "\\n================ PDF RESPONSE ================\\n"
)

print(
    "PDF URL:",
    pdf_data["url"]
)

print(
    "PDF Content-Type:",
    pdf_data["content_type"]
)

print(
    "\\n===============================================\\n"
)


# ============================================================
# 8. Capture PDF Body
# ============================================================

pdf_bytes = pdf_response.body()

assert pdf_bytes is not None, (
    "PDF response body is None."
)

assert len(pdf_bytes) > 0, (
    "PDF response body is empty."
)

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Captured response is not a valid PDF."
)

pdf_data["bytes"] = pdf_bytes

print(
    "PDF response body captured successfully."
)

print(
    "Captured PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 9. Read PDF
# ============================================================

reader = PdfReader(
    BytesIO(
        pdf_bytes
    )
)

print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 10. Extract PDF Text
# ============================================================

pdf_text = ""

for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    page_text = (
        pdf_document_page.extract_text()
        or ""
    )

    pdf_text += (
        f"\\n--- PDF Page {page_number} ---\\n"
        + page_text
    )


# ============================================================
# 11. Verify PDF Text
# ============================================================

assert pdf_text.strip(), (
    "PDF text extraction returned empty text."
)


# ============================================================
# 12. Display PDF Content
# ============================================================

print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)

print(
    "PDF content extracted successfully."
)


# ============================================================
# 13. Save PDF Temporarily
# ============================================================

pdf_path = (
    "/tmp/order_pdf.pdf"
)

with open(
    pdf_path,
    "wb"
) as pdf_file:

    pdf_file.write(
        pdf_bytes
    )

assert os.path.exists(
    pdf_path
), (
    "Temporary PDF was not saved."
)

assert os.path.getsize(
    pdf_path
) > 0, (
    "Temporary PDF is empty."
)

print(
    "Temporary PDF saved:",
    pdf_path
)


