(17701,20507,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO


# ============================================================
# 1. Locate Print Button
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(
    timeout=10000
)

print(
    "Print button found."
)


# ============================================================
# 2. PDF Response Storage
# ============================================================

pdf_data = {
    "bytes": None,
    "url": None,
    "content_type": None
}


# ============================================================
# 3. Click Print and Capture PDF Response
# ============================================================

with context.expect_page(
    timeout=15000
) as new_page_info:

    with context.expect_event(
        "response",
        predicate=lambda response: (
            "application/pdf"
            in response.headers.get(
                "content-type",
                ""
            ).lower()
        ),
        timeout=15000
    ) as pdf_response_info:

        print_button.click(
            force=True
        )


# ============================================================
# 4. Get New PDF Tab
# ============================================================

pdf_page = (
    new_page_info.value
)

print(
    "Print button clicked."
)

print(
    "PDF opened in new tab."
)


# ============================================================
# 5. Get PDF API Response
# ============================================================

pdf_response = (
    pdf_response_info.value
)


pdf_data["url"] = (
    pdf_response.url
)


pdf_data["content_type"] = (
    pdf_response.headers.get(
        "content-type",
        ""
    )
)


print(
    "\\n================ PDF RESPONSE ================\\n"
)

print(
    "PDF API URL:",
    pdf_data["url"]
)

print(
    "PDF Content-Type:",
    pdf_data["content_type"]
)

print(
    "\\n===============================================\\n"
)


# ============================================================
# 6. Capture PDF Body
# ============================================================

pdf_bytes = (
    pdf_response.body()
)


assert pdf_bytes is not None, (
    "PDF response body is None."
)


assert len(pdf_bytes) > 0, (
    "PDF response body is empty."
)


assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Captured response is not a valid PDF."
)


pdf_data["bytes"] = (
    pdf_bytes
)


print(
    "PDF response captured successfully."
)

print(
    "Captured PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 7. Read PDF
# ============================================================

reader = PdfReader(
    BytesIO(
        pdf_bytes
    )
)


print(
    "PDF page count:",
    len(
        reader.pages
    )
)


# ============================================================
# 8. Extract PDF Text
# ============================================================

pdf_text = ""


for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    page_text = (
        pdf_document_page.extract_text()
        or ""
    )

    pdf_text += (
        f"\\n--- PDF Page {page_number} ---\\n"
        + page_text
    )


# ============================================================
# 9. Verify PDF Text
# ============================================================

assert pdf_text.strip(), (
    "PDF content is empty."
)


# ============================================================
# 10. Display PDF Content
# ============================================================

print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)


print(
    "PDF content read successfully."
)


# ============================================================
# IMPORTANT
# ============================================================
#
# Do NOT do:
#
#     page = pdf_page
#
# Keep original application page active.
#
