    timeout=15000
) as new_page_info:

    print_invoice_button.click(
        force=True
    )


# ============================================================
# 7. Get PDF Page
# ============================================================

pdf_page = (
    new_page_info.value
)

print(
    "Print Invoice clicked."
)

print(
    "PDF opened in new tab."
)


# ============================================================
# 8. Wait for PDF Request
# ============================================================

pdf_page.wait_for_timeout(
    3000
)


# ============================================================
# 9. Verify PDF Request
# ============================================================

assert pdf_request_data["request"] is not None, (
    "PDF request was not captured."
)


# ============================================================
# 10. Get Actual PDF URL
# ============================================================

pdf_request = (
    pdf_request_data["request"]
)


pdf_url = (
    pdf_request.url
)


print(
    "\\n================ PDF REQUEST ================\\n"
)

print(
    "Actual PDF URL:",
    pdf_url
)

print(
    "Request Method:",
    pdf_request.method
)

print(
    "Resource Type:",
    pdf_request.resource_type
)

print(
    "\\n==============================================\\n"
)


# ============================================================
# 11. Verify PDF URL
# ============================================================

assert pdf_url, (
    "PDF URL was not captured."
)


assert (
    "/scadmin/genPdfs/" in pdf_url
), (
    f"Unexpected PDF URL: {pdf_url}"
)


assert (
    pdf_url.lower().endswith(".pdf")
), (
    f"Captured URL is not a PDF: {pdf_url}"
)


print(
    "PDF URL verified successfully."
)


# ============================================================
# 12. Verify New PDF Tab
# ============================================================

tabs_after = len(
    context.pages
)


print(
    "Tabs after Print Invoice:",
    tabs_after
)


assert tabs_after > tabs_before, (

    f"\\nExpected new PDF tab.\\n"
    f"Before={tabs_before}\\n"
    f"After={tabs_after}"
)


print(
    "Print Invoice PDF opened in new tab successfully."
)


# ============================================================
# 13. PDF Viewer
# ============================================================

pdf_page.wait_for_timeout(
    3000
)


print(
    "PDF tab URL:",
    repr(pdf_page.url)
)


# ============================================================
# 14. Extract Expected Filename
# ============================================================

expected_filename = (
    pdf_url.rsplit(
        "/",
        1
    )[1]
)


print(
    "Expected PDF filename:",
    expected_filename
)


# ============================================================
# 15. Verify Filename Format
# ============================================================

assert re.match(
    r"^Document\\d+_\\d+\\.pdf$",
    expected_filename,
    flags=re.IGNORECASE
), (
    f"Unexpected PDF filename: "
    f"{expected_filename}"
)


print(
    "PDF filename format verified."
)


# ============================================================
# 16. Fetch PDF Using Actual PDF URL
# ============================================================

print(
    "Fetching PDF using captured PDF URL..."
)


pdf_response = (
    context.request.get(
        pdf_url,
        timeout=30000
    )
)


# ============================================================
# 17. Verify PDF HTTP Response
# ============================================================

assert pdf_response.ok, (

    f"\\nPDF request failed.\\n"
    f"Status: {pdf_response.status}\\n"
    f"URL: {pdf_url}"
)


print(
    "PDF request successful."
)

print(
    "PDF HTTP status:",
    pdf_response.status
)


# ============================================================
# 18. Verify Content-Type
# ============================================================

content_type = (
    pdf_response.headers.get(
        "content-type",
        ""
    ).lower()
)


print(
    "PDF Content-Type:",
    content_type
)


assert (
    "application/pdf" in content_type
), (

    f"\\nExpected application/pdf.\\n"
    f"Actual Content-Type: {content_type}"
)


# ============================================================
# 19. Get PDF Bytes
# ============================================================

pdf_bytes = (
    pdf_response.body()
)


assert pdf_bytes is not None, (
    "PDF response body is None."
)


assert len(pdf_bytes) > 0, (
    "PDF response body is empty."
)


print(
    "PDF response body captured successfully."
)

print(
    "Captured PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 20. Verify PDF Header
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Captured response is not a valid PDF."
)


print(
    "Valid PDF detected."
)


# ============================================================
# 21. Read PDF Using pypdf
# ============================================================

reader = PdfReader(
    BytesIO(
        pdf_bytes
    )
)


print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 22. Extract PDF Content
# ============================================================

pdf_text = ""


for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    try:

        page_text = (
            pdf_document_page.extract_text()
            or ""
        )

        pdf_text += (
            page_text
            + "\\n"
        )

    except Exception as e:

        print(
            f"Unable to extract PDF page "
            f"{page_number}:",
            e
        )


# ============================================================
# 23. Verify PDF Content
# ============================================================

assert pdf_text.strip(), (
    "PDF content is empty."
)


# ============================================================
# 24. Display PDF Content
# ============================================================

print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)


print(
    "PDF content read successfully."
)


# ============================================================
# 25. Prepare Download Directory
# ============================================================

download_dir = (
    "/tmp/downloads"
)


os.makedirs(
    download_dir,
    exist_ok=True
)


print(
    "Download directory:",
    download_dir
)


# ============================================================
# 26. Prepare Download File Path
# ============================================================

file_path = os.path.join(
    download_dir,
    expected_filename
)


# ============================================================
# 27. Remove Existing File
# ============================================================

if os.path.exists(
    file_path
):

    os.remove(
        file_path
    )

    print(
        "Existing file removed:",
        file_path
    )


# ============================================================
# 28. Save PDF
# ============================================================
#
# Chrome PDF Viewer Download button is browser-internal.
#
# We already captured the exact PDF response bytes.
# Save those exact bytes using the filename from the
# actual PDF URL.
#
# ============================================================

with open(
    file_path,
    "wb"
) as downloaded_file:

    downloaded_file.write(
        pdf_bytes
    )


print(
    "PDF saved successfully:"
)

print(
    file_path
)


# ============================================================
# 29. Verify File Exists
# ============================================================

assert os.path.exists(
    file_path
), (
    f"Downloaded PDF was not saved:\\n"
    f"{file_path}"
)


print(
    "Downloaded PDF file exists."
)


# ============================================================
# 30. Verify File Size
# ============================================================

file_size = (
    os.path.getsize(
        file_path
    )
)


assert file_size > 0, (
    f"Downloaded PDF file is empty:\\n"
    f"{file_path}"
)


print(
    "Downloaded PDF file size:",
    file_size,
    "bytes"
)


# ============================================================
# 31. Verify Filename
# ============================================================

assert expected_filename.lower().endswith(
    ".pdf"
), (
    f"Expected PDF file, "
    f"but downloaded: {expected_filename}"
)


print(
    "Downloaded filename verified:"
)

print(
    expected_filename
)


# ============================================================
# 32. Read Saved PDF Bytes
# ============================================================

with open(
    file_path,
    "rb"
) as downloaded_file:

    downloaded_bytes = (
        downloaded_file.read()
    )


# ============================================================
# 33. Verify Saved PDF Header
# ============================================================

assert downloaded_bytes.startswith(
    b"%PDF"
), (
    "Saved file is not a valid PDF."
)


print(
    "Saved PDF is valid."
)


# ============================================================
# 34. Compare PDF Bytes
# ============================================================

assert (
    downloaded_bytes
    == pdf_bytes
), (
    "\\nSaved PDF bytes do not match "
    "the captured PDF response."
)


print(
    "Saved PDF bytes match captured PDF bytes."
)


# ============================================================
# 35. Read Saved PDF Using pypdf
# ============================================================

downloaded_reader = PdfReader(
    BytesIO(
        downloaded_bytes
    )
)


print(
    "Saved PDF page count:",
    len(
        downloaded_reader.pages
    )
)


# ============================================================
# 36. Extract Saved PDF Content
# ============================================================

downloaded_pdf_text = ""


for page_number, pdf_document_page in enumerate(
    downloaded_reader.pages,
    start=1
):

    try:

        page_text = (
            pdf_document_page.extract_text()
            or ""
        )

        downloaded_pdf_text += (
            page_text
            + "\\n"
        )

    except Exception as e:

        print(
            f"Unable to extract saved PDF page "
            f"{page_number}:",
            e
        )


# ============================================================
# 37. Verify Saved PDF Content
# ============================================================

assert downloaded_pdf_text.strip(), (
    "Saved PDF content is empty."
)


print(
    "\\n========== SAVED PDF CONTENT ==========\\n"
)

print(
    downloaded_pdf_text
)

print(
    "\\n========================================\\n"
)


print(
    "Saved PDF content read successfully."
)


# ============================================================
# 38. Normalize PDF Text
# ============================================================

original_pdf_normalized = (
    " ".join(
        pdf_text.split()
    )
)


saved_pdf_normalized = (
    " ".join(
        downloaded_pdf_text.split()
    )
)


# ============================================================
# 39. Compare Original PDF and Saved PDF Content
# ============================================================

assert (
    original_pdf_normalized
    == saved_pdf_normalized
), (
    "\\nOriginal PDF and saved PDF "
    "content do not match."
)


print(
    "Original PDF and saved PDF "
    "content match successfully."
)


# ============================================================
# 40. Delete Downloaded PDF
# ============================================================

assert os.path.exists(
    file_path
), (
    f"PDF file does not exist before deletion:\\n"
    f"{file_path}"
)


os.remove(
    file_path
)


print(
    "PDF file deleted:"
)

print(
    file_path
)


# ============================================================
# 41. Verify PDF File Deleted
# ============================================================

assert not os.path.exists(
    file_path
), (
    f"PDF file was not deleted:\\n"
    f"{file_path}"
)


print(
    "PDF file deletion verified successfully."
)


# ============================================================
# 42. Final Validation
# ============================================================

print(
    "\\n"
    "============================================================"
)

print(
    "PRINT INVOICE PDF VALIDATION PASSED"
)

print(
    "============================================================"
)

print(
    "PDF opened in new tab."
)

print(
    "Actual PDF URL:"
)

print(
    pdf_url
)

print(
    "PDF content read successfully."
)

print(
    "PDF page count:",
    len(reader.pages)
)

print(
    "PDF filename verified:"
)

print(
    expected_filename
)

print(
    "Saved PDF bytes match original PDF response."
)

print(
    "Saved PDF content verified."
)

print(
    "Original PDF and saved PDF content match."
)

print(
    "PDF file deleted successfully."
)

print(
    "============================================================"
)


# ============================================================
# IMPORTANT
# ============================================================
#
# DO NOT DO:
#
#     page = pdf_page
#
# Keep the original application page as "page".
#
# ============================================================

print(
    "Original application page kept active."
