from pypdf import PdfReader
from io import BytesIO


# ============================================================
# 1. Get Order # From UI
# ============================================================

order_input = page.locator(
    "//input[@name=\'orderId\']"
)

expect(
    order_input
).to_be_visible(
    timeout=10000
)

ui_order_number = (
    order_input
    .input_value()
    .strip()
)

assert ui_order_number, (
    "Order # value is empty in UI."
)

print(
    "UI Order #:",
    ui_order_number
)


# ============================================================
# 2. Locate Print Button
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(
    timeout=10000
)

print(
    "Print button found."
)


# ============================================================
# 3. Count Tabs Before Print
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before Print:",
    tabs_before
)


# ============================================================
# 4. PDF Request Predicate
# ============================================================

def is_pdf_request(request):

    try:

        request_url = (
            request.url.lower()
        )

        return (
            ".pdf" in request_url
            or "/genpdfs/" in request_url
        )

    except Exception:

        return False


# ============================================================
# 5. Capture PDF Request + New Tab
# ============================================================

with context.expect_page(
    timeout=15000
) as new_page_info:

    with context.expect_event(
        "request",
        predicate=is_pdf_request,
        timeout=15000
    ) as pdf_request_info:

        print_button.click(
            force=True
        )


# ============================================================
# 6. Get PDF Tab
# ============================================================

pdf_page = (
    new_page_info.value
)


# ============================================================
# 7. Get PDF Request
# ============================================================

pdf_request = (
    pdf_request_info.value
)

pdf_url = (
    pdf_request.url
)


print(
    "Print button clicked."
)

print(
    "PDF opened in new tab."
)

print(
    "PDF request URL:",
    pdf_url
)


# ============================================================
# 8. Verify PDF Request URL
# ============================================================

assert pdf_url, (
    "PDF request URL was not captured."
)

assert (
    ".pdf" in pdf_url.lower()
    or "/genpdfs/" in pdf_url.lower()
), (
    f"Captured request is not a PDF: {pdf_url}"
)

print(
    "PDF request URL verified."
)


# ============================================================
# 9. Verify New Tab
# ============================================================

tabs_after = len(
    context.pages
)

print(
    "Tabs after Print:",
    tabs_after
)

assert tabs_after > tabs_before, (

    f"Expected new PDF tab. "
    f"Before={tabs_before}, "
    f"After={tabs_after}"
)

print(
    "New PDF tab verified successfully."
)


# ============================================================
# 10. PDF Viewer URL
# ============================================================
#
# Chrome PDF Viewer may return blank URL to Playwright.
# Therefore use the captured request URL.
#
# ============================================================

pdf_page.wait_for_timeout(
    2000
)

print(
    "PDF viewer URL:",
    repr(pdf_page.url)
)

print(
    "Actual PDF URL:",
    pdf_url
)


# ============================================================
# 11. Fetch PDF Using Captured URL
# ============================================================
#
# We do NOT use response.body().
#
# The original PDF response can become unavailable after
# navigation. Instead, fetch the same PDF URL again.
#
# ============================================================

pdf_response = (
    context.request.get(
        pdf_url,
        timeout=30000
    )
)


# ============================================================
# 12. Verify PDF HTTP Response
# ============================================================

assert pdf_response.ok, (

    f"Unable to fetch PDF.\\n"
    f"Status: {pdf_response.status}\\n"
    f"URL: {pdf_url}"
)

print(
    "PDF fetched successfully."
)

print(
    "PDF response status:",
    pdf_response.status
)


# ============================================================
# 13. Verify Content-Type
# ============================================================

content_type = (
    pdf_response
    .headers
    .get(
        "content-type",
        ""
    )
    .lower()
)

print(
    "PDF Content-Type:",
    content_type
)

assert (
    "application/pdf" in content_type
), (

    f"Expected PDF content type.\\n"
    f"Actual: {content_type}"
)


# ============================================================
# 14. Get PDF Bytes
# ============================================================

pdf_bytes = (
    pdf_response.body()
)

assert pdf_bytes is not None, (
    "PDF response body is None."
)

assert len(pdf_bytes) > 0, (
    "PDF response body is empty."
)


# ============================================================
# 15. Verify PDF Header
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "Response is not a valid PDF."
)

print(
    "Valid PDF detected."
)

print(
    "PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 16. Read PDF From Memory
# ============================================================

reader = PdfReader(
    BytesIO(
        pdf_bytes
    )
)


# ============================================================
# 17. Verify PDF Page Count
# ============================================================

page_count = len(
    reader.pages
)

print(
    "PDF page count:",
    page_count
)

assert page_count > 0, (
    "PDF contains no pages."
)


# ============================================================
# 18. Extract PDF Content
# ============================================================

pdf_text = ""


for page_number, pdf_document_page in enumerate(
    reader.pages,
    start=1
):

    try:

        page_text = (
            pdf_document_page
            .extract_text()
            or ""
        )

        pdf_text += (
            page_text
            + "\\n"
        )

    except Exception as e:

        print(
            f"Unable to extract PDF page "
            f"{page_number}: {e}"
        )


# ============================================================
# 19. Verify PDF Content
# ============================================================

assert pdf_text.strip(), (
    "PDF content is empty."
)


# ============================================================
# 20. Print PDF Content
# ============================================================

print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)

print(
    "PDF content read successfully."
)


# ============================================================
# 21. Normalize Values
# ============================================================

pdf_text_normalized = " ".join(
    pdf_text.split()
)

ui_order_number_normalized = " ".join(
    ui_order_number.split()
)


# ============================================================
# 22. Verify UI Order # In PDF
# ============================================================

assert (
    ui_order_number_normalized
    in pdf_text_normalized
), (

    f"\\nOrder # validation failed.\\n"
    f"UI Order #: {ui_order_number}\\n"
    f"Order # was not found in PDF."
)


print(
    "Order # verified successfully in PDF:"
)

print(
    "UI Order #:",
    ui_order_number
)


# ============================================================
# 23. Final Result
# ============================================================

print(
    "\\n============================================================"
)

print(
    "PRINT PDF VALIDATION PASSED"
)

print(
    "============================================================"
)

print(
    "PDF opened in new tab successfully."
)

print(
    "Actual PDF URL:",
    pdf_url
)

print(
    "PDF page count:",
    page_count
)

print(
    "PDF content read successfully."
)

print(
