(17705,20511,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO


# ============================================================
# 1. Capture Order # From Selected Rows
# ============================================================

selected_rows = page.locator(
    "//div[@role=\'row\' and @aria-selected=\'true\']"
)

selected_row_count = selected_rows.count()

assert selected_row_count > 0, (
    "No selected rows found."
)

print(
    "Selected rows:",
    selected_row_count
)


selected_order_numbers = []

for i in range(selected_row_count):

    row = selected_rows.nth(i)

    order_cell = row.locator(
        "div[role=\'gridcell\'][data-field=\'orderId\']"
    )

    if order_cell.count() == 0:
        continue

    order_number = (
        order_cell.first.inner_text()
        .strip()
    )

    if order_number:

        selected_order_numbers.append(
            order_number
        )


assert selected_order_numbers, (
    "Order # was not found in selected rows."
)


print(
    "\\nSelected Order # values:"
)

for order_number in selected_order_numbers:

    print(
        order_number
    )


# ============================================================
# 2. Locate Print Button
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(
    timeout=10000
)

print(
    "Print button found."
)


# ============================================================
# 3. PDF URL Storage
# ============================================================

pdf_data = {
    "url": None,
    "content_type": None
}


# ============================================================
# 4. Capture PDF URL Only
# ============================================================

def handle_response(response):

    try:

        content_type = response.headers.get(
            "content-type",
            ""
        ).lower()

        response_url = response.url

        if (
            "application/pdf" in content_type
            or ".pdf" in response_url.lower()
        ):

            print(
                "\\nPDF response detected:"
            )

            print(
                "PDF URL:",
                response_url
            )

            print(
                "Content-Type:",
                content_type
            )

            # IMPORTANT:
            # Do NOT call response.body() here.
            # This response is used for PDF navigation.

