(17710,20512,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# 1. Get UI Pagination
# ============================================================

pagination_locator = page.locator(
    "//p[contains(@class,\'MuiTablePagination-displayedRows\')]"
)

expect(
    pagination_locator
).to_be_visible(timeout=10000)

pagination_text = (
    pagination_locator
    .inner_text()
    .strip()
)

