    try:

        request_url = (
            request.url
            .lower()
        )

        if (
            ".pdf" in request_url
            or "/genpdfs/" in request_url
        ):

            pdf_request_data["url"] = (
                request.url
            )

            print(
                "PDF request detected:",
                request.url
            )

    except Exception as e:

        print(
            "Unable to inspect request:",
            e
        )


