    )

    print(
        "Order # verified:",
        ui_order_number
    )

    print(
        "Credit ID verified:",
        ui_credit_id
    )

    print(
        "Inventory Cost heading verified:",
        detected_heading
    )

    print(
        "Inventory Cost treated as BLANK."
    )

    print(
        "PDF content read successfully."
    )

    print(
        "============================================================"
    )


finally:

