pdf_request_data = {
    "request": None
}


def handle_request(request):

    try:

        request_url = (
            request.url
            .lower()
        )

        if (
            ".pdf" in request_url
            or "/genpdfs/" in request_url
            or "receiptcredit.pdf" in request_url
        ):

            pdf_request_data["request"] = request

            print(
                "PDF request detected:",
                request.url
            )

            print(
                "PDF request method:",
                request.method
            )

    except Exception as e:

        print(
            "Unable to inspect request:",
            e
        )


context.on(
