    )


    # ========================================================
    # 29. Verify Page Count
    # ========================================================

    page_count = len(
        reader.pages
    )

    print(
        "PDF page count:",
        page_count
    )

    assert page_count > 0, (
        "PDF contains no pages."
    )


    # ========================================================
    # 30. Extract PDF Text
    # ========================================================

    pdf_text = ""

    for page_number, pdf_document_page in enumerate(
        reader.pages,
        start=1
    ):

        try:

            page_text = (
                pdf_document_page
                .extract_text()
                or ""
            )

            pdf_text += (
                page_text
                + "\\n"
            )

        except Exception as e:

            print(
                f"Unable to extract PDF page "
                f"{page_number}: {e}"
