# Capture Product ID value
product_id = product_id_cell.inner_text().strip()

print(f"Product ID: {product_id}")

set_var("product_id", product_id)','from playwright.sync_api import expect

# Locate the first Product ID cell
product_id_cell = page.locator(\'[data-field="productId"]\').nth(1)

