(18085,20914,'custom','import os
import csv
import xlwt

# ==================================================
# 1. Export Inventory Summary Report as CSV
# ==================================================

export_button = page.locator(
    "xpath=//span[normalize-space()=\'Export as CSV\']"
)

expect(
    export_button
).to_be_visible(timeout=10000)

with page.expect_download() as download_info:
    export_button.click()

download = download_info.value

# ==================================================
# 2. Download Information
# ==================================================

filename = download.suggested_filename

print(
    "Filename:",
    filename
)

# ==================================================
# 3. Download Location
# ==================================================

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(
    file_path
)

print(
    "Saved file:",
    file_path
)

# ==================================================
# 4. Verify CSV
# ==================================================

assert os.path.exists(
    file_path
), (
    f"Downloaded file was not saved: {file_path}"
)

assert os.path.getsize(
    file_path
) > 0, (
    f"Downloaded file is empty: {file_path}"
)

assert filename.lower().endswith(
    ".csv"
), (
    f"Expected CSV file, but downloaded: {filename}"
)

print(
    "SUCCESS: Inventory Summary Report CSV "
    "downloaded successfully."
)

# ==================================================
# 5. Read Original CSV
# ==================================================

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)

    rows = list(reader)

assert len(rows) > 0, (
    "Inventory Summary Report CSV "
    "does not contain any data."
)

print(
    "Original CSV rows:",
    len(rows)
)

# ==================================================
# 6. Find Header Row Automatically
# ==================================================

header_row_index = None

for index, row in enumerate(rows):

    cleaned_row = [
        column.strip().strip(\'="\')
        for column in row
    ]

    if (
        "Product Type" in cleaned_row
        and "Product ID" in cleaned_row
        and "Description" in cleaned_row
        and "Location" in cleaned_row
        and "Current Stock" in cleaned_row
    ):
        header_row_index = index
        break

assert header_row_index is not None, (
    "Inventory Summary Report column "
    "header row was not found."
)

print(
    "Column header found at row:",
    header_row_index + 1
)

# ==================================================
# 7. Get Original Column Names
# ==================================================

headers = [
    column.strip().strip(\'="\')
    for column in rows[header_row_index]
]

print(
    "Total columns:",
    len(headers)
)

# ==================================================
# 8. Rename ONLY Required Adjustment Columns
#
# Final column names:
#
# Adjust Price
# Adjust Grade
# adjust Stock type
# Adjust Bulk TFR FRT Cost
# Adjust PO Transit FRT Cost
# ==================================================

column_rename_map = {
    "Adjusted Price":
        "Adjust Price",

    "Adjusted Grade":
        "Adjust Grade",

    "Adjust Stock Type":
        "adjust Stock type",

    "Adjust Bulk TFR FRT Cost":
        "Adjust Bulk TFR FRT Cost",

    "Adjust PO Transit FRT Cost":
        "Adjust PO Transit FRT Cost"
}

headers = [
    column_rename_map.get(
        column,
        column
    )
    for column in headers
]

print(
    "SUCCESS: Required adjustment "
    "column names updated."
)

# ==================================================
# 9. Get Data Rows Below Header
# ==================================================

data_rows = rows[
    header_row_index + 1:
]

data_rows = [
    row
    for row in data_rows
    if any(
        cell.strip()
        for cell in row
    )
]

print(
    "Original data rows:",
    len(data_rows)
)

# ==================================================
# 10. Keep ONLY First 5 Data Rows
# ==================================================

first_five_rows = data_rows[:5]

assert len(first_five_rows) == 5, (
    f"Expected exactly 5 data rows, "
    f"but found {len(first_five_rows)}."
)

print(
    "Rows retained:",
    len(first_five_rows)
)

# ==================================================
# 11. Create Filtered CSV
# Header + ONLY 5 Data Rows
# ==================================================

final_rows = [
    headers
] + first_five_rows

temp_file_path = (
    file_path + ".tmp"
)

with open(
    temp_file_path,
    mode="w",
    encoding="utf-8-sig",
    newline=""
) as file:

    writer = csv.writer(file)

    writer.writerows(
        final_rows
    )

os.replace(
    temp_file_path,
    file_path
)

print(
    "SUCCESS: Filtered CSV saved:",
    file_path
)

# ==================================================
# 12. Read Final CSV
# ==================================================

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
