        return True
    except Exception as e:
        print(f"Could not click the Print button: {e}")
        return False


def click_print_and_expect_download():
    try:
        with page.expect_download(
            timeout=DOWNLOAD_EVENT_TIMEOUT * 1000
        ) as download_info:
            if not click_print_button():
                raise RuntimeError("Print button was not clickable.")
        return download_info.value
    except PlaywrightTimeoutError:
        print("No download event fired - the PDF may be in a tab.")
        return None
    except RuntimeError:
        return None


def save_download(download):
    filename = download.suggested_filename or "printed.pdf"
    target = DOWNLOAD_FOLDER / filename
    download.save_as(target)
    print("Download saved to:", target)
    return target


def scan_tabs_for_pdf():
    for index, tab in enumerate(context.pages):
        url = tab.url or ""
        print(f"Tab {index}: {url!r}")

        if url.startswith("blob:"):
            print(f"PDF tab found at index {index} (top-level blob URL)")
            return tab, url

        for frame in tab.frames:
            if (frame.url or "").startswith("blob:"):
                print(f"PDF found in a frame of tab {index}")
                return tab, frame.url

        try:
            src = tab.evaluate(
                "() => { const e = document.querySelector("
                "\'embed,iframe,object\');"
                " return e ? (e.src || e.data || null) : null; }"
            )
            if src and src.startswith("blob:"):
                print(f"PDF found in an embedded viewer of tab {index}")
                return tab, src
        except Exception:
            pass

    return None, None


def fetch_blob_bytes(blob_url, pdf_tab):
    parsed = urlparse(blob_url[5:])
    blob_origin = f"{parsed.scheme}://{parsed.netloc}"
    print("Blob source origin:", blob_origin)

    candidates = []

    for tab in context.pages:
        if tab == pdf_tab:
            continue
        tab_parsed = urlparse(tab.url or "")
        if f"{tab_parsed.scheme}://{tab_parsed.netloc}" == blob_origin:
            candidates.append(tab)

    if pdf_tab is not None and not (pdf_tab.url or "").startswith("blob:"):
        candidates.append(pdf_tab)

    if not candidates:
        print("No same-origin page found to fetch the blob from.")
        return None

    for tab in candidates:
        try:
            print("Fetching PDF blob via:", tab.url or "about:blank popup")
            pdf_base64 = tab.evaluate(FETCH_BLOB_AS_BASE64_JS, blob_url)
            return base64.b64decode(pdf_base64)
        except Exception as e:
            print(f"Blob fetch failed on this page: {e}")

    return None


def clean_download_folder():
    if not DOWNLOAD_FOLDER.is_dir():
        return

    pattern = "*.pdf" if DELETE_ONLY_PDFS else "*"
    deleted = 0

    for item in DOWNLOAD_FOLDER.glob(pattern):
        if not item.is_file():
            continue
        try:
            item.unlink()
            deleted += 1
        except Exception as e:
            print(f"Could not delete {item}: {e}")

    print(f"Cleanup: deleted {deleted} file(s) from {DOWNLOAD_FOLDER}")


DOWNLOAD_FOLDER.mkdir(parents=True, exist_ok=True)
print("Download folder:", DOWNLOAD_FOLDER)

pdf_bytes = None
pdf_source = None
pdf_page = None
saved_pdf_path = None

try:
    for attempt in range(1, ATTEMPTS + 1):
        print(f"\\nAttempt {attempt}/{ATTEMPTS}")

        download = None
        if attempt <= CLICK_ON_FIRST_N_ATTEMPTS:
            download = click_print_and_expect_download()

        if download is None and popup_downloads:
            download = popup_downloads[0]
            print("Download captured from a popup page.")

        if download is not None:
            saved_pdf_path = save_download(download)
            pdf_bytes = saved_pdf_path.read_bytes()
            pdf_source = f"download event ({saved_pdf_path.name})"
            break

        pdf_page, blob_url = scan_tabs_for_pdf()

        if blob_url:
            print("PDF blob URL:", blob_url)
            pdf_bytes = fetch_blob_bytes(blob_url, pdf_page)
            if pdf_bytes:
                pdf_source = "new tab (blob URL)"
                break

        if attempt < ATTEMPTS:
            page.wait_for_timeout(TAB_CHECK_INTERVAL * 1000)

    assert pdf_bytes is not None, (
        "PDF was not obtained: no download event fired AND no "
        f"PDF tab appeared after {ATTEMPTS} attempts."
    )

    print("\\nPDF obtained from:", pdf_source)
    print("PDF size:", len(pdf_bytes), "bytes")

    assert pdf_bytes.startswith(b"%PDF"), (
        "Downloaded content is not a valid PDF."
    )
    print("Valid PDF detected.")

    reader = PdfReader(BytesIO(pdf_bytes))
    print("PDF page count:", len(reader.pages))

    pdf_text = ""
    for page_number, pdf_document_page in enumerate(reader.pages, start=1):
        try:
            page_text = pdf_document_page.extract_text() or ""
            pdf_text += f"\\n--- PDF Page {page_number} ---\\n" + page_text
        except Exception as e:
            print(
                f"Unable to extract text from PDF page {page_number}: {e}"
            )

    print("\\n================ PDF TEXT ================\\n")
    print(pdf_text)
    print("\\n===========================================\\n")

    expected_text = EXPECTED_TEXT

    print("Expected PDF text:", expected_text)

    assert expected_text in pdf_text, (
        "\\nPDF VALIDATION FAILED\\n"
        f"Expected text was not found:\\n{expected_text}\\n"
        f"(PDF source: {pdf_source})\\n"
    )

    print(f"PDF VALIDATION PASSED: \'{expected_text}\' found in PDF.")

    if pdf_page is not None:
        page = pdf_page
        print("Active page switched to PDF tab:", page.url)

finally:
    clean_download_folder()
