(18289,21127,'custom','from playwright.sync_api import expect
import os


print(
    "\\n============================================================"
)
print(
    "CLICKING EXCEL EXPORT AND VERIFYING EXCEL DOWNLOAD"
)
print(
    "============================================================"
)


# ============================================================
# 1. LOCATE ENABLED EXCEL EXPORT BUTTON
# ============================================================

export_button = page.locator(
    "button[title=\'Excel Export\']:not([disabled])"
)


# Verify exactly one enabled Excel Export button exists

assert export_button.count() == 1, (
    f"Expected exactly 1 enabled Excel Export button, "
    f"but found {export_button.count()}"
)


# Verify button is visible

expect(
    export_button
).to_be_visible(timeout=10000)


# Verify button is enabled

expect(
    export_button
).to_be_enabled(timeout=10000)


print(
    "SUCCESS: Enabled Excel Export button is visible and enabled."
)


# ============================================================
# 2. CLICK EXCEL EXPORT
#
# The application may take more than 30 or 60 seconds to
# generate the Excel report.
#
# Therefore use a 3-minute download timeout.
# ============================================================

print(
    "\\nClicking Excel Export button..."
)

print(
    "Waiting for Excel file download. "
    "Export may take several minutes..."
)


with page.expect_download(
    timeout=180000
) as download_info:

    export_button.click()


# ============================================================
# 3. GET DOWNLOAD
# ============================================================

download = (
    download_info.value
)


print(
    "\\nSUCCESS: Excel download event detected."
)


# ============================================================
# 4. GET DOWNLOADED FILENAME
# ============================================================

filename = (
    download.suggested_filename
)


print(
    "Downloaded filename:",
    filename
)


# ============================================================
# 5. VERIFY EXCEL FILE EXTENSION
# ============================================================

assert filename.lower().endswith(
    (
        ".xlsx",
        ".xls"
    )
), (
    f"Expected an Excel file, "
    f"but downloaded file is: {filename}"
)


print(
    "SUCCESS: Downloaded file has a valid Excel extension."
)


# ============================================================
# 6. CREATE DOWNLOAD DIRECTORY
# ============================================================

download_dir = (
    "/tmp/downloads"
)


os.makedirs(
    download_dir,
    exist_ok=True
)


# ============================================================
# 7. SAVE DOWNLOADED FILE
# ============================================================

file_path = os.path.join(
    download_dir,
    filename
)


# Remove existing file if present

if os.path.exists(
    file_path
):

    os.remove(
        file_path
    )


print(
    "Saving Excel file..."
)


download.save_as(
    file_path
)


print(
    "Excel file saved:",
    file_path
)


# ============================================================
# 8. VERIFY FILE EXISTS
# ============================================================

assert os.path.exists(
    file_path
), (
    f"Excel file was not saved: {file_path}"
)


print(
    "SUCCESS: Excel file exists."
)


# ============================================================
# 9. VERIFY FILE IS NOT EMPTY
# ============================================================

file_size = (
    os.path.getsize(
        file_path
    )
)


assert file_size > 0, (
    f"Excel file is empty: {file_path}"
)


print(
    "SUCCESS: Excel file is not empty."
)

print(
    "Excel file size:",
    file_size,
    "bytes"
)


# ============================================================
# 10. OPTIONAL: VERIFY FILE CAN BE READ AS XLSX
#
# Only perform this check for .xlsx files.
# This verifies that the downloaded file is not just a
# non-empty HTML/error response.
# ============================================================

if filename.lower().endswith(
    ".xlsx"
):

    with open(
        file_path,
        "rb"
    ) as excel_file:

        excel_header = (
            excel_file.read(
                4
            )
        )


    # XLSX files are ZIP containers and start with "PK"

    assert excel_header[:2] == b"PK", (
        f"Downloaded XLSX file does not have a valid "
        f"XLSX/ZIP signature. "
        f"Header: {excel_header!r}"
    )


    print(
        "SUCCESS: XLSX file signature is valid."
    )


# ============================================================
# 11. FINAL VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "EXCEL EXPORT VALIDATION PASSED"
)

print(
    "============================================================"
)

print(
    "Excel Export button          : PASS"
)

print(
    "Excel download               : PASS"
)

print(
    f"Excel filename               : PASS ({filename})"
)

print(
    "Excel file exists            : PASS"
)

print(
    f"Excel file not empty         : PASS ({file_size} bytes)"
)

if filename.lower().endswith(
    ".xlsx"
):

    print(
        "XLSX file signature         : PASS"
    )

print(
    "============================================================"
)


# ============================================================
# 12. DELETE FILE AFTER VALIDATION
# ============================================================

os.remove(
    file_path
)


assert not os.path.exists(
    file_path
), (
    f"Excel file was not deleted: {file_path}"
)


print(
    "SUCCESS: Excel file deleted after validation."
)

print(
    "============================================================"
