(18545,21377,'custom','# ============================================================
# INVENTORY ADJUSTMENT PDF VALIDATION
# VALIDATIONS:
#   1. PDF opens in new tab
#   2. PDF can be saved/downloaded
#   3. Unit Cost New Value = 1,345.00
#   4. Quantity (PCS) increased by 5
# ============================================================

from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


print(
    "\\n============================================================"
)
print(
    "CLICKING OK AND VERIFYING INVENTORY ADJUSTMENT PDF"
)
print(
    "============================================================"
)


# ============================================================
# 1. LOCATE CONFIRM POPUP
# ============================================================

# There may be multiple dialogs on the page.
# Find the dialog that contains the Confirm heading.

confirm_dialog = page.locator(
    "//div[@role=\'dialog\']"
).filter(
    has=page.locator(
        "h2",
        has_text="Confirm"
    )
).last


expect(
    confirm_dialog
).to_be_visible(timeout=10000)

print(
    "Inventory Adjustment confirmation dialog is visible."
)


# ============================================================
# 2. CLICK OK BUTTON
# ============================================================

ok_button = confirm_dialog.locator(
    "button",
    has_text=re.compile(
        r"^Ok$",
        re.IGNORECASE
    )
).last


expect(
    ok_button
).to_be_visible(timeout=10000)

expect(
    ok_button
).to_be_enabled(timeout=10000)

print(
    "Ok button is visible and enabled."
)


# ============================================================
# 3. COUNT TABS BEFORE CLICKING OK
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before clicking Ok:",
    tabs_before
)


# ============================================================
# 4. CAPTURE INVENTORY ADJUSTMENT PDF API RESPONSE
# ============================================================

print(
    "Waiting for Inventory Adjustment PDF API response..."
)


with page.expect_response(
    lambda response:
        "imsInventoryAdjustmentPdf.pdf"
        in response.url,
    timeout=30000
) as pdf_response_info:

    ok_button.click()


print(
    "Ok button clicked successfully."
)


# ============================================================
# 5. GET PDF RESPONSE
# ============================================================

pdf_response = (
    pdf_response_info.value
)


print(
    "\\n================ PDF API RESPONSE ================\\n"
)

print(
    "PDF API URL:",
    pdf_response.url
)

print(
    "HTTP Status:",
    pdf_response.status
)

print(
    "Content-Type:",
    pdf_response.headers.get(
        "content-type",
        ""
    )
)

print(
    "\\n===================================================\\n"
)


# ============================================================
# 6. VERIFY PDF API RESPONSE
# ============================================================

assert pdf_response.ok, (
    f"\\nInventory Adjustment PDF API failed.\\n"
    f"Status: {pdf_response.status}\\n"
    f"URL: {pdf_response.url}"
)

print(
    "PDF API HTTP response verification PASSED."
)


# ============================================================
# 7. VERIFY PDF CONTENT TYPE
# ============================================================

content_type = (
    pdf_response.headers.get(
        "content-type",
        ""
    ).lower()
)


assert "application/pdf" in content_type, (
    f"\\nExpected application/pdf.\\n"
    f"Actual Content-Type: {content_type}"
)


print(
    "PDF Content-Type verification PASSED."
)


# ============================================================
# 8. READ PDF BODY IMMEDIATELY
# ============================================================

print(
    "Reading PDF response body..."
)


pdf_bytes = (
    pdf_response.body()
)


assert pdf_bytes is not None, (
    "PDF response body is None."
)


assert len(pdf_bytes) > 0, (
    "PDF response body is empty."
)


print(
    "PDF response body captured successfully."
)

print(
    "PDF size:",
    len(pdf_bytes),
    "bytes"
)


# ============================================================
# 9. VERIFY PDF HEADER
# ============================================================

assert pdf_bytes.startswith(
    b"%PDF"
), (
    "PDF API response does not contain a valid PDF."
)


print(
    "Valid PDF header verification PASSED."
)


# ============================================================
# 10. WAIT FOR NEW PDF TAB
# ============================================================

timeout_ms = 20000
poll_interval_ms = 500

elapsed = 0
pdf_page = None


while elapsed < timeout_ms:

    if len(context.pages) > tabs_before:

        pdf_page = context.pages[-1]

        print(
            "\\nNew PDF tab detected."
        )

        print(
            "PDF tab URL:",
            pdf_page.url
        )

        break

    page.wait_for_timeout(
        poll_interval_ms
    )

    elapsed += poll_interval_ms


# ============================================================
# 11. VERIFY NEW TAB
# ============================================================

tabs_after = len(
    context.pages
)


print(
    "\\nTabs before clicking Ok:",
    tabs_before
)

print(
    "Tabs after clicking Ok:",
    tabs_after
)


assert tabs_after > tabs_before, (
    "\\nInventory Adjustment PDF did not open "
    "in a new tab.\\n"
    f"Tabs before: {tabs_before}\\n"
    f"Tabs after : {tabs_after}"
)


pdf_page = context.pages[-1]


print(
    "PDF opened in new tab successfully."
)

print(
    "PDF tab URL:",
    pdf_page.url
)


# ============================================================
# 12. VERIFY PDF VIEWER TAB
# ============================================================

pdf_page.wait_for_timeout(
    1000
)


pdf_tab_url = pdf_page.url


print(
    "Final PDF tab URL:",
    pdf_tab_url
)


assert (
    pdf_tab_url.startswith("blob:")
    or "application/pdf" in pdf_tab_url.lower()
    or pdf_tab_url == ""
), (
    f"Unexpected PDF tab URL: {pdf_tab_url}"
)


print(
    "PDF viewer tab verification PASSED."
)


# ============================================================
# 13. DETERMINE PDF FILENAME
# ============================================================

content_disposition = (
    pdf_response.headers.get(
        "content-disposition",
        ""
    )
)


filename_match = re.search(
    r\'filename="?([^";]+)"?\',
    content_disposition,
    re.IGNORECASE
)


if filename_match:

    expected_filename = (
        filename_match.group(1)
    )

else:

    expected_filename = (
        "Inventory_Adjustment.pdf"
    )


if not expected_filename.lower().endswith(
    ".pdf"
):

    expected_filename += ".pdf"


print(
    "PDF filename:",
    expected_filename
)


# ============================================================
# 14. SAVE PDF
# ============================================================

download_dir = "/tmp/downloads"

os.makedirs(
    download_dir,
    exist_ok=True
)


file_path = os.path.join(
    download_dir,
    expected_filename
)


if os.path.exists(file_path):

    os.remove(file_path)


with open(
    file_path,
    "wb"
) as downloaded_file:

    downloaded_file.write(
        pdf_bytes
    )


print(
    "PDF saved successfully:",
    file_path
)


# ============================================================
# 15. VERIFY DOWNLOADED FILE
# ============================================================

assert os.path.exists(
    file_path
), (
    f"PDF was not saved:\\n{file_path}"
)


file_size = os.path.getsize(
    file_path
)


assert file_size > 0, (
    "Saved PDF is empty."
)


print(
    "PDF download/save verification PASSED."
)

print(
    "Downloaded PDF size:",
    file_size,
    "bytes"
)


# ============================================================
# 16. READ PDF USING PYPDF
# ============================================================

reader = PdfReader(
    BytesIO(pdf_bytes)
)


assert len(reader.pages) > 0, (
    "PDF does not contain any pages."
)


print(
    "PDF page count:",
    len(reader.pages)
)


# ============================================================
# 17. EXTRACT PDF TEXT
# ============================================================

pdf_text = ""


for pdf_document_page in reader.pages:

    page_text = (
        pdf_document_page.extract_text()
        or ""
    )

    pdf_text += (
        page_text
        + "\\n"
    )


assert pdf_text.strip(), (
    "Unable to extract text from PDF."
)


print(
    "\\n================ PDF CONTENT ================\\n"
)

print(
    pdf_text
)

print(
    "\\n==============================================\\n"
)


# ============================================================
# 18. NORMALIZE PDF TEXT
# ============================================================

normalized_pdf_text = " ".join(
    pdf_text.split()
)


print(
    "Normalized PDF text:",
    normalized_pdf_text
)


# ============================================================
# 19. VERIFY UNIT COST
# ============================================================
#
# Expected PDF:
#
# Unit Cost
# 19,136.54
# 1,345.00
# -17,791.54
#
# We only validate the NEW VALUE.
# ============================================================

unit_cost_pattern = re.compile(
    r"Unit\\s+Cost\\s+"
    r"([\\d,]+\\.\\d{2})\\s+"
    r"([\\d,]+\\.\\d{2})\\s+"
    r"(-?[\\d,]+\\.\\d{2})",
    re.IGNORECASE
)


unit_cost_match = (
    unit_cost_pattern.search(
        normalized_pdf_text
    )
)


assert unit_cost_match is not None, (
    "Unit Cost row was not found in PDF.\\n"
    f"PDF Text:\\n{pdf_text}"
)


unit_cost_old = (
    unit_cost_match.group(1)
)

unit_cost_new = (
    unit_cost_match.group(2)
)

unit_cost_variance = (
    unit_cost_match.group(3)
)


print(
    "\\n================ UNIT COST ================\\n"
)

print(
    "Old Value:",
    unit_cost_old
)

print(
    "New Value:",
    unit_cost_new
)

print(
    "Variance:",
    unit_cost_variance
)

print(
    "\\n============================================\\n"
)


# ============================================================
# 20. VERIFY UNIT COST NEW VALUE
# ============================================================

expected_unit_cost_new = (
    "1,345.00"
)


assert unit_cost_new == (
    expected_unit_cost_new
), (
    f"Expected Unit Cost New Value = "
    f"{expected_unit_cost_new}, "
    f"but found {unit_cost_new}"
)


print(
    "Unit Cost New Value verification PASSED."
)


# ============================================================
# 21. VERIFY QUANTITY (PCS)
# ============================================================
#
# IMPORTANT:
# PDF text contains:
#
# Quantity (PCS) 2,038 2,043 5
#
# The previous regex expected integers without commas.
# That is why it failed.
#
# This regex supports comma-formatted values.
# ============================================================

quantity_pattern = re.compile(
    r"Quantity\\s*\\(PCS\\)\\s+"
    r"([\\d,]+)\\s+"
    r"([\\d,]+)\\s+"
    r"(-?[\\d,]+)",
    re.IGNORECASE
)


quantity_match = (
    quantity_pattern.search(
        normalized_pdf_text
    )
)


assert quantity_match is not None, (
    "Quantity (PCS) row was not found in PDF.\\n"
    f"PDF Text:\\n{pdf_text}"
)


quantity_old_text = (
    quantity_match.group(1)
)

quantity_new_text = (
    quantity_match.group(2)
)

quantity_variance_text = (
    quantity_match.group(3)
)


# Remove commas before converting to integers

quantity_old = int(
    quantity_old_text.replace(",", "")
)

quantity_new = int(
    quantity_new_text.replace(",", "")
)

quantity_variance = int(
    quantity_variance_text.replace(",", "")
)


print(
    "\\n================ QUANTITY (PCS) ================\\n"
)

print(
    "Old Value:",
    quantity_old
)

print(
    "New Value:",
    quantity_new
)

print(
    "Variance:",
    quantity_variance
)

print(
    "\\n==================================================\\n"
)


# ============================================================
# 22. VERIFY QUANTITY INCREASED BY 5
# ============================================================

expected_quantity_new = (
    quantity_old + 5
)


assert quantity_new == (
    expected_quantity_new
), (
    f"Expected Quantity (PCS) New Value = "
    f"{expected_quantity_new}, "
    f"but found {quantity_new}"
)


assert quantity_variance == 5, (
    f"Expected Quantity variance = 5, "
    f"but found {quantity_variance}"
)


assert (
    quantity_new - quantity_old == 5
), (
    f"Quantity did not increase by 5. "
    f"Old={quantity_old}, "
    f"New={quantity_new}"
)


print(
    "Quantity (PCS) verification PASSED."
)

print(
    f"Quantity increased correctly: "
    f"{quantity_old} + 5 = {quantity_new}"
)


# ============================================================
# 23. VERIFY SAVED PDF CAN BE OPENED
# ============================================================

with open(
    file_path,
    "rb"
) as downloaded_file:

    downloaded_bytes = (
        downloaded_file.read()
    )


assert downloaded_bytes.startswith(
    b"%PDF"
), (
    "Saved file is not a valid PDF."
)


downloaded_reader = PdfReader(
    BytesIO(downloaded_bytes)
)


assert len(downloaded_reader.pages) > 0, (
    "Downloaded PDF contains no pages."
)


print(
    "Downloaded PDF can be opened successfully."
)


# ============================================================
# 24. VERIFY DOWNLOADED PDF CONTENT
# ============================================================

downloaded_pdf_text = ""


for downloaded_page in downloaded_reader.pages:

    downloaded_pdf_text += (
        downloaded_page.extract_text()
        or ""
    )

    downloaded_pdf_text += "\\n"


assert downloaded_pdf_text.strip(), (
    "Downloaded PDF content is empty."
)


downloaded_pdf_normalized = " ".join(
    downloaded_pdf_text.split()
)


assert (
    downloaded_pdf_normalized
    == normalized_pdf_text
), (
    "Downloaded PDF content does not match "
    "the original PDF response."
)


print(
    "Downloaded PDF content verification PASSED."
)


# ============================================================
# 25. FINAL VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "INVENTORY ADJUSTMENT PDF VALIDATION PASSED"
)

print(
    "============================================================"
)

print(
    "Confirmation dialog          : PASS"
)

print(
    "Ok button                    : PASS"
)

print(
    "PDF API response             : PASS"
)

print(
    "PDF response body            : PASS"
)

print(
