)

print(
    f"Quantity Old Value           : PASS ({quantity_old})"
)

print(
    f"Quantity New Value           : PASS ({quantity_new})"
)

print(
    f"Quantity Variance            : PASS (+{quantity_variance})"
)

print(
    "Downloaded PDF verified      : PASS"
