# ============================================================

print_received_button = page.get_by_role(
    "button",
    name="Print Received"
)

expect(
    print_received_button
).to_be_visible(timeout=10000)

expect(
    print_received_button
).to_be_enabled(timeout=10000)

print(
    "\\nPrint Received button is visible and enabled."
)


# ============================================================
# 4. Count Existing Tabs
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before clicking Print Received:",
    tabs_before
)


# ============================================================
# 5. Capture ONLY the PDF URL
#
# IMPORTANT:
#
# DO NOT call response.body() here.
#
# The PDF is a navigation response. Chrome can navigate away
# from the response before Playwright can retrieve its body.
# ============================================================

pdf_info = {
    "url": None,
    "status": None,
    "content_type": None
}


def capture_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_http_url = (
            response_url.startswith("http://")
            or response_url.startswith("https://")
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        is_generated_pdf = (
            "/scadmin/genPdfs/" in response_url
            and ".pdf" in response_url.lower()
        )

        if not is_http_url:
            return

        if not (
            is_pdf_content
            or is_generated_pdf
        ):
            return

        # Ignore duplicates
        if pdf_info["url"] is not None:
            return

        pdf_info["url"] = response_url
        pdf_info["status"] = response.status
        pdf_info["content_type"] = content_type

        print(
            "\\n=============================================="
        )

        print(
            "Print Received PDF response detected."
        )

        print(
            "PDF URL:",
            response_url
        )

        print(
            "HTTP Status:",
            response.status
        )

        print(
            "Content-Type:",
            content_type
        )

        print(
            "PDF URL captured successfully."
        )

        print(
            "==============================================\\n"
        )

    except Exception as e:

        print(
            "Error while capturing PDF response:",
            e
        )


# ============================================================
# 6. Register Context-Level Response Listener
#
# This catches the response even though the PDF opens in
