)


transit_pattern = re.compile(
    r"(?:"
    r"Transit\\s+Number"
    r"|"
    r"Numéro\\s+de\\s+transit"
    r")"
    r"\\s*[:#-]?\\s*"
    + re.escape(ui_transit_number)
    + r"\\b",
    re.IGNORECASE
)


