from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# 1. Capture values from the UI BEFORE clicking Print Received
# ============================================================

# ------------------------------------------------------------
# Transit ID from page header
# ------------------------------------------------------------

transit_header = page.locator(
    "h6",
    has_text="Transit ID:"
).first

expect(
    transit_header
).to_be_visible(
    timeout=10000
)

transit_header_text = (
    transit_header.inner_text()
)

print(
    "Transit header:",
    transit_header_text
)

# Example:
# Transit ID: (231187) , Shipment # (1091203) , Received by: TestA, Load # (00001)

transit_match = re.search(
    r"Transit ID:\\s*\\((\\d+)\\)",
    transit_header_text
)

assert transit_match, (
    f"Unable to extract Transit ID from UI:\\n"
    f"{transit_header_text}"
)

expected_transit_number = (
    transit_match.group(1)
)

print(
    "Expected Transit Number from UI:",
    expected_transit_number
)


# ------------------------------------------------------------
# First row product description
# ------------------------------------------------------------

first_row = page.locator(
    \'[role="row"][data-rowindex="0"]\'
).first

expect(
    first_row
).to_be_visible(
    timeout=10000
)

description_cell = first_row.locator(
    \'[data-field="internalName"]\'
)

expect(
    description_cell
).to_be_visible(
    timeout=10000
)

expected_product_description = (
    description_cell.get_attribute("title")
    or description_cell.inner_text()
)

expected_product_description = (
    expected_product_description.strip()
)

assert expected_product_description, (
    "First row product description is empty."
)

print(
    "Expected product description from UI:"
)

print(
    repr(expected_product_description)
)


# ============================================================
# 2. Locate Print Received Button
# ============================================================

print_received_button = page.locator(
    "//button[normalize-space()=\'Print Received\']"
)

expect(
    print_received_button
).to_be_visible(
    timeout=10000
)

expect(
    print_received_button
).to_be_enabled(
    timeout=10000
)

print(
    "Print Received button found and enabled."
)


# ============================================================
# 3. Store PDF Response
# ============================================================

pdf_response_data = {
    "response": None
}


# ============================================================
# 4. PDF Response Listener
# ============================================================

def capture_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        # PDF generated by the application
        if (
            "/scadmin/genPdfs/" in response_url
            and (
                "application/pdf" in content_type
                or response_url.lower().split("?")[0].endswith(".pdf")
            )
        ):

            pdf_response_data["response"] = response

            print(
                "\\nPDF response detected:"
            )

            print(
                "PDF URL:",
                response_url
            )

            print(
                "Content-Type:",
                content_type
            )

    except Exception as e:

        print(
            "Unable to capture PDF response:",
            e
        )


# Register BEFORE clicking Print Received
context.on(
    "response",
    capture_pdf_response
)


# ============================================================
# 5. Count Tabs Before Print Received
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before Print Received:",
    tabs_before
)


