(18594,21431,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None
route_registered = False

pdf_info = {
    "url": None,
    "status": None,
    "content_type": None,
    "body": None
}


# ============================================================
# 1. Get Dynamic Transit ID from Intransit Details
# ============================================================

transit_header = page.locator(
    "h6",
    has_text="Intransit Details"
).first

expect(
    transit_header
).to_be_visible(timeout=10000)

transit_header_text = transit_header.inner_text()

print(
    "\\nIntransit header from UI:",
    transit_header_text
)


transit_match = re.search(
    r"Intransit\\s+Details\\s*\\(\\s*#?\\s*(\\d+)\\s*\\)",
    transit_header_text,
    re.IGNORECASE
)

assert transit_match, (
    "Transit ID was not found in Intransit Details header.\\n"
    f"Header: {transit_header_text}"
)

ui_transit_number = transit_match.group(1)

print(
    "Transit Number from UI:",
    ui_transit_number
)


# ============================================================
# 2. Get Product Description from First Row
# ============================================================

product_description_locator = page.locator(
    "//div[@data-id=\'1\' and @data-rowindex=\'0\']"
    "//div[@data-field=\'internalName\']"
)

expect(
    product_description_locator
).to_be_visible(timeout=10000)

ui_product_description = (
    product_description_locator.inner_text()
)

ui_product_description_normalized = " ".join(
    ui_product_description.split()
)

print(
    "\\nProduct Description from UI:",
    ui_product_description
)

print(
    "Normalized Product Description:",
    ui_product_description_normalized
)

assert ui_product_description_normalized, (
    "Product Description from first row is empty."
)


# ============================================================
# 3. Locate Print Button
# ============================================================

print_button = page.locator(
    "//button[normalize-space()=\'Print\']"
)

expect(
    print_button
).to_be_visible(timeout=10000)

expect(
    print_button
).to_be_enabled(timeout=10000)

print(
    "\\nPrint button is visible and enabled."
)


# ============================================================
# 4. Count Tabs Before Clicking Print
# ============================================================

tabs_before = len(
    context.pages
)

print(
    "Tabs before clicking Print:",
    tabs_before
)


# ============================================================
# 5. Intercept the REAL Browser PDF Request
#
# IMPORTANT:
#
# We do NOT use:
#
#     context.request.get(pdf_url)
#
# because the application returns an HTML error page when the
# PDF URL is replayed independently.
#
# Instead:
#
#     route.fetch()
#
# executes the REAL browser request with the browser\'s current
# session/request context.
#
# We immediately read response.body() before navigation can
# invalidate the network resource.
# ============================================================

def handle_intransit_pdf(route):

    request = route.request

    request_url = request.url

    # Only intercept the actual Intransit PDF endpoint.
    if (
        "/api/scadmin/control/imsInTransit.pdf"
        not in request_url
    ):

        route.continue_()

        return


    print(
        "\\n================================================"
    )

    print(
        "Actual browser Print Intransit PDF request intercepted."
    )

    print(
        "Request URL:",
        request_url
    )


    try:

        # ----------------------------------------------------
        # Fetch the request through the browser route.
        # ----------------------------------------------------

        response = route.fetch()

        response_url = response.url

        response_status = response.status

        response_headers = response.headers

        response_content_type = (
            response_headers.get(
                "content-type",
                ""
            ).lower()
        )


        print(
            "PDF response URL:",
            response_url
        )

        print(
            "HTTP Status:",
            response_status
        )

        print(
            "Content-Type:",
            response_content_type
        )


        # ----------------------------------------------------
        # IMPORTANT:
        #
        # Read the body immediately.
        #
        # This avoids:
        #
        # Network.getResponseBody:
        # No resource with given identifier found
        # ----------------------------------------------------

        response_body = response.body()


        print(
            "Actual response body size:",
            len(response_body),
            "bytes"
        )


        # ----------------------------------------------------
        # Check whether the actual response is really PDF.
        # ----------------------------------------------------

        pdf_signature_index = (
            response_body.find(b"%PDF")
        )


        if pdf_signature_index < 0:

            print(
                "\\nERROR: Actual browser response does not "
                "contain PDF signature."
            )

            print(
                "First 200 bytes:"
            )

            print(
                repr(response_body[:200])
            )

            # Still fulfill the request so the browser can
            # receive the server response.
            route.fulfill(
                response=response
            )

            return


        # ----------------------------------------------------
        # Remove any bytes before %PDF if present.
        # ----------------------------------------------------

        if pdf_signature_index > 0:

            print(
                "PDF signature found at byte offset:",
                pdf_signature_index
            )

            response_body = (
                response_body[pdf_signature_index:]
            )


        # ----------------------------------------------------
        # Save captured PDF information.
        # ----------------------------------------------------

        pdf_info["url"] = response_url
        pdf_info["status"] = response_status
        pdf_info["content_type"] = response_content_type
        pdf_info["body"] = response_body


        print(
            "REAL PDF BODY CAPTURED SUCCESSFULLY."
        )

        print(
            "PDF size:",
            len(response_body),
            "bytes"
        )


        print(
            "================================================\\n"
        )


        # ----------------------------------------------------
        # Return the original server response to the browser.
        # ----------------------------------------------------

        route.fulfill(
            response=response
        )


    except Exception as e:

        print(
            "Error while intercepting Print Intransit PDF:",
            e
        )

        # Make sure the browser request is not blocked.
        try:

            route.continue_()

        except Exception:

            pass


# ============================================================
# 6. Register Route
# ============================================================

context.route(
    "**/api/scadmin/control/imsInTransit.pdf*",
    handle_intransit_pdf
)

route_registered = True


try:

    # ========================================================
    # 7. Click Print
    # ========================================================

    print(
        "\\nClicking Print..."
    )

    print_button.click(
        force=True
    )

    print(
        "Print button clicked successfully."
    )


    # ========================================================
    # 8. Locate Print Intransit Menu
    #
    # Using YOUR existing code.
    # ========================================================

    print_intransit = page.locator(
        "//li[@role=\'menuitem\' and contains(.,\'Print Intransit\')]"
    )

    expect(
        print_intransit
    ).to_be_visible(timeout=10000)

    print(
        "Print Intransit menu is visible."
    )


    # ========================================================
    # 9. Click Print Intransit + Capture New Tab
    # ========================================================

    print(
        "\\nClicking Print Intransit..."
    )


    with context.expect_page(
        timeout=30000
    ) as new_page_info:

        # Your existing click
        print_intransit.click(
            force=True
        )


    pdf_page = new_page_info.value


    print(
        "Print Intransit clicked successfully."
    )

    print(
        "New PDF tab detected."
    )


    # ========================================================
    # 10. Wait for PDF Tab
    # ========================================================

    try:

        pdf_page.wait_for_load_state(
            "domcontentloaded",
            timeout=30000
        )

    except Exception:

        # Chrome PDF viewer may not expose a normal DOM load
        # state. This is acceptable.
        pass


    print(
        "PDF tab URL:",
        pdf_page.url
    )


    # ========================================================
    # 11. Wait for REAL PDF Body
    #
    # The route handler captures the body.
    # ========================================================

    timeout_ms = 30000
    poll_interval_ms = 250

    elapsed = 0


    while (
        pdf_info["body"] is None
        and elapsed < timeout_ms
    ):

        page.wait_for_timeout(
            poll_interval_ms
        )

        elapsed += poll_interval_ms


    # ========================================================
    # 12. Verify PDF Was Captured
    # ========================================================

    assert pdf_info["body"] is not None, (
        "\\nActual Print Intransit PDF response was not captured.\\n"
        "The new tab opened, but the browser PDF body was not "
        "intercepted."
    )


    pdf_url = pdf_info["url"]

    pdf_status = pdf_info["status"]

    pdf_content_type = pdf_info["content_type"]

    pdf_bytes = pdf_info["body"]


    print(
        "\\n================ PDF RESPONSE ================\\n"
    )

    print(
        "PDF URL:",
        pdf_url
    )

    print(
        "HTTP Status:",
        pdf_status
    )

    print(
        "Content-Type:",
        pdf_content_type
    )

    print(
        "PDF Size:",
        len(pdf_bytes),
        "bytes"
    )

    print(
        "\\n==============================================\\n"
    )


    # ========================================================
    # 13. Verify HTTP Status
    # ========================================================

    assert pdf_status == 200, (
        "\\nPDF HTTP response failed.\\n"
        f"Expected: 200\\n"
        f"Actual: {pdf_status}\\n"
        f"URL: {pdf_url}"
    )

    print(
        "PDF HTTP response verification PASSED."
    )


    # ========================================================
    # 14. Verify Content-Type
    # ========================================================

    assert (
        "application/pdf"
        in pdf_content_type
    ), (
        "\\nExpected application/pdf.\\n"
        f"Actual Content-Type: {pdf_content_type}\\n"
        f"URL: {pdf_url}"
    )

    print(
        "PDF Content-Type verification PASSED."
    )


    # ========================================================
    # 15. Verify PDF Signature
    # ========================================================

    pdf_signature_index = (
        pdf_bytes.find(b"%PDF")
    )


    assert pdf_signature_index >= 0, (
        "\\nCaptured response does not contain a valid PDF "
        "signature.\\n"
        f"URL: {pdf_url}\\n"
        f"Response size: {len(pdf_bytes)}\\n"
        f"First 200 bytes: {pdf_bytes[:200]!r}"
    )


    if pdf_signature_index > 0:

        pdf_bytes = (
            pdf_bytes[pdf_signature_index:]
        )


    assert pdf_bytes.startswith(
        b"%PDF"
    ), (
        "Captured response is not a valid PDF."
    )


    print(
        "Valid PDF header verification PASSED."
    )


    # ========================================================
    # 16. Verify New Tab
    # ========================================================

    tabs_after = len(
        context.pages
    )

    print(
        "\\nTabs before clicking Print:",
        tabs_before
    )

    print(
        "Tabs after clicking Print Intransit:",
        tabs_after
    )


    assert tabs_after > tabs_before, (
        "\\nPrint Intransit PDF did not open in a new tab.\\n"
        f"Tabs before: {tabs_before}\\n"
        f"Tabs after: {tabs_after}"
    )


    print(
        "PDF opened in new tab successfully."
    )

    print(
        "PDF tab URL:",
        pdf_page.url
    )


    # ========================================================
    # 17. Verify PDF Can Be Downloaded
    #
    # We already have the REAL PDF body from the actual
    # browser request.
    #
    # We save that exact body as the downloaded PDF instead
    # of replaying the URL with context.request.get().
    # ========================================================

    print(
        "\\nDownloading Print Intransit PDF..."
    )


    # --------------------------------------------------------
    # Determine filename
    # --------------------------------------------------------

    pdf_filename = "Print_Intransit.pdf"


    # The endpoint is:
    #
    # /imsInTransit.pdf
    #
    # but use a readable local filename.
    # --------------------------------------------------------


    download_dir = "/tmp/downloads"

    os.makedirs(
        download_dir,
        exist_ok=True
    )


    downloaded_pdf_path = os.path.join(
        download_dir,
        pdf_filename
    )


    if os.path.exists(
        downloaded_pdf_path
    ):

        os.remove(
            downloaded_pdf_path
        )


    # --------------------------------------------------------
    # Save the ACTUAL captured browser PDF body.
    # --------------------------------------------------------

    with open(
        downloaded_pdf_path,
        "wb"
    ) as pdf_file:

        pdf_file.write(
            pdf_bytes
        )


    print(
        "\\nPDF saved successfully:"
    )

    print(
        downloaded_pdf_path
    )


    # ========================================================
    # 18. Verify Downloaded File
    # ========================================================

    assert os.path.exists(
        downloaded_pdf_path
    ), (
        "Downloaded PDF file does not exist."
    )


    downloaded_file_size = (
        os.path.getsize(
            downloaded_pdf_path
        )
    )


    assert downloaded_file_size > 0, (
        "Downloaded PDF file is empty."
    )


    print(
        "PDF download verification PASSED."
    )

    print(
        "Downloaded PDF size:",
        downloaded_file_size,
        "bytes"
    )


    # ========================================================
    # 19. Verify Downloaded PDF Signature
    # ========================================================

    with open(
        downloaded_pdf_path,
        "rb"
    ) as downloaded_pdf_file:

        downloaded_pdf_bytes = (
            downloaded_pdf_file.read()
        )


    assert downloaded_pdf_bytes.startswith(
        b"%PDF"
    ), (
        "\\nDownloaded file is not a valid PDF.\\n"
        f"First bytes: {downloaded_pdf_bytes[:200]!r}"
    )


    print(
        "Downloaded PDF signature verification PASSED."
    )


    # ========================================================
    # 20. Read PDF With pypdf
    # ========================================================

    reader = PdfReader(
        BytesIO(
            downloaded_pdf_bytes
        )
    )


    assert len(reader.pages) > 0, (
        "PDF contains no pages."
    )


    print(
        "PDF page count:",
        len(reader.pages)
    )


    # ========================================================
    # 21. Extract PDF Text
    # ========================================================

    pdf_text = ""


    for pdf_document_page in reader.pages:

        page_text = (
            pdf_document_page.extract_text()
            or ""
        )

        pdf_text += (
            page_text
            + "\\n"
        )


    assert pdf_text.strip(), (
        "Unable to extract text from Print Intransit PDF."
    )


    print(
        "\\n================ PDF CONTENT ================\\n"
    )

    print(
        pdf_text
    )

    print(
        "\\n==============================================\\n"
    )


    # ========================================================
    # 22. Normalize PDF Text
    # ========================================================

    pdf_text_normalized = " ".join(
        pdf_text.split()
    )


    # ========================================================
    # 23. Verify Transit Number
    # ========================================================

    print(
        "\\n================ TRANSIT NUMBER ================\\n"
    )

    print(
        "Transit Number from UI:",
        ui_transit_number
    )


    # --------------------------------------------------------
    # More flexible pattern.
    #
    # It accepts:
    #
    # Transit Number 231237
    # Transit Number: 231237
    # Transit Number - 231237
    # Transit Number  : 231237
    #
    # --------------------------------------------------------

    transit_pattern = re.compile(
        r"Transit\\s*Number"
        r"\\s*[:#-]?\\s*"
        + re.escape(ui_transit_number)
        + r"\\b",
        re.IGNORECASE
    )


    transit_found = transit_pattern.search(
        pdf_text_normalized
    )


    if not transit_found:

        # Some PDFs may contain just the number without
        # the exact "Transit Number" label.
        #
        # We first check whether the dynamic Transit ID
        # itself exists in the PDF.
        fallback_transit_pattern = re.compile(
            r"\\b"
            + re.escape(ui_transit_number)
            + r"\\b"
        )

        transit_found = (
            fallback_transit_pattern.search(
                pdf_text_normalized
            )
        )


    assert transit_found, (
        "\\nTransit Number mismatch.\\n"
        f"Expected Transit Number from UI: "
        f"{ui_transit_number}\\n"
        f"PDF URL: {pdf_url}\\n\\n"
        f"PDF Text:\\n{pdf_text_normalized}"
    )


    print(
        "Transit Number found in PDF:",
        ui_transit_number
    )

    print(
        "Transit Number verification PASSED."
    )


    # ========================================================
    # 24. Verify Product Description
    # ========================================================

    print(
        "\\n================ PRODUCT DESCRIPTION ================\\n"
    )

    print(
        "Product Description from UI:"
    )

    print(
        ui_product_description_normalized
    )


    assert (
        ui_product_description_normalized
        in pdf_text_normalized
    ), (
        "\\nProduct Description mismatch.\\n"
        "The first-row Product Description from the UI "
        "was not found in the Print Intransit PDF.\\n\\n"
        f"UI Product Description:\\n"
        f"{ui_product_description_normalized}\\n\\n"
        f"PDF URL:\\n"
        f"{pdf_url}\\n\\n"
        f"PDF Text:\\n"
        f"{pdf_text_normalized}"
    )


    print(
        "Product Description found in PDF."
    )

    print(
        "Product Description verification PASSED."
    )


    # ========================================================
    # 25. Verify Downloaded PDF Can Be Opened
    # ========================================================

    with open(
        downloaded_pdf_path,
        "rb"
    ) as downloaded_pdf_file:

        downloaded_pdf_bytes = (
            downloaded_pdf_file.read()
        )


    downloaded_reader = PdfReader(
        BytesIO(
            downloaded_pdf_bytes
        )
    )


    assert len(downloaded_reader.pages) > 0, (
        "Downloaded PDF contains no pages."
    )


    print(
        "Downloaded PDF can be opened successfully."
    )


    # ========================================================
    # 26. Extract Downloaded PDF Text
    # ========================================================

    downloaded_pdf_text = ""


    for downloaded_page in downloaded_reader.pages:

        downloaded_pdf_text += (
            downloaded_page.extract_text()
            or ""
        )

        downloaded_pdf_text += "\\n"


    downloaded_pdf_text_normalized = " ".join(
        downloaded_pdf_text.split()
    )


    assert downloaded_pdf_text_normalized, (
        "Downloaded PDF text is empty."
    )


    # ========================================================
    # 27. Verify Transit Number in Downloaded PDF
    # ========================================================

    downloaded_transit_found = (
        transit_pattern.search(
            downloaded_pdf_text_normalized
        )
    )


    if not downloaded_transit_found:

        fallback_transit_pattern = re.compile(
