(18608,21443,'custom','from playwright.sync_api import expect


# ============================================================
# Add 2 Products
# ============================================================

for i in range(1, 3):

    product_id = tdm_fetch(
        f"{{RTC_69.${row_number}.EnterFirstProductIDInputField{i}}}"
    )

    if (
        product_id is None
        or str(product_id).strip() == ""
        or str(product_id).strip().upper() in ["N/A", "NA", "NULL"]
        or (
            str(product_id).strip().startswith("{")
            and str(product_id).strip().endswith("}")
        )
    ):
        print(
            f"Skipping Product ID Row {i}: {product_id}"
        )
        continue

    product_id = str(product_id).strip()

    # ========================================================
    # Wait for Product ID field
    # ========================================================

    product_input = page.locator(
        "//input[@name=\'partyId\']"
    )

    expect(
        product_input
    ).to_be_visible(timeout=30000)

    # ========================================================
    # Enter Product ID
    # ========================================================

    product_input.click()
    product_input.fill(product_id)

    page.wait_for_timeout(1000)

    # ========================================================
    # Click Add
    # ========================================================

    add_button = page.locator(
        "//button[normalize-space()=\'Add\']"
    )

    expect(
        add_button
    ).to_be_visible(timeout=30000)

    expect(
        add_button
    ).to_be_enabled(timeout=30000)

    add_button.click()

    print(
        f"Added Product {i}: {product_id}"
    )

    page.wait_for_timeout(3000)


# ============================================================
# Wait for Product Grid
# ============================================================

quantity_cells = page.locator(
    "//div[@role=\'gridcell\' and @data-field=\'quantity\']"
)

expect(
    quantity_cells.first
).to_be_visible(timeout=30000)


# ============================================================
# Qty & Material Cost for 2 Products
# ============================================================

for i in range(1, 3):

    # ========================================================
    # Fetch TDM Data
    # ========================================================

    qty = tdm_fetch(
        f"{{RTC_69.${row_number}.POQtyOrderedtem{i}}}"
    )

    material_cost = tdm_fetch(
        f"{{RTC_69.${row_number}.POMaterialCostItem{i}}}"
    )


    # ========================================================
    # Qty Ordered
    # ========================================================

    if (
        qty is not None
        and str(qty).strip() != ""
        and str(qty).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        qty_cell = page.locator(
            "//div[@role=\'gridcell\' and @data-field=\'quantity\']"
        ).nth(i - 1)

        expect(
            qty_cell
        ).to_be_visible(timeout=30000)

        qty_cell.click()

        qty_input = qty_cell.locator("input")

        expect(
            qty_input
        ).to_be_visible(timeout=10000)

        qty_input.fill(
            str(qty)
        )

        page.wait_for_timeout(1000)

        page.locator(
            "//h6[contains(text(),\'New Purchase Order\')]"
        ).click(force=True)

        page.wait_for_timeout(2000)

        print(
            f"Qty updated for Product {i}: {qty}"
        )

    else:

        print(
            f"Skipping Qty Product {i}: {qty}"
        )


    # ========================================================
    # Material Cost
    # ========================================================

    if (
        material_cost is not None
        and str(material_cost).strip() != ""
        and str(material_cost).strip().upper() not in ["N/A", "NA", "NULL"]
    ):

        material_cost_cell = page.locator(
            "//div[@role=\'gridcell\' and @data-field=\'materialCost\']"
        ).nth(i - 1)

        expect(
            material_cost_cell
        ).to_be_visible(timeout=30000)

        material_cost_cell.click()

        material_cost_input = material_cost_cell.locator(
            "input"
        )

        expect(
            material_cost_input
        ).to_be_visible(timeout=10000)

        material_cost_input.fill(
            str(material_cost)
        )

        page.wait_for_timeout(1000)

        page.locator(
            "//h6[contains(text(),\'New Purchase Order\')]"
        ).click(force=True)

        page.wait_for_timeout(2000)

        print(
            f"Material Cost updated for Product {i}: {material_cost}"
        )

    else:

        print(
            f"Skipping Material Cost Product {i}: {material_cost}"
        )

    page.wait_for_timeout(3000)


# ============================================================
# Final Message
# ============================================================

print("\\n===================================")
print("2 Products added and processed successfully.")
