(18615,21451,'custom','import re
from playwright.sync_api import expect


# ================================================================
# Find Lookup Product Dialog
# ================================================================

dialog = page.get_by_role(
    "dialog"
).filter(
    has=page.get_by_role(
        "heading",
        name="Lookup Product"
    )
).first

expect(
    dialog
).to_be_visible(timeout=30000)


# ================================================================
# Find Grid
# ================================================================

grid = dialog.get_by_role(
    "grid"
).first

expect(
    grid
).to_be_visible(timeout=30000)


# ================================================================
# Wait for Rows
# ================================================================

rows = grid.locator(
    "div[role=\'row\'][data-id]"
)

expect(
    rows.first
).to_be_visible(timeout=30000)

print(
    f"Initial rows loaded: {rows.count()}"
)


# ================================================================
# Read Total Rows
# ================================================================

pagination = dialog.locator(
    "p.MuiTablePagination-displayedRows"
)

expect(
    pagination
).to_be_visible(timeout=30000
)

pagination_text = pagination.inner_text().strip()

print(
    f"Pagination Text: {pagination_text}"
)


match = re.search(
    r"of\\s+([\\d,]+)",
    pagination_text,
    re.I
)

if not match:
    raise Exception(
        "Unable to determine total row count."
    )

total_rows = int(
    match.group(1).replace(",", "")
)

print(
    f"Total Rows: {total_rows}"
)


# ================================================================
# Search Condition
#
# Stock on S/O (LBS) = 0
# AND
# Actual Yard Stock (LBS) > 1
# ================================================================

selected = False

processed_row_ids = set()

print(
    "\\nSearching for matching inventory row..."
)


# ================================================================
# Process Rows
# ================================================================

for attempt in range(total_rows + 20):

    current_rows = grid.locator(
        "div[role=\'row\'][data-id]"
    )

    current_count = current_rows.count()

    print(
        f"\\nVisible DOM rows: {current_count}"
    )


    # ============================================================
    # Process Current Visible Rows
    # ============================================================

    for index in range(current_count):

        row = current_rows.nth(index)

        row_id = None

        try:

            # ====================================================
            # Get Row ID
            # ====================================================

            row_id = row.get_attribute(
                "data-id"
            )

            if not row_id:
                continue


            # ====================================================
            # Skip Already Processed Row
            # ====================================================

            if row_id in processed_row_ids:
                continue

            processed_row_ids.add(
                row_id
            )


            # ====================================================
            # Scroll Row Into View
            # ====================================================

            row.scroll_into_view_if_needed()

            page.wait_for_timeout(100)


            # ====================================================
            # Product ID
            # ====================================================

            product_id_cell = row.locator(
                "[data-field=\'idCol\']"
            )


            # ====================================================
            # Actual Yard Stock
            # ====================================================

            actual_yard_cell = row.locator(
                "[data-field=\'actualYardStockLBS\']"
            )


            # ====================================================
            # Stock on S/O
            # ====================================================

            stock_on_so_cell = row.locator(
                "[data-field=\'stockOnSoLBS\']"
            )


            # ====================================================
            # Validate Cells Exist
            # ====================================================

            if (
                product_id_cell.count() == 0
                or actual_yard_cell.count() == 0
                or stock_on_so_cell.count() == 0
            ):

                print(
                    f"Row {row_id}: "
                    "Required cells not found."
                )

                continue


            # ====================================================
            # Read Product ID
            # ====================================================

            product_id = (
                product_id_cell
                .inner_text(timeout=3000)
                .strip()
            )


            # ====================================================
            # Read Actual Yard Stock
            # ====================================================

            actual_yard = (
                actual_yard_cell
                .inner_text(timeout=3000)
                .strip()
            )


            # ====================================================
            # Read Stock on S/O
            # ====================================================

            stock_on_so = (
                stock_on_so_cell
                .inner_text(timeout=3000)
                .strip()
            )


            print(
                f"Row {row_id} -> "
                f"Product ID: {product_id}, "
                f"Actual Yard Stock: {actual_yard}, "
                f"Stock on S/O: {stock_on_so}"
            )


            # ====================================================
            # Convert Numeric Values
            # ====================================================

            try:

                actual_yard_val = float(
                    actual_yard.replace(",", "")
                )

                stock_on_so_val = float(
                    stock_on_so.replace(",", "")
                )

            except ValueError:

                print(
                    f"Row {row_id}: "
                    "Unable to convert numeric values."
                )

                continue


            # ====================================================
            # Matching Condition
            # ====================================================

            if (
                stock_on_so_val == 0
                and actual_yard_val > 1
            ):

                print(
                    "\\n======================================"
                )

                print(
                    "MATCHING ROW FOUND"
                )

                print(
                    f"Row ID: {row_id}"
                )

                print(
                    f"Product ID: {product_id}"
                )

                print(
                    f"Stock on S/O = {stock_on_so_val}"
                )

                print(
                    f"Actual Yard Stock = {actual_yard_val}"
                )

                print(
                    "======================================"
                )


                # =================================================
                # Find Checkbox
                # =================================================

                checkbox = row.locator(
                    "input[type=\'checkbox\'][aria-label=\'Select row\']"
                ).first


                # =================================================
                # Validate Checkbox
                # =================================================

                if checkbox.count() == 0:

                    print(
                        f"Row {row_id}: "
                        "Select checkbox not found."
                    )

                    continue


                expect(
                    checkbox
                ).to_be_visible(timeout=5000)


                # =================================================
                # Select Matching Row
                # =================================================

                checkbox.scroll_into_view_if_needed()

                checkbox.click(
                    force=True
                )


                print(
                    f"Row {row_id} selected successfully."
                )


                selected = True

                break


        except Exception as e:

            print(
                f"Failed processing row "
                f"{row_id}: {e}"
            )

            continue


    # ============================================================
    # Stop Searching After Match
    # ============================================================

    if selected:
        break


    # ============================================================
    # Scroll Last Visible Row
    # ============================================================

    current_rows = grid.locator(
        "div[role=\'row\'][data-id]"
    )

    if current_rows.count() == 0:

        print(
            "No rows currently available."
        )

        break


    last_row = current_rows.last


    try:

        last_row.scroll_into_view_if_needed()

    except Exception:

        print(
            "Unable to scroll last visible row."
        )

        break


    page.wait_for_timeout(500)


# ================================================================
# Final Validation
# ================================================================

if not selected:

    raise Exception(
        "No matching row found where "
        "Stock on S/O = 0 and "
        "Actual Yard Stock > 1."
    )


# ================================================================
# Success
# ================================================================

print(
    "\\n======================================"
)

print(
    "Matching inventory row selected successfully."
)

print(
    "======================================"
)','import re
from playwright.sync_api import expect


# ================================================================
# Find Lookup Product Dialog
# ================================================================

dialog = page.get_by_role(
    "dialog"
).filter(
    has=page.get_by_role(
        "heading",
        name="Lookup Product"
    )
).first

expect(
    dialog
).to_be_visible(timeout=30000)


# ================================================================
# Find Grid
# ================================================================

grid = dialog.get_by_role(
    "grid"
).first

expect(
    grid
).to_be_visible(timeout=30000)


# ================================================================
# Wait for Rows
# ================================================================

rows = grid.locator(
    "div[role=\'row\'][data-id]"
)

expect(
    rows.first
).to_be_visible(timeout=30000)

print(
    f"Initial rows loaded: {rows.count()}"
)


# ================================================================
# Read Total Rows
# ================================================================

pagination = dialog.locator(
    "p.MuiTablePagination-displayedRows"
)

expect(
    pagination
).to_be_visible(timeout=30000
)

pagination_text = pagination.inner_text().strip()

print(
    f"Pagination Text: {pagination_text}"
)


match = re.search(
    r"of\\s+([\\d,]+)",
    pagination_text,
    re.I
)

if not match:
    raise Exception(
        "Unable to determine total row count."
    )

total_rows = int(
    match.group(1).replace(",", "")
)

print(
    f"Total Rows: {total_rows}"
)


# ================================================================
# Search Condition
#
# Stock on S/O (LBS) = 0
# AND
# Actual Yard Stock (LBS) > 1
# ================================================================

selected = False

processed_row_ids = set()

print(
    "\\nSearching for matching inventory row..."
)


# ================================================================
# Process Rows
# ================================================================

for attempt in range(total_rows + 20):

    current_rows = grid.locator(
        "div[role=\'row\'][data-id]"
    )

    current_count = current_rows.count()

    print(
        f"\\nVisible DOM rows: {current_count}"
    )


    # ============================================================
    # Process Current Visible Rows
    # ============================================================

    for index in range(current_count):

        row = current_rows.nth(index)

        row_id = None

        try:

            # ====================================================
            # Get Row ID
            # ====================================================

            row_id = row.get_attribute(
                "data-id"
            )

            if not row_id:
                continue


            # ====================================================
            # Skip Already Processed Row
            # ====================================================

            if row_id in processed_row_ids:
                continue

            processed_row_ids.add(
                row_id
            )


            # ====================================================
            # Scroll Row Into View
            # ====================================================

            row.scroll_into_view_if_needed()

            page.wait_for_timeout(100)


            # ====================================================
            # Product ID
            # ====================================================

            product_id_cell = row.locator(
                "[data-field=\'idCol\']"
            )


            # ====================================================
            # Actual Yard Stock
            # ====================================================

            actual_yard_cell = row.locator(
                "[data-field=\'actualYardStockLBS\']"
            )


            # ====================================================
            # Stock on S/O
            # ====================================================

            stock_on_so_cell = row.locator(
                "[data-field=\'stockOnSoLBS\']"
            )


            # ====================================================
            # Validate Cells Exist
            # ====================================================

            if (
                product_id_cell.count() == 0
                or actual_yard_cell.count() == 0
                or stock_on_so_cell.count() == 0
            ):

                print(
                    f"Row {row_id}: "
                    "Required cells not found."
                )

                continue


            # ====================================================
            # Read Product ID
            # ====================================================

            product_id = (
                product_id_cell
                .inner_text(timeout=3000)
                .strip()
            )


            # ====================================================
            # Read Actual Yard Stock
            # ====================================================

            actual_yard = (
                actual_yard_cell
                .inner_text(timeout=3000)
                .strip()
            )


            # ====================================================
            # Read Stock on S/O
            # ====================================================

            stock_on_so = (
                stock_on_so_cell
                .inner_text(timeout=3000)
                .strip()
            )


            print(
                f"Row {row_id} -> "
                f"Product ID: {product_id}, "
                f"Actual Yard Stock: {actual_yard}, "
                f"Stock on S/O: {stock_on_so}"
            )


            # ====================================================
            # Convert Numeric Values
            # ====================================================

            try:

                actual_yard_val = float(
                    actual_yard.replace(",", "")
                )

                stock_on_so_val = float(
                    stock_on_so.replace(",", "")
                )

            except ValueError:

                print(
                    f"Row {row_id}: "
                    "Unable to convert numeric values."
                )

                continue


            # ====================================================
            # Matching Condition
            # ====================================================

            if (
                stock_on_so_val == 0
                and actual_yard_val > 1
            ):

                print(
                    "\\n======================================"
                )

                print(
                    "MATCHING ROW FOUND"
                )

                print(
                    f"Row ID: {row_id}"
                )

                print(
                    f"Product ID: {product_id}"
                )

                print(
                    f"Stock on S/O = {stock_on_so_val}"
                )

                print(
                    f"Actual Yard Stock = {actual_yard_val}"
                )

                print(
                    "======================================"
                )


                # =================================================
                # Find Checkbox
                # =================================================

                checkbox = row.locator(
                    "input[type=\'checkbox\'][aria-label=\'Select row\']"
                ).first


                # =================================================
                # Validate Checkbox
                # =================================================

                if checkbox.count() == 0:

                    print(
                        f"Row {row_id}: "
                        "Select checkbox not found."
                    )

                    continue


                expect(
                    checkbox
                ).to_be_visible(timeout=5000)


                # =================================================
                # Select Matching Row
                # =================================================

                checkbox.scroll_into_view_if_needed()

                checkbox.click(
                    force=True
                )


                print(
                    f"Row {row_id} selected successfully."
                )


                selected = True

                break


        except Exception as e:

            print(
                f"Failed processing row "
                f"{row_id}: {e}"
            )

            continue


    # ============================================================
    # Stop Searching After Match
    # ============================================================

    if selected:
        break


    # ============================================================
    # Scroll Last Visible Row
    # ============================================================

    current_rows = grid.locator(
        "div[role=\'row\'][data-id]"
    )

    if current_rows.count() == 0:

        print(
            "No rows currently available."
        )

        break


    last_row = current_rows.last


    try:

        last_row.scroll_into_view_if_needed()

    except Exception:

        print(
            "Unable to scroll last visible row."
        )

        break


    page.wait_for_timeout(500)


# ================================================================
# Final Validation
# ================================================================

if not selected:

    raise Exception(
        "No matching row found where "
        "Stock on S/O = 0 and "
        "Actual Yard Stock > 1."
    )


# ================================================================
# Success
# ================================================================

print(
    "\\n======================================"
)

print(
    "Matching inventory row selected successfully."
)

print(
    "======================================"
)','passed','2026-08-22 05:14:02','2026-09-06 01:55:34','Initial rows loaded: 20
