# --------------------------------------------------

filename = download.suggested_filename

print("Filename:", filename)

# --------------------------------------------------
# Download Location
# --------------------------------------------------

download_dir = "/tmp/downloads"
os.makedirs(download_dir, exist_ok=True)

file_path = os.path.join(
    download_dir,
    filename
)

download.save_as(file_path)

print("Saved file:", file_path)

# --------------------------------------------------
# Verify File Exists
# --------------------------------------------------

assert os.path.exists(file_path), (
    f"Downloaded file was not saved: {file_path}"
)

assert os.path.getsize(file_path) > 0, (
    f"Downloaded file is empty: {file_path}"
)

# --------------------------------------------------
# Verify CSV File
# --------------------------------------------------

assert filename.lower().endswith(".csv"), (
    f"Expected CSV file, but downloaded: {filename}"
)

print(f"{filename} downloaded successfully.")

# --------------------------------------------------
# Get UI Pagination Total Row Count
#
# There can be multiple pagination elements on the page.
# Do NOT use the locator directly because strict mode
# will fail if more than one element is found.
# --------------------------------------------------

pagination = page.locator(
    ".MuiTablePagination-displayedRows"
)

pagination_count = pagination.count()

assert pagination_count > 0, (
    "No pagination elements found on the page."
)

print(
    "Pagination elements found:",
    pagination_count
)

# --------------------------------------------------
# Find the Order Search pagination
#
# The page currently has:
#   1–1 of 1
#   1–4 of 4
#
# Select the pagination containing the Order Search
# result count. Here we use the last visible pagination.
# --------------------------------------------------

visible_paginations = []

for i in range(pagination_count):
    candidate = pagination.nth(i)

    if candidate.is_visible():
        visible_paginations.append(candidate)

assert len(visible_paginations) > 0, (
    "No visible pagination elements found."
)

# Use the last visible pagination element.
# This avoids Playwright strict-mode violation.
pagination = visible_paginations[-1]

expect(pagination).to_be_visible()

pagination_text = pagination.inner_text().strip()

print("UI Pagination:", pagination_text)

# --------------------------------------------------
# Extract Total Rows From Pagination
# Example:
#   1–106 of 106
# --------------------------------------------------

pagination_match = re.search(
    r"\\d+\\s*[–-]\\s*\\d+\\s+of\\s+(\\d+)",
    pagination_text
)

assert pagination_match is not None, (
    f"Unable to extract total row count from pagination: "
    f"{pagination_text}"
)

ui_total_rows = int(
    pagination_match.group(1)
)

print(
    "Total rows displayed in UI:",
    ui_total_rows
)

# --------------------------------------------------
# Read Order Search CSV
# --------------------------------------------------

with open(
    file_path,
    mode="r",
    encoding="utf-8-sig",
    newline=""
) as file:

    reader = csv.reader(file)
    rows = list(reader)

assert len(rows) > 0, (
    f"{filename} does not contain any data."
)

# --------------------------------------------------
# Validate CSV Row Count
#
# Assumes the first row is the CSV header.
# --------------------------------------------------

csv_data_rows = len(rows) - 1

print(
    "CSV data rows:",
    csv_data_rows
)

print(
    "UI total rows:",
    ui_total_rows
)

assert csv_data_rows == ui_total_rows, (
    f"CSV/UI row count mismatch. "
    f"UI: {ui_total_rows}, "
    f"CSV: {csv_data_rows}"
)

print(
    "SUCCESS: CSV row count matches UI row count."
)

# --------------------------------------------------
# Delete Order Search CSV After Verification
# --------------------------------------------------

assert os.path.exists(file_path), (
    f"{filename} does not exist: {file_path}"
)

os.remove(file_path)

assert not os.path.exists(file_path), (
    f"{filename} was not deleted: {file_path}"
)

print(
    f"SUCCESS: {filename} was deleted after verification."
