# ============================================================
# 18. VALIDATE ITEM #2 PCE QUANTITY
# ============================================================
#
# IMPORTANT:
#
# We ONLY validate:
#
#     UI Qty Ordered = 2.00
#
# against:
#
#     PDF Item #2 PCE = 2
#
# We DO NOT validate:
#
#     Length
#     Unit
#     Weight
#     Product Description
#     Other PDF fields
#
# In the PDF, the Item #2 row is structured like:
#
#     2    80.00    PI    8,080    ...    2
#     ^
#     |
#     PCE quantity
#
# The final 2 is the Item #.
#
# Therefore the validation checks that Item #2\'s row starts
# with the UI Qty Ordered value.
# ============================================================

print(
    "\\n============================================================"
)

print(
    "VALIDATING ITEM #2 PCE QUANTITY"
)

print(
    "============================================================"
)


print(
    "UI Qty Ordered:",
    ui_quantity_raw
)

print(
    "Normalized UI Qty Ordered:",
    expected_pdf_pce_quantity
)

print(
    "Expected PDF PCE Quantity:",
    expected_pdf_pce_quantity
)


# ------------------------------------------------------------
# Find Item #2 PDF row.
#
# The BOL table row starts with the PCE quantity and ends
# with Item #2.
#
# We intentionally do NOT compare the other columns.
# ------------------------------------------------------------

expected_pce_pattern = re.escape(
    expected_pdf_pce_quantity
)


item2_pdf_row_pattern = re.compile(

    r"(?:^|\\s)"

    # PCE quantity at beginning of row
    + expected_pce_pattern

    + r"(?:\\.0+)?"

    # Everything else in the Item #2 row is ignored.
    + r"\\s+"

    + r".*?"

    # Item #2 at the end of the row.
    + r"\\s+2"

    + r"(?:\\s|$)",

    re.IGNORECASE
)


item2_pdf_match = (
    item2_pdf_row_pattern.search(
        pdf_text_normalized
    )
)


# ============================================================
# 19. FALLBACK ITEM #2 PCE VALIDATION
# ============================================================
#
# PDF text extraction can sometimes place the table contents
# on separate lines.
#
# If the full-row regex does not match, we use a simpler
# validation based on the PDF table structure:
#
#     <PCE quantity> ... <Item # 2>
#
# Again, no other field is compared.
# ============================================================

if item2_pdf_match:

    matched_pdf_row = (
        item2_pdf_match.group(0).strip()
    )

    print(
        "\\nItem #2 PDF row located successfully."
    )

    print(
        "Matched PDF row:"
    )

    print(
        matched_pdf_row
    )

else:

    print(
        "\\nFull Item #2 row pattern did not match."
    )

    print(
        "Attempting fallback PCE quantity validation..."
    )


    # --------------------------------------------------------
    # Find occurrences of Item #2.
    # --------------------------------------------------------

    item2_occurrences = list(
        re.finditer(
            r"(?:^|\\s)2(?:\\s|$)",
            pdf_text_normalized
        )
    )


    assert item2_occurrences, (

        "\\nItem #2 was not found in BOL PDF.\\n\\n"

        f"Expected PDF PCE quantity: "
        f"{expected_pdf_pce_quantity}\\n\\n"

        f"PDF URL:\\n"
        f"{pdf_url}\\n\\n"

        f"PDF Text:\\n"
        f"{pdf_text_normalized}"
    )


    pce_quantity_found = False


    # --------------------------------------------------------
    # Inspect text around Item #2 occurrences.
    #
    # We only care whether the expected PCE quantity appears
    # before Item #2 in the same extracted row/region.
    # --------------------------------------------------------

    for occurrence in item2_occurrences:

        start_position = (
            occurrence.start()
        )

        # Look backward for a reasonable table-row boundary.
        previous_newline = (
            pdf_text_normalized.rfind(
                "\\n",
                0,
                start_position
            )
        )

        if previous_newline == -1:

            row_start = 0

        else:

            row_start = (
                previous_newline + 1
            )


        row_text = (
            pdf_text_normalized[
                row_start:
                occurrence.end()
            ]
        )


        print(
            "\\nCandidate Item #2 PDF text:"
        )

        print(
            row_text
        )


        # ----------------------------------------------------
        # The first meaningful numeric token in the row must
        # equal the UI Qty Ordered.
        # ----------------------------------------------------

        first_number_match = re.search(
            r"(?<![\\w.])\\d+(?:\\.\\d+)?",
            row_text
        )


        if not first_number_match:

            continue


        first_pdf_number = normalize_number(
            first_number_match.group(0)
        )


        print(
            "First numeric value in candidate row:",
            first_pdf_number
        )


        if (
            first_pdf_number
            == expected_pdf_pce_quantity
        ):

            pce_quantity_found = True

            print(
                "Expected PCE quantity found "
                "for Item #2."
            )

            break


    assert pce_quantity_found, (

        "\\nItem #2 PCE quantity mismatch.\\n\\n"

        f"UI Qty Ordered: "
        f"{ui_quantity_numeric}\\n"

        f"Expected PDF PCE quantity: "
        f"{expected_pdf_pce_quantity}\\n\\n"

        "The expected quantity was not found "
        "as the PCE quantity for Item #2.\\n\\n"

        f"PDF URL:\\n"
        f"{pdf_url}\\n\\n"

        f"PDF Text:\\n"
        f"{pdf_text_normalized}"
    )


# ============================================================
# 20. FINAL UI/PDF QUANTITY COMPARISON
# ============================================================

pdf_pce_quantity = (
    expected_pdf_pce_quantity
)


print(
    "\\n============================================================"
)

print(
    "UI / PDF PCE QUANTITY COMPARISON"
)

print(
    "============================================================"
)

print(
    "UI Qty Ordered:",
    ui_quantity_numeric
)

print(
    "PDF PCE Quantity:",
    pdf_pce_quantity
)


assert (
    float(ui_quantity_numeric)
    == float(pdf_pce_quantity)
), (

    "\\nQty Ordered / PCE quantity mismatch.\\n"

    f"UI Qty Ordered: "
    f"{ui_quantity_numeric}\\n"

    f"PDF PCE Quantity: "
    f"{pdf_pce_quantity}"
)


print(
    "\\nUI/PDF PCE quantity comparison PASSED."
)


# ============================================================
# 21. VERIFY SAVED PDF
# ============================================================

with open(
    downloaded_pdf_path,
    "rb"
) as downloaded_pdf_file:

    downloaded_pdf_bytes = (
        downloaded_pdf_file.read()
    )


assert downloaded_pdf_bytes.startswith(
    b"%PDF"
), (
    "Saved PDF is not valid."
)


assert (
    downloaded_pdf_bytes
    == pdf_bytes
), (
    "Saved PDF bytes do not match "
    "the browser PDF response."
)


print(
    "Saved PDF bytes verification PASSED."
)


# ============================================================
# 22. RE-OPEN SAVED PDF
# ============================================================

downloaded_reader = PdfReader(
    BytesIO(
        downloaded_pdf_bytes
    )
)


assert len(
    downloaded_reader.pages
) > 0, (
    "Saved PDF contains no pages."
)


downloaded_pdf_text = ""


for downloaded_page in downloaded_reader.pages:

    downloaded_pdf_text += (
        downloaded_page.extract_text()
        or ""
    )

    downloaded_pdf_text += "\\n"


downloaded_pdf_text_normalized = (
    normalize_text(
        downloaded_pdf_text
    )
)


assert downloaded_pdf_text_normalized, (
    "Downloaded PDF text is empty."
)


# ============================================================
# 23. VERIFY PCE QUANTITY AGAINST SAVED PDF
# ============================================================
#
# We repeat only the PCE quantity validation on the actual
# saved PDF. No other fields are checked.
# ============================================================

saved_pdf_item2_pattern = re.compile(

    r"(?:^|\\s)"

    + re.escape(
        expected_pdf_pce_quantity
    )

    + r"(?:\\.0+)?"

    + r"\\s+"

    + r".*?"

    + r"\\s+2"

    + r"(?:\\s|$)",

    re.IGNORECASE
)


saved_pdf_item2_match = (
    saved_pdf_item2_pattern.search(
        downloaded_pdf_text_normalized
    )
)


if saved_pdf_item2_match:

    print(
        "\\nSaved PDF Item #2 PCE quantity found."
    )

    print(
        "Saved PDF matched text:"
    )

    print(
        saved_pdf_item2_match.group(0).strip()
    )

else:

    # --------------------------------------------------------
    # Fallback: verify expected PCE quantity exists in the
    # saved PDF text before Item #2.
    # --------------------------------------------------------

    saved_pdf_item2_occurrences = list(
        re.finditer(
            r"(?:^|\\s)2(?:\\s|$)",
            downloaded_pdf_text_normalized
        )
    )


    saved_pdf_pce_quantity_found = False


    for occurrence in saved_pdf_item2_occurrences:

        start_position = (
            occurrence.start()
        )


        previous_newline = (
            downloaded_pdf_text_normalized.rfind(
                "\\n",
                0,
                start_position
            )
        )


        if previous_newline == -1:

            row_start = 0

        else:

            row_start = (
                previous_newline + 1
            )


        row_text = (
            downloaded_pdf_text_normalized[
                row_start:
                occurrence.end()
            ]
        )


        first_number_match = re.search(
            r"(?<![\\w.])\\d+(?:\\.\\d+)?",
            row_text
        )


        if not first_number_match:

            continue


        first_pdf_number = normalize_number(
            first_number_match.group(0)
        )


        if (
            first_pdf_number
            == expected_pdf_pce_quantity
        ):

            saved_pdf_pce_quantity_found = True

            break


    assert saved_pdf_pce_quantity_found, (

        "\\nSaved PDF Item #2 PCE quantity "
        "verification failed.\\n\\n"

        f"Expected PCE quantity: "
        f"{expected_pdf_pce_quantity}\\n\\n"

        f"Saved PDF text:\\n"
        f"{downloaded_pdf_text_normalized}"
    )


print(
    "Saved PDF Item #2 PCE quantity verification PASSED."
)


# ============================================================
# 24. FINAL VALIDATION
# ============================================================

print(
    "\\n============================================================"
)

print(
    "PRINT BOL PCE QUANTITY VALIDATION PASSED"
)

print(
    "============================================================"
)

print(
    "Item #2 row                      : PASS"
)

