(19035,19366,'custom','from playwright.sync_api import expect
from pypdf import PdfReader
from io import BytesIO
import os
import re
import unicodedata


# ============================================================
# VARIABLES
# ============================================================

downloaded_pdf_path = None


# ============================================================
# HELPER FUNCTIONS
# ============================================================

def normalize_text(value):
    """
    Normalize text for PDF/UI comparison.

    Handles:
    - whitespace
    - accents
    - non-breaking spaces
    - dash characters
    - case
    """

    if value is None:
        return ""

    value = str(value)

    # Replace non-breaking spaces
    value = value.replace("\\xa0", " ")

    # Normalize unicode
    value = unicodedata.normalize(
        "NFKD",
        value
    )

    # Remove combining accent characters
    value = "".join(
        ch
        for ch in value
        if not unicodedata.combining(ch)
    )

    # Normalize common dash characters
    value = value.replace("–", "-")
    value = value.replace("—", "-")
    value = value.replace("−", "-")

    # Normalize whitespace
    value = " ".join(
        value.split()
    )

    return value.strip().lower()


# ============================================================
# HELPER - CLEAN UI FIELD VALUE
# ============================================================

def clean_ui_value(value):
    """
    Clean a UI field value without changing its actual content.
    """

    if value is None:
        return ""

    return " ".join(
        str(value).split()
    ).strip()


# ============================================================
# HELPER - CAPTURE CUSTOMER PO
# ============================================================

def capture_customer_po():
    """
    Capture Customer PO from the Edit Order UI.

    The Customer PO field has previously appeared as:

        input[name=\'customerPO\']

    We intentionally use the first matching field, matching
    the proven approach used by the working Edit Shipment code.

    Because this field can be React-controlled, several DOM
    properties are checked if input_value() is empty.
    """

    print(
        "\\n============================================================"
    )

    print(
        "CAPTURING CUSTOMER PO FROM EDIT ORDER"
    )

    print(
        "============================================================"
    )

    print(
        "\\nLocating Customer PO input..."
    )

    customer_po_locator = page.locator(
        "input[name=\'customerPO\']"
    ).first

    # --------------------------------------------------------
    # Wait for the actual input to exist.
    # --------------------------------------------------------

    expect(
        customer_po_locator
    ).to_be_attached(
        timeout=10000
    )

    expect(
        customer_po_locator
    ).to_be_visible(
        timeout=10000
    )

    print(
        "Customer PO input is visible."
    )

    # --------------------------------------------------------
    # Print basic DOM information for troubleshooting.
    # --------------------------------------------------------

    try:

        customer_po_count = page.locator(
            "input[name=\'customerPO\']"
        ).count()

        print(
            "Customer PO matching input count:",
            customer_po_count
        )

    except Exception:

        pass

    # --------------------------------------------------------
    # IMPORTANT:
    #
    # Use input_value() first.
    # This is the same proven method used by the working
    # Shipping Instructions code.
    # --------------------------------------------------------

    try:

        ui_customer_po = (
            customer_po_locator.input_value(
                timeout=10000
            )
        )

        ui_customer_po = clean_ui_value(
            ui_customer_po
        )

        print(
            "Customer PO input_value():",
            repr(ui_customer_po)
        )

        if ui_customer_po:

            print(
                "Customer PO captured successfully "
                "through input_value()."
            )

            return ui_customer_po

    except Exception as e:

        print(
            "Customer PO input_value() failed:",
            e
        )

    # ========================================================
    # FALLBACK 1 - LIVE DOM VALUE PROPERTY
    # ========================================================

    print(
        "\\nCustomer PO input_value() returned empty."
    )

    print(
        "Trying live DOM value property..."
    )

    try:

        dom_value = customer_po_locator.evaluate(
            """
            el => ({
                value: el.value || \'\',
                defaultValue: el.defaultValue || \'\',
                textContent: el.textContent || \'\',
                innerText: el.innerText || \'\',
                placeholder: el.getAttribute(\'placeholder\') || \'\',
                ariaLabel: el.getAttribute(\'aria-label\') || \'\',
                ariaValueText: el.getAttribute(\'aria-valuetext\') || \'\',
                dataValue: el.getAttribute(\'data-value\') || \'\'
            })
            """
        )

        print(
            "Customer PO DOM information:",
            dom_value
        )

        # ----------------------------------------------------
        # Check the actual live value first.
        # ----------------------------------------------------

        candidate_values = [
            (
                "DOM value",
                dom_value.get("value")
            ),
            (
                "defaultValue",
                dom_value.get("defaultValue")
            ),
            (
                "data-value",
                dom_value.get("dataValue")
            ),
            (
                "aria-valuetext",
                dom_value.get("ariaValueText")
            ),
        ]

        for source_name, candidate_value in candidate_values:

            candidate_value = clean_ui_value(
                candidate_value
            )

            print(
                f"Customer PO {source_name}:",
                repr(candidate_value)
            )

            if candidate_value:

                print(
                    "Customer PO captured successfully "
                    f"through {source_name}."
                )

                return candidate_value

    except Exception as e:

        print(
            "Customer PO DOM fallback failed:",
            e
        )

    # ========================================================
    # FALLBACK 2 - PAGE DOM SEARCH
    # ========================================================
    #
    # Search visible elements associated with customerPO.
    #
    # This does NOT invent a value. It only reads values
    # already present in the DOM.
    # ========================================================

    print(
        "\\nTrying page-level Customer PO DOM search..."
    )

    try:

        customer_po_dom_values = page.locator(
            """
            input[name=\'customerPO\'],
            textarea[name=\'customerPO\'],
            [name=\'customerPO\'],
            [data-testid*=\'customerPO\' i],
            [id*=\'customerPO\' i]
            """
        ).evaluate_all(
            """
            elements => elements.map(el => ({
                tag: el.tagName,
                value: el.value || \'\',
                defaultValue: el.defaultValue || \'\',
                textContent: el.textContent || \'\',
                visible: (() => {
                    const style = window.getComputedStyle(el);
                    const rect = el.getBoundingClientRect();

                    return (
                        style.display !== \'none\' &&
                        style.visibility !== \'hidden\' &&
                        rect.width > 0 &&
                        rect.height > 0
                    );
                })()
            }))
            """
        )

        print(
            "Customer PO page-level DOM candidates:",
            customer_po_dom_values
        )

        for candidate in customer_po_dom_values:

            if not candidate.get("visible"):

                continue

            possible_values = [
                candidate.get("value"),
                candidate.get("defaultValue"),
                candidate.get("textContent")
            ]

            for candidate_value in possible_values:

                candidate_value = clean_ui_value(
                    candidate_value
                )

                if candidate_value:

                    print(
                        "Customer PO captured from "
                        "page-level DOM:",
                        candidate_value
                    )

                    return candidate_value

    except Exception as e:

        print(
            "Page-level Customer PO DOM search failed:",
            e
        )

    # ========================================================
    # FINAL DIAGNOSTIC
    # ========================================================

    try:

        customer_po_outer_html = (
            customer_po_locator.evaluate(
                "el => el.outerHTML"
            )
        )

        print(
            "\\nCustomer PO input outerHTML:"
        )

        print(
            customer_po_outer_html
        )

    except Exception as e:

        print(
            "Unable to read Customer PO outerHTML:",
            e
        )

    raise AssertionError(
        "\\nCustomer PO value is empty in Edit Order UI.\\n\\n"

        "Locator:\\n"
        "input[name=\'customerPO\']\\n\\n"

        "input_value(), DOM value, defaultValue, "
        "data-value and aria-valuetext were all empty.\\n\\n"

        "This means the Customer PO value is not currently "
        "available in the matched input\'s DOM."
    )


# ============================================================
# HELPER - CAPTURE STANDARD INPUT FIELD
# ============================================================

def capture_input_field(
    locator,
    field_name,
    locator_description,
    timeout=10000
):
    """
    Capture a standard input field using the same proven
    approach as the working Edit Shipment code.
    """

    print(
        f"\\nLocating {field_name}..."
    )

    expect(
        locator
    ).to_be_visible(
        timeout=timeout
    )

    print(
        f"{field_name} input is visible."
    )

    try:

        value = locator.input_value(
            timeout=timeout
        )

    except Exception as e:

        raise AssertionError(
            f"\\nUnable to capture {field_name} "
            "from Edit Order.\\n\\n"
            f"Locator: {locator_description}\\n\\n"
            f"Error: {e}"
        )

    value = clean_ui_value(
        value
    )

    assert value, (

        f"\\n{field_name} value is empty "
        "in Edit Order UI.\\n\\n"

        f"Locator:\\n"
        f"{locator_description}"
    )

    print(
        f"{field_name} from Edit Order:",
        value
    )

    return value


