def is_order_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        # Avoid accidentally capturing BOL PDF.
        is_not_bol_pdf = (
            "/api/scadmin/control/shipment.pdf"
            not in response_url
        )

        return (
            is_pdf_content
            and is_not_bol_pdf
        )

    except Exception:

        return False


