# ============================================================
# 6. ORDER PDF RESPONSE PREDICATE
# ============================================================

def is_order_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        # Avoid accidentally capturing the BOL PDF endpoint
        # if another PDF request is present.
        is_not_bol_pdf = (
            "/api/scadmin/control/shipment.pdf"
            not in response_url
        )

        return (
            is_pdf_content
            and is_not_bol_pdf
        )

    except Exception:

        return False


