(19043,19368,'custom','import os
import re
import unicodedata
from pathlib import Path

from pypdf import PdfReader


# ============================================================
# HELPERS
# ============================================================

def normalize_text(text: str) -> str:
    """
    Normalize PDF text for reliable comparisons:
    - lowercase
    - remove accents
    - normalize whitespace
    """
    text = text or ""

    # Remove accents
    text = unicodedata.normalize("NFD", text)
    text = "".join(
        char for char in text
        if unicodedata.category(char) != "Mn"
    )

    # Lowercase
    text = text.lower()

    # Normalize whitespace
    text = re.sub(r"\\s+", " ", text)

    return text.strip()


def extract_pdf_text(pdf_path: str) -> str:
    """
    Extract text from all pages of the downloaded BOL PDF.
    """
    reader = PdfReader(pdf_path)

    pages = []

    for page in reader.pages:
        page_text = page.extract_text() or ""
        pages.append(page_text)

    return "\\n".join(pages)


# ============================================================
# MAIN BOL VALIDATION
# ============================================================

def validate_bol_pdf(page):
    """
    Complete BOL flow:

    1. Locate Print button
    2. Click Print
    3. Click Print BOL
    4. Verify BOL opens in a new tab
    5. Capture BOL PDF response
    6. Download PDF
    7. Verify PDF signature/content type/status
    8. Extract PDF text
    9. Validate:
       - Customer PO -> BON DE TRAVAIL # -> PO12345
       - Project Name -> NOM DE PROJET -> Project1
       - Shipping Instructions -> INSTRUCTIONS SPÉCIALES
         -> Test shipping instruction
    """

    context = page.context

    # ========================================================
    # EXPECTED VALUES
    # ========================================================

    expected_customer_po = "PO12345"
    expected_project_name = "Project1"
    expected_shipping_instructions = "Test shipping instruction"

    # Download location
    download_dir = Path("/tmp/downloads")
    download_dir.mkdir(parents=True, exist_ok=True)

    bol_pdf_path = download_dir / "BOL_PDF.pdf"

    # Remove old PDF if it exists
    if bol_pdf_path.exists():
        bol_pdf_path.unlink()

    # ========================================================
    # LOCATING PRINT BUTTON
    # ========================================================

    print("\\n" + "=" * 60)
    print("LOCATING PRINT BUTTON")
    print("=" * 60)

    print_button = page.get_by_role("button", name=re.compile(r"^Print$", re.I))

    if not print_button.is_visible():
        raise AssertionError("Print button is not visible.")

    if not print_button.is_enabled():
        raise AssertionError("Print button is disabled.")

    print("Print button is visible and enabled.")

    tabs_before_print = len(context.pages)

    print(f"Tabs before clicking Print: {tabs_before_print}")

    # ========================================================
    # OPENING PRINT MENU
    # ========================================================

    print("\\n" + "=" * 60)
    print("OPENING PRINT MENU")
    print("=" * 60)

    # Verify menu is initially closed if possible
    print_bol_menu_item = page.get_by_text(
        "Print BOL",
        exact=True
    )

    if print_bol_menu_item.is_visible():
        print("Print menu is already open.")
    else:
        print("Print menu is closed. Clicking Print button once...")

        print_button.click()

        print("Print button clicked successfully.")

        # Wait for Print BOL option
        print_bol_menu_item.wait_for(
            state="visible",
            timeout=10000
        )

        print("Print menu opened successfully.")

    # ========================================================
    # CLICK PRINT BOL
    # ========================================================

    print("\\n" + "=" * 60)
    print("CLICKING PRINT BOL")
    print("=" * 60)

    if not print_bol_menu_item.is_visible():
        raise AssertionError(
            "Print BOL menu item is not visible."
        )

    print("Print BOL menu item is visible and ready.")

    # We expect:
    # 1. a new browser tab/page
    # 2. a PDF HTTP response
    #
    # Both are captured at the same time.

    tabs_before_print_bol = len(context.pages)

    with context.expect_page(timeout=15000) as new_page_info:
        with page.expect_response(
            lambda response: (
                "shipment.pdf" in response.url.lower()
                and response.request.method == "GET"
            ),
            timeout=15000
        ) as bol_response_info:

            print_bol_menu_item.click()

    # ========================================================
    # NEW BOL PDF TAB
    # ========================================================

    bol_page = new_page_info.value
    bol_response = bol_response_info.value

    print("Print BOL clicked successfully.")

    # Make sure new tab is ready
    try:
        bol_page.wait_for_load_state(
            "domcontentloaded",
            timeout=15000
        )
    except Exception:
        # PDF viewer pages may not expose normal DOM load states.
        pass

    tabs_after_print_bol = len(context.pages)

    print("New BOL PDF tab detected.")

    print(
        f"Tabs before clicking Print BOL: "
        f"{tabs_before_print_bol}"
    )

    print(
        f"Tabs after clicking Print BOL: "
        f"{tabs_after_print_bol}"
    )

    if tabs_after_print_bol <= tabs_before_print_bol:
        raise AssertionError(
            "BOL PDF did not open in a new tab."
        )

    bol_pdf_url = bol_response.url

    print(f"BOL PDF tab URL: {bol_pdf_url}")

    # ========================================================
    # VERIFY BOL PDF RESPONSE
    # ========================================================

    print("\\n" + "=" * 60)
    print("BOL PDF RESPONSE")
