        )

    print(
        "BOL PDF HTTP Status verification PASSED."
    )

    if "application/pdf" not in content_type:
        raise AssertionError(
            "BOL PDF Content-Type verification FAILED. "
            f"Expected application/pdf, got {content_type}"
        )

    print(
        "BOL PDF Content-Type verification PASSED."
    )

    # ========================================================
    # DOWNLOAD BOL PDF
    # ========================================================

    print("\\n" + "=" * 60)
    print("DOWNLOADING BOL PDF")
    print("=" * 60)

    pdf_body = bol_response.body()

    if not pdf_body:
