    print("=" * 60)

    bol_pdf_text = extract_pdf_text(
        str(bol_pdf_path)
    )

    if not bol_pdf_text.strip():
        raise AssertionError(
            "No text could be extracted from the BOL PDF."
        )

    print(bol_pdf_text)

    # Normalize only for validation.
    normalized_bol_text = normalize_text(
