    )

    print("\\n" + "=" * 60)
    print("NORMALIZED BOL PDF TEXT")
    print("=" * 60)

    print(normalized_bol_text)

    # ========================================================
    # VALIDATING CUSTOMER PO
    #
    # IMPORTANT:
    # Customer PO is validated against:
    #
    # BON DE TRAVAIL #
    # PO12345
    #
    # NOT:
    #
    # # de Commande P&P
    # MTL15974
    # ========================================================

    print("\\n" + "=" * 60)
    print("VALIDATING CUSTOMER PO ON BOL PDF")
    print("=" * 60)

    normalized_customer_po = normalize_text(
        expected_customer_po
    )

    customer_po_pattern = (
        r"bon\\s+de\\s+travail\\s*#\\s*"
        + re.escape(normalized_customer_po)
    )

    customer_po_match = re.search(
        customer_po_pattern,
        normalized_bol_text,
        re.IGNORECASE
    )

    if not customer_po_match:
        raise AssertionError(
            "Customer PO was not found on the BOL PDF "
            "under BON DE TRAVAIL #.\\n"
            f"Expected Customer PO: {expected_customer_po}\\n"
            f"Expected field: BON DE TRAVAIL #\\n"
            f"BOL PDF URL: {bol_pdf_url}\\n"
            f"BOL PDF Text: {normalized_bol_text}"
        )

    print(
        "Customer PO verification PASSED."
    )

    print(
        "Customer PO found under BON DE TRAVAIL #: "
        f"{expected_customer_po}"
    )

    # ========================================================
    # VALIDATING PROJECT NAME
    #
    # NOM DE PROJET
    # Project1
    # ========================================================

    print("\\n" + "=" * 60)
    print("VALIDATING PROJECT NAME ON BOL PDF")
    print("=" * 60)

    normalized_project_name = normalize_text(
        expected_project_name
    )

    project_pattern = (
        r"nom\\s+de\\s+projet\\s*"
        + re.escape(normalized_project_name)
    )

    project_match = re.search(
        project_pattern,
        normalized_bol_text,
        re.IGNORECASE
    )

    if not project_match:
        raise AssertionError(
            "Project Name was not found on the BOL PDF.\\n"
            f"Expected Project Name: {expected_project_name}\\n"
            f"Expected field: NOM DE PROJET\\n"
            f"BOL PDF URL: {bol_pdf_url}\\n"
            f"BOL PDF Text: {normalized_bol_text}"
        )

    print(
        "Project Name verification PASSED."
    )

    print(
        f"Project Name found on BOL: "
        f"{expected_project_name}"
    )

    # ========================================================
    # VALIDATING SHIPPING INSTRUCTIONS
    #
    # INSTRUCTIONS SPÉCIALES
    # Test shipping instruction
    #
    # Accent/spacing differences are handled by normalization.
    # ========================================================

    print("\\n" + "=" * 60)
    print("VALIDATING SHIPPING INSTRUCTIONS ON BOL PDF")
    print("=" * 60)

    normalized_shipping_instructions = normalize_text(
