# ============================================================
# 7. BOL PDF RESPONSE PREDICATE
# ============================================================

def is_bol_pdf_response(response):

    try:

        response_url = response.url

        content_type = (
            response.headers.get(
                "content-type",
                ""
            ).lower()
        )

        is_pdf_content = (
            "application/pdf"
            in content_type
        )

        # ----------------------------------------------------
        # IMPORTANT:
        #
        # BOL PDF is expected to come from shipment.pdf.
        # This is intentionally the OPPOSITE of the
        # Order PDF predicate.
        # ----------------------------------------------------

        is_bol_endpoint = (
            "/api/scadmin/control/shipment.pdf"
            in response_url
        )

        return (
            is_pdf_content
            and is_bol_endpoint
        )

    except Exception:

        return False


