# ------------------------------------------------------------

item2_row = page.locator(
    "//div[@data-id=\'2\' and @data-rowindex=\'1\']"
).first


expect(
    item2_row
).to_be_visible(
    timeout=10000
)


# ------------------------------------------------------------
# VERIFY ITEM #2 ROW
# ------------------------------------------------------------

item2_row_text = item2_row.inner_text()


print(
    "\\nItem #2 row text from UI:"
)

print(
    item2_row_text
)


# Verify row belongs to Item #2
item_number_cell = item2_row.locator(
    "div[data-field=\'orderItemSeqIdIndex\']"
).first


expect(
    item_number_cell
).to_be_visible(
    timeout=10000
)


ui_item_number = (
    item_number_cell.inner_text()
    .strip()
)


assert ui_item_number == "2", (
    "\\nIncorrect UI row located.\\n"
    f"Expected Item #: 2\\n"
    f"Actual Item #: {ui_item_number}\\n"
    f"Row text:\\n{item2_row_text}"
)


print(
