(19205,22034,'custom','import re
from playwright.sync_api import expect

# Scope inside dialog
dialog = page.locator("div[role=\'dialog\']")

# Wait for grid initial load
dialog.locator("div[role=\'row\'][data-id]").first.wait_for()

# -------------------------------------------------------------------
# STEP 1: Read total row count from pagination
# -------------------------------------------------------------------

pagination_text = dialog.locator(
    "p.MuiTablePagination-displayedRows"
).inner_text().strip()

print("Pagination Text:", pagination_text)

match = re.search(r"of\\s+(\\d+)", pagination_text)

if not match:
    raise Exception("Unable to determine total row count")

total_rows = int(match.group(1))

print("Total Rows:", total_rows)

# -------------------------------------------------------------------
# STEP 2: Iterate through rows
# -------------------------------------------------------------------

selected = False

for row_index in range(total_rows):

    print(f"\\nProcessing Row Index: {row_index}")

    row_locator = dialog.locator(
        f"div[role=\'row\'][data-rowindex=\'{row_index}\']"
    )

    # ---------------------------------------------------------------
    # If row is not currently in DOM, scroll grid
    # ---------------------------------------------------------------

    retry = 0

    while row_locator.count() == 0 and retry < 15:

        print(
            f"Row {row_index} not in DOM. Scrolling..."
        )

        visible_rows = dialog.locator(
            "div[role=\'row\'][data-id]"
        )

        if visible_rows.count() == 0:
            break

        visible_rows.last.scroll_into_view_if_needed()

        page.wait_for_timeout(300)

        retry += 1

    # ---------------------------------------------------------------
    # Skip if still not found
    # ---------------------------------------------------------------

    if row_locator.count() == 0:
        print(
            f"Row {row_index} could not be loaded"
        )
        continue

    row = row_locator.first

    row.scroll_into_view_if_needed()

    # ---------------------------------------------------------------
    # Read correct LBS fields
    # ---------------------------------------------------------------

    try:

        stock_on_so = row.locator(
            "[data-field=\'stockOnSoLBS\']"
        ).inner_text().strip()

        actual_yard = row.locator(
            "[data-field=\'actualYardStockLBS\']"
        ).inner_text().strip()

        print(
            "StockOnSoLBS:",
            stock_on_so
        )

        print(
            "ActualYardStockLBS:",
            actual_yard
        )

        # Remove commas before conversion
        stock_on_so_val = float(
            stock_on_so.replace(",", "")
        )

        actual_yard_val = float(
            actual_yard.replace(",", "")
        )

    except Exception as e:

        print(
            f"Failed reading row {row_index}:",
            e
        )

        continue

    # ---------------------------------------------------------------
    # Apply condition
    # Stock on S/O = 0
    # Actual Yard Stock > 1
    # ---------------------------------------------------------------

    if (
        stock_on_so_val == 0
        and actual_yard_val > 1
    ):

        print(
            f"Matching row found at index {row_index}"
        )

        checkbox = row.locator(
            "input[type=\'checkbox\'][aria-label=\'Select row\']"
        )

        expect(checkbox).to_be_visible()

        checkbox.scroll_into_view_if_needed()

        checkbox.click(force=True)

        selected = True

        print(
            f"Row {row_index} selected successfully."
        )

        break

# -------------------------------------------------------------------
# FINAL VALIDATION
# -------------------------------------------------------------------

if not selected:

    raise Exception(
        "No matching row found: "
        "StockOnSoLBS == 0 and "
        "ActualYardStockLBS > 1"
    )

print("Matching row selected successfully.")','import re
