    new_in_this_pass = 0

    for i in range(count):
        row = rows.nth(i)
        data_id = row.get_attribute("data-id")
        if data_id is None or data_id in seen_ids:
            continue
        seen_ids.add(data_id)
        new_in_this_pass += 1

        so_cell = row.locator(\'[data-field="StockOnSoPCS"]\')
        yard_cell = row.locator(\'[data-field="actualYardStockPCS"]\')
        if so_cell.count() == 0 or yard_cell.count() == 0:
            continue

        so_val = parse_num(so_cell.get_attribute("title"))
        yard_val = parse_num(yard_cell.get_attribute("title"))
        if so_val is None or yard_val is None:
            continue

        print(f"  data-id={data_id}  SO={so_val}  Yard={yard_val}")

        if so_val < yard_val:
            found_data_id = data_id
            id_cell = row.locator(\'[data-field="idCol"]\')
            found_product_id = (
                id_cell.get_attribute("title") or id_cell.inner_text()
            ).strip()
            break

    if found_data_id is not None:
        break

    info = scroll_info()
    print(f"scroll top={info[\'top\']} max={info[\'max\']} new={new_in_this_pass} seen={len(seen_ids)}")

    if new_in_this_pass == 0:
        stale_scrolls += 1
    else:
        stale_scrolls = 0

    if info["top"] >= info["max"] - 1 or stale_scrolls >= MAX_STALE:
        print("reached bottom or no new rows after scrolling")
        break

    scroll_by(SCROLL_STEP)
    page.wait_for_timeout(500)

assert found_data_id is not None, "No row found where Stock on S/O (PCS) < Actual Yard Stock (PCS)"

set_var("rowProductId", found_product_id)
print("Matched product:", found_product_id, "data-id:", found_data_id)

target_row = page.locator(f\'div[role="row"][data-id="{found_data_id}"]\')

if target_row.count() == 0:
    scroll_to_top()
    page.wait_for_timeout(500)
    while target_row.count() == 0:
        before = scrollbar_v.evaluate("el => el.scrollTop")
        scroll_by(SCROLL_STEP)
        page.wait_for_timeout(500)
        after = scrollbar_v.evaluate("el => el.scrollTop")
        if after == before:
            break

target_row.scroll_into_view_if_needed()
page.wait_for_timeout(300)
